    ["02-10"] = {steps={[1]={npc="Xafetim Manigiro", tgt="Xafetim Manigiro"}, [2]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [3]={node="Auberdine"}, [4]={hint="Colete 6 Patas de Rastejante e coloque-as na Caixazorra 827.", desc="Colete pernas dos caranguejos de nível 9-10 na costa ao sul de Auberdine. Se ainda não tiver a missão da criatura encalhada, aceite-a na próxima passagem pelas docas a partir do nível 11."}, [5]={hint="Obtenha Ossos de Criaturas Marinhas da criatura marinha encalhada logo ao sul Auberdine e leve para Gwennyth Bly'Leggonde em Auberdine."}, [6]={npc="Caixazorra 827", npcObj=true}, [7]={npc="Caixazorra 827", npcObj=true}, [8]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [9]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [10]={hint="Leve 8 cargas de Minério de Elunita e o Medalhão de Elura para Elanaria em Darnassus."}, [11]={npc="Cerellean Garralva", tgt="Cerellean Garralva"}, [12]={hint="Recupere a Carcaça de Tartaruga Marinha da Tartaruga Marinha Descarnada nas águas a oeste de Auberdine, e então fale com Gwennyth Bly'Leggonde em Auberdine."}, [13]={hint="Recolha 3 Olhos de Mangual dos Manguais da Costa Negra no fundo do mar, perto da Caixazorra 411."}, [14]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [15]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [16]={npc="Tharnariun Tratárvore", tgt="Tharnariun Tratárvore"}, [17]={npc="Terenthis", tgt="Terenthis"}, [18]={hint="Capture um ursocardo raivoso e traga de volta para Tharnariun."}, [19]={hint="Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui."}, [20]={npc="Astérion", tgt="Astérion"}, [21]={npc="Astérion", tgt="Astérion"}, [22]={hint="Consiga 8 Brinco de Capeta para Astérion em Bashal'Aran."}, [23]={npc="Astérion", tgt="Astérion"}, [24]={npc="Astérion", tgt="Astérion"}, [25]={hint="Obtenha o Selo Antigo de Pedra-da