    ["02-11"] = {steps={[1]={node="Stormwind"}, [2]={npc="Ilsa Cletes", tgt="Ilsa Cletes", tag="Opcional", desc="A missão introdutória é opcional: vá direto a Ari Barbotina em Ventobravo e aceite Bartolino, o bebum."}, [3]={npc="Ari Barbotina", tgt="Ari Barbotina", tag="Opcional", desc="A missão introdutória é opcional: vá direto a Ari Barbotina em Ventobravo e aceite Bartolino, o bebum."}, [4]={npc="Ari Barbotina", tgt="Ari Barbotina"}, [5]={npc="Bartolino", tgt="Bartolino"}, [6]={npc="Bartolino", tgt="Bartolino", desc="Fale com Bartolino e ele vai atacar. Lute até ele se render."}, [7]={hint="Vença o Bartolino e converse com ele.", desc="Fale com Bartolino e ele vai atacar. Lute até ele se render."}, [8]={npc="Bartolino", tgt="Bartolino", desc="Fale com Bartolino e ele vai atacar. Lute até ele se render."}, [9]={npc="Bartolino", tgt="Bartolino"}, [10]={npc="Ari Barbotina", tgt="Ari Barbotina"}, [11]={npc="Ari Barbotina", tgt="Ari Barbotina"}, [12]={npc="Delegado Fadigas", tgt="Delegado Fadigas"}, [13]={npc="Delegado Fadigas", tgt="Delegado Fadigas", desc="Diogo Dente-podre fica no acampamento ao norte da Madeireira Vale do Leste, na Floresta de Elwynn."}, [14]={hint="Recupere o Distintivo do Fadigas que está no acampamento de Diogo Dente-podre e fale novamente com o Delegado Fadigas.", desc="Diogo Dente-podre fica no acampamento ao norte da Madeireira Vale do Leste, na Floresta de Elwynn."}, [15]={npc="Delegado Fadigas", tgt="Delegado Fadigas", desc="Diogo Dente-podre fica no acampamento ao norte da Madeireira Vale do Leste, na Floresta de Elwynn."}, [16]={text="Da Madeireira Vale do Leste, siga a estrada da Floresta de Elwynn para o oeste, passe pela Vila d'Ouro e atravesse a ponte para entrar em Cerro Oeste."}, [17]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante"}, [18]={npc="Rêmulo Marcos", tgt="Rêmulo Marcos", tag="Opcional", desc="Missão introdutória dos humanos na Vila d'Ouro. Pode ir direto a Gakin, o Neromante, e aceitar a Surena Caledon."}, [19]={npc=