    ["05-d1"] = {name="Salão dos Thanes", entrance="Altaforja 27.63, 47.83", pickup="Ao passar por Dun Morogh e Loch Modan, pegue primeiro as missões pré-masmorra; não precisa voltar de propósito logo antes de entrar. Os Skyborne pulam a {s:01-9}: na primeira vez em Altaforja, vá para o leste, até Dun Morogh, procure o Vidente da Terra Farsen, faça Vigília de Farsen, Cortando o mal pela raiz e Mapa subterrâneo e volte para Altaforja. Se não quiser fazer o desvio, pule Incursão à Antiga Altaforja.", pickupS={{"Ao passar por Dun Morogh e Loch Modan, pegue primeiro as missões pré-masmorra; não precisa voltar de propósito logo antes de entrar"}, {"Os Skyborne pulam a {s:01-9}: na primeira vez em Altaforja, vá para o leste, até Dun Morogh, procure o Vidente da Terra Farsen, faça Vigília de Farsen, Cortando o mal pela raiz e Mapa subterrâneo e volte para Altaforja", {race={"Skyborne"}}}, {"Se não quiser fazer o desvio, pule Incursão à Antiga Altaforja"}}, steps={[1]={npc="Mapa Ferro Negro", npcObj=true, tag="Pré-requisito de masmorra"}, [2]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen", tag="Pré-requisito de masmorra"}, [3]={npc="Vidente da Terra Farsen", tgt="Vidente da Terra Farsen"}, [4]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [5]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [6]={text="Entrada: Salão dos Thanes"}, [7]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [8]={hint="Dê descanso ao espírito de Faldrim Sidermar e depois fale novamente com a Atendente Fantasmagórica no Salão dos Thanes."}, [9]={npc="Ghostly Attendant", tgt="Ghostly Attendant"}, [10]={hint="Mate 15 Aparições Enfurecidas, 10 Almas Atormentadas e dê descanso ao espírito de Sidermar."}, [11]={hint="Colete 8 Heranças Enânicas no Salão dos Thanes."}, [12]={hint="Adentre o Salão dos Thanes abaixo da Antiga Altaforja e corte a cabeça de Durgen Martelúgubre."}, [13]={npc="Treaty of Understanding", npcObj=true, desc="Clique com o botão direito em Tratado de Entendimento na bolsa para aceitar a missão. O chefe final usa Medo com cerca de 35% de vida. Limpe os lacaios primeiro e depois puxe o chefe para a sala anterior. Ao lado de quem dá a missão há uma alavanca. Puxe para abrir a porta e saia em linha reta."}, [14]={npc="Tom Mão-leve", tgt="Tom Mão-leve"}, [15]={npc="Afadra Dunwall", tgt="Afadra Dunwall"}, [16]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}, [17]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}}},
    ["02-12"] = {steps={[1]={npc="Grif Trovino", tgt="Grif Trovino"}, [2]={node="Altaforja"}, [3]={to="Thelsamar", toA="{a:144}"}, [4]={text="Saia de Altaforja e siga a estrada para leste, atravesse o túnel da passagem oriental até Loch Modan e depois siga a estrada para nordeste até Thelsamar.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [5]={nodeA="{a:144}", node="Thelsamar"}, [6]={npc="Montanhista Kadrell", tgt="Montanhista Kadrell", desc="Montanhista Kadrell vai e volta pela estrada de Thelsamar (32.6, 49.7 a 36.8, 42.0). Se não estiver aqui, siga a estrada."}, [7]={npc="Montanhista Ylva", tgt="Montanhista Ylva"}, [8]={hint="O Montanhista Cascalhaça, da torre de guarda sul, quer que você mate 10 Batecrânios Lascapedra e 10 Videntes Lascapedra e fale novamente com ele."}, [9]={hint="Erga o estandarte de Altaforja, chame o trogg Rachacrânio, mate-o, e depois fale com o Capitão Balbúrdia."}, [10]={npc="Montanhista Cascalhaça", tgt="Montanhista Cascalhaça"}, [11]={npc="Montanhista Batemuro", tgt="Montanhista Batemuro"}, [12]={hint="Montanhista Batemuro na torre de vigia sul quer que você mate 10 Xamãs Lascapedra and 10 Quebraossos Lascapedra."}, [13]={npc="Montanhista Batemuro", tgt="Montanhista Batemuro"}, [14]={npc="Capitão Balbúrdia", tgt="Capitão Balbúrdia"}, [15]={hint="Leve o Símbolo da Vida e ressuscite Narm Faulk em Dun Morogh."}, [16]={npc="Narm Faulk", tgt="Narm Faulk"}, [17]={npc="Narm Faulk", tgt="Narm Faulk"}, [18]={hint="Obtenha uma Carta de Ferro Negro com os anões Ferro Negro perto do Lago Helm e fale novamente com Muiredon Beloforja em Altaforja."}, [19]={npc="Muiredon Beloforja", tgt="Muiredon Beloforja"}, [20]={npc="Muiredon Beloforja", tgt="Muiredon Beloforja", desc="Entregue a missão para aprender Redenção."}, [21]={npc="Tiza Beloforja", tgt="Tiza Beloforja", desc="Entregue a missão para aprender Redenção."}, [22]={npc="Jern Elmocorno", tgt="Jern Elmocorno"}, [23]={npc="Brock Buscapedra", tgt="Brock Buscapedra"}, [24]=