54]={to="Auberdine", from="Stormwind", desc="Embarque no cais do porto de Ventobravo."}}},
    ["02-13"] = {steps={[1]={npc="Gubber Blump", tgt="Gubber Blump"}, [2]={npc="PROCURA-SE: Lodofundo!", npcObj=true}, [3]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [4]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [5]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [6]={npc="Gorbold Manácero", tgt="Gorbold Manácero"}, [7]={npc="Gorbold Manácero", tgt="Gorbold Manácero"}, [8]={npc="Gershala Umbrurmúrio", tgt="Gershala Umbrurmúrio"}, [9]={npc="Terenthis", tgt="Terenthis"}, [10]={npc="Terenthis", tgt="Terenthis"}, [11]={npc="Cristal Vermelho Misterioso", npcObj=true}, [12]={npc="Cristal Vermelho Misterioso", npcObj=true}, [13]={npc="Astérion", tgt="Astérion"}, [14]={npc="Criatura Marinha Encalhada", npcObj=true}, [15]={hint="Recupere o Baú do Aurora de Prata e o Baú do Véu das Brumas para Gorbold Manácero em Auberdine. Os dois itens podem ser encontrados nos destroços dos navios a norte da aldeia."}, [16]={npc="Caixazorra 411", npcObj=true}, [17]={npc="Caixazorra 411", npcObj=true}, [18]={npc="Tartaruga Marinha Encalhada", npcObj=true}, [19]={text="Pule no rio aqui e nade até o poço embaixo da cachoeira. Daqui em diante, mate os Espreitalunas Raquíticos e Ursocardos Raivosos que encontrar."}, [20]={hint="Vá para o norte de Auberdine até a primeira queda d'água ao longo do Rio Fontescarpa e consiga uma amostra do charco."}, [21]={hint="Recolha 6 Pedaços Delicados de Caranguejo para Gubber Blump em Auberdine."}, [22]={npc="Tartaruga Marinha Encalhada", npcObj=true}, [23]={npc="Balthule Umbrataque", tgt="Balthule Umbrataque"}, [24]={npc="Balthule Umbrataque", tgt="Balthule Umbrataque"}, [25]={hint="Colete 4 Pergaminhos Gastos para Balthule Umbrataque, perto da Torre de Althalaxx."}, [26]={npc="Balthule Umbrataque", tgt="Balthule Umbrataque"}, [27]={npc="Balthule Umbrataque", tgt="Balthule Umbrataque"}, [28]={hint="Purifique a floresta matando 20 Ursocardos Raivosos e fale novamente com Tharnariun Tratárvore na Costa Negra."}, [29]={hint="Recolha 6 Presas de Espreitaluna e deposite-as na Caixazorra 323."}, [30]={hint="Leve 5 Galhos de Piolho e 1 Cogumelo-cicuta para Barithras Sombraluna, em Auberdine."}, [31]={npc="Caixazorra 323", npcObj=true}, [32]={npc="Caixazorra 323", npcObj=true}, [33]={npc="Tharnariun Tratárvore", tgt="Tharnariun Tratárvore"}, [34]={npc="Tharnariun Tratárvore", tgt="Tharnariun Tratárvore"}, [35]={npc="Gorbold Manácero", tgt="Gorbold Manácero"}, [36]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [37]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [38]={npc="Sentinela Glynda Nal'Shea", tgt="Sentinela Glynda Nal'Shea"}, [39]={npc="Barithras Sombraluna", tgt="Barithras Sombraluna", desc="Encha a Bacia de Limpeza Vazia no poço lunar."}, [40]={npc="Barithras Sombraluna", tgt="Barithras Sombraluna"}, [41]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [42]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [43]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [44]={npc="Gubber Blump", tgt="Gubber Blump"}, [45]={npc="Criatura Marinha Encalhada", npcObj=true}, [46]={npc="Criatura Marinha Encalhada", npcObj=true, desc="O evento só começa perto da fogueira. Faça agora ou quando a rota passar por aqui de novo."}, [47]={npc="Tartaruga Marinha Encalhada", npcObj=true}, [48]={npc="Tartaruga Marinha Encalhada", npcObj=true}, [49]={npc="Criatura Marinha Encalhada", npcObj=true}, [50]={npc="Sentinela Aynasha", tgt="Sentinela Aynasha", desc="A caminho da próxima missão, mate todo Espreitaluna Macho que encontrar (os filhotes e a matriarca vêm junto)."}, [51]={hint="Proteja a Sentinela Aynasha. Em seguida, fale com Onaeya no Entreposto de Maestra, que fica no Vale Gris."}, [52]={npc="Onu", tgt="Onu"}, [53]={npc="Onu", tgt="Onu"}, [54]={npc="Bacia de Vidência", npcObj=true, desc="Vá até 39.2, 86.9 e use o frasco que Onu deu para colocá-lo no chão."}, [55]={npc="Bacia de Vidência", npcObj=true}, [56]={npc="Tomo do Crepúsculo", npcObj=true}, [57]={npc="Tomo do Crepúsculo", npcObj=true}, [58]={npc="Tomo do Crepúsculo", npcObj=true}, [59]={hint="Obtenha um Olho Sem Igual de um Discípulo ou Capanga do Crepúsculo na Glaive do Mestre, na Costa Negra, e encontre alguém em Auberdine que esteja disposto a ficar com ele."}, [60]={npc="Therylune", tgt="Therylune", desc="Missão de escolta: em grupo, espere todos estarem no mesmo ponto antes de aceitar e desligue o aceite automático."}, [61]={hint="Ajude Therylune a escapar e, depois, conte a Therysil, no Altar de Aessina, que a irmã dela está a salvo."}, [62]={npc="Livro: Os Poderes de Baixo", npcObj=true, tag="Opcional", desc="Clique com o botão direito em Livro: Os Poderes de Baixo na bolsa para iniciar a missão. Os monstros do fosso têm pouca chance de derrubar \"Livro: Os Poderes de Baixo\". Só aceite se cair."}, [63]={npc="Prospector Trilheiro", tgt="Prospector Trilheiro", desc="Missão de escolta: em grupo, espere todos estarem no mesmo ponto antes de aceitar e desligue o aceite automático. Deixe o Prospector Trilheiro ir na frente e só lute com os monstros que o atacarem primeiro."}, [64]={npc="Prospector Trilheiro", tgt="Prospector Trilheiro"}, [65]={hint="Proteja o Prospector Trilheiro enquanto ele procura o fóssil misterioso, depois fale novamente com a Arqueóloga Hollee em Auberdine."}, [66]={hint="Recolha 4 Escalpos Grisalhos dos Ursocardos Grisalhos ao sul de Auberdine e deposite-os na Caixazorra 525."}, [67]={npc="Caixazorra 525", npcObj=true}, [68]={hint="Encontre 5 Pelagens de Espreitaluna Finas e leve-as para Terenthis, em Auberdine."}, [69]={npc="Onu", tgt="Onu"}, [70]={npc="Onu", tgt="Onu"}, [71]={npc="Arbal", tgt="Arbal"}, [72]={hint="Encontre e mate o murloc conhecido como Lodofundo. Acredita-se que a criatura esteja defendendo as tendas dos murlocs ao sul de Auberdine, ao longo da costa.", desc="Vêm várias ondas de murlocs, 2-3 por onda. Afaste o último murloc de cada onda da fogueira antes de matá-lo, coma e beba e só então puxe a próxima. Ou procure um grupo."}, [73]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [74]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [75]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [76]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [77]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [78]={npc="Gwennyth Bly'Leggonde", tgt="Gwennyth Bly'Leggonde"}, [79]={npc="Sentinela Glynda Nal'Shea", tgt="Sentinela Glynda Nal'Shea"}, [80]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [81]={npc="Arqueóloga Hollee", tgt="Arqueóloga Hollee"}, [82]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento"}, [83]={npc="Terenthis", tgt="Terenthis"}, [84]={npc="Terenthis", tgt="Terenthis"}, [85]={to="Rut'theran Village", toA="{a:702}", from="Auberdine"}, [86]={to="Rut'theran Village", toA="{a:702}"}, [87]={npc="Nessa Cantonegro", tgt="Nessa Cantonegro"}, [88]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus."}, [89]={npc="Arqueólogo-chefe Suiçagris", tgt="Arqueólogo-chefe Suiçagris"}, [90]={npc="Arqueólogo-chefe Suiçagris", tgt="Arqueólogo-chefe Suiçagris"}, [91]={npc="Elanaria", tgt="Elanaria"}, [92]={npc="Elanaria", tgt="Elanaria"}, [93]={npc="Mathiel", tgt="Mathiel"}, [94]={npc="Mathiel", tgt="Mathiel", desc="Recompensa: uma arma de elunita."}, [95]={npc="Mathiel", tgt="Mathiel", desc="Recompensa: uma arma de elunita."}, [96]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus", desc="Depois de concluir \"Corpo e coração\" na Pedra Luniscante de Auberdine, volte a Darnassus para entregar e aprender Forma de Urso."}, [97]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus", tag="Você já pode comprar na casa de leilões (ou pedir para um alt enviar) 5 × Raiz-telúrica (para Colhendo a cura, mais tarde)."}, [98]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [99]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [100]={hint="Use o Coletor Vazio das Quedas de Fontescarpa para coletar uma amostra de água da entrada da caverna da cachoeira.", desc="Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran e depois voe para Auberdine."}, [101]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto"}, [102]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine. Raiz-telúrica ×5: dá para comprar na casa de leilões."}, [103]={hint="Leve 5 Raízes-telúricas e 12 Fungos Lunares para Alanndária Noturcanto em Auberdine para que ela possa preparar o bálsamo curativo.", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine."}, [104]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Colete Raiz-telúrica e Fungo Lunar na Costa Negra e entregue em Auberdine."}, [105]={npc="Alanndária Noturcanto", tgt="Alanndária Noturcanto", desc="Use o remédio nos cervos doentes da Costa Negra."}, [106]={hint="Use o Bálsamo Curativo para Animais em 10 Cervos Adoentados espalhados pela Costa Negra. Isso deve curá-los. Cervos Adoentados foram avistados da região ao sul do Rio Fontescarpa, seguindo até a área ao norte de Auberdine, até a Costa Negra meridional, na fronteira do Vale Gris.", desc="Use o remédio nos cervos doentes da Costa Negra."}, [107]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Depois de curar 10 cervos, use Teleporte: Clareira da Lua para voltar e entregar."}, [108]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Entregue a missão para aprender Curar Veneno."}, [109]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus", desc="Entregue a missão para aprender Curar Veneno. Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran e use o portal da vila para entrar em Darnassus."}, [110]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus"}, [111]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [112]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Encontre o Adorno de Altar no fundo do Lago Eluna'ara."}, [113]={hint="Encontre um Adorno de Altar no Lago Eluna'ara e leve-o para o Santuário de Remulos, na parte noroeste da Clareira da Lua. Use o Adorno de Altar lá dentro.", desc="Encontre o Adorno de Altar no fundo do Lago Eluna'ara."}, [114]={npc="Tajarri", tgt="Tajarri", desc="Encontre o Adorno de Altar no fundo do Lago Eluna'ara."}, [115]={npc="Tajarri", tgt="Tajarri", desc="Os dois baús trancados estranhos guardam cada um metade de um pingente: um está no fundo do mar ao norte de Auberdine, na Costa Negra, e o outro no fundo do mar ao largo da costa noroeste de Cerro Oeste."}, [116]={hint="Encontre o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática. Fale com os residentes da Clareira da Lua para obter pistas de onde esse itens podem estar.", desc="Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran, voe para Auberdine e nade para o norte até o baú trancado no fundo do mar. Depois pegue o barco de Auberdine para Ventobravo, voe para o Morro da Sentinela e vá para o noroeste, até a costa, e mergulhe para abrir o outro baú trancado."}, [117]={text="Com as duas metades, use Teleporte: Clareira da Lua para voltar e juntar as metades do pingente perto do Santuário de Remulos."}, [118]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [119]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor", desc="Entregue a missão para aprender Forma Aquática."}, [120]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus", desc="Entregue a missão para aprender Forma Aquática. Pegue o voo exclusivo de druidas de Refúgio Noturno até a Vila de Rut'theran e use o portal da vila para entrar em Darnassus."}, [121]={text="Entre no portal de Darnassus para voltar à Vila de Rut'theran."}, [122]={nodeA="{a:702}", node="Rut'theran Village"}, [123]={to="Auberdine"}, [124]={hint="Encontre e mate a Matriarca do Covil."}, [125]={hint="Encha a Bacia de Limpeza Vazia no Poço Lunar de Auberdine."}, [126]={hint="Leve 6 Relíquias de Mathistra para Onu no Bosque dos Ancientes."}, [127]={hint="Elimine 12 Mirmidões Escamarraio, 8 Feiticeiras Escamarraio e 6 Guerreiros Escamarraio para Arbal no Bosque dos Ancientes."}, [128]={hint="Encontre uma Senhora das Feras Escamarraio, mate-a e traga de volta seu Bastão do Domínio Profundo."}, [129]={}}},
    ["05-d2"] = {name="Ruínas de Lordaeron", entrance="Cidade Baixa 72.41, 11.37", steps={[1]={text="Opcional e distante: a entrada fica nas Ruínas de Lordaeron, acima da Cidade Baixa, e é preciso atravessar território da Horda. De Auberdine, vá primeiro de barco ao Porto de Menethil e siga pela rota marítima do norte até Costa Sul. Desça ali e descubra o ponto de voo; depois vá para o norte pelo Contraforte de Eira dos Montes e pela Floresta de Pinhaprata até as Clareiras de Tirisfal. Ao sair da masmorra, use a pedra de regresso para voltar a Ventobravo e retome a {s:02-14}.", tag="Opcional"}, [2]={text="Entrada: Ruínas de Lordaeron"}, [3]={}, [4]={npc="Insígnia Ensanguentada", npcObj=true, tag="Aceite se cair, Opcional", desc="Clique com o botão direito em Insígnia Ensanguentada na bolsa para iniciar a missão."}, [5]={hint="Colete 10 Insígnias Ensanguentadas e leve-as ao General Marcus Jonas em Ventobravo.", tag="Opcional"}, [6]={npc="Escudo de Lordaeron", npcObj=true, desc="Clique com o botão direito em Escudo de Lordaeron na bolsa para iniciar a missão."}, [7]={npc="Blood-Stained Parchment", npcObj=true, desc="Clique com o botão direito em Pergaminho Manchado de Sangue na bolsa para aceitar a missão."}, [8]={}, [9]={npc="Matriarca Ananéri", tgt="Matriarca Ananéri"}, [10]={npc="Lady Dina Cápita", tgt="Lady Dina Cápita"}, [11]={npc="General Marcus Jonas", tgt="General Marcus Jonas", tag="Opcional"}}},
    ["02-14"] = {grind={[1]={mob="Esmagador de Cristarrubra", note="Acampamento dos gnolls ao norte de Vila Plácida; monstros comuns, perto do ponto de voo."}, [2]={mob="Vanguardeiro Rocha Negra", note="Orcs Rocha Negra na margem nordeste do Lago Plácido; nível mais adequado, com Brutos misturados, então puxe pela borda."}}, steps={[1]={npc="Renzik The Shiv", tgt="Renzik The Shiv"}, [2]={npc="Alta-sacerdotisa Laurena", tgt="Alta-sacerdotisa Laurena", desc="Aceite em Ventobravo, entregue em Altaforja e aprenda Proteção contra Medo."}, [3]={npc="Sumo Sacerdote Rohan", tgt="Sumo Sacerdote Rohan", desc="Aceite em Ventobravo, entregue em Altaforja e aprenda Proteção contra Medo."}, [4]={text="Pegue o Metrô Correfundo em Altaforja de volta para Ventobravo."}, [5]={npc="Alta-sacerdotisa Laurena", tgt="Alta-sacerdotisa Laurena", desc="Aceite em Ventobravo e entregue em Dun Morogh."}, [6]={npc="Alta-sacerdotisa Mims", tgt="Alta-sacerdotisa Mims", desc="Aceite em Ventobravo e entregue em Dun Morogh."}, [7]={text="Volte a Altaforja e pegue o Metrô Correfundo para Ventobravo."}, [8]={npc="Jana Catão", tgt="Jana Catão", desc="A taverna Recôndito Azulego fica no Distrito dos Magos de Ventobravo."}, [9]={componentNpc="Aparição Etérea", hint="Use o encantamento na taverna do Recôndito Azulego, no Distrito dos Magos de Ventobravo. Enfraqueça a criatura da fenda até atordoá-la, use o baú e saqueie o cofre no chão. Recolha três.", desc="A taverna Recôndito Azulego fica no Distrito dos Magos de Ventobravo."}, [10]={npc="Jana Catão", tgt="Jana Catão", desc="A taverna Recôndito Azulego fica no Distrito dos Magos de Ventobravo."}, [11]={npc="Jana Catão", tgt="Jana Catão", desc="Separe 10 × Linho e 6 × Gema Energizada da Fenda. Quando voltar a Loch Modan, entre na mina pelo norte (perto de 35.9,18.2) e abra os caixotes dos mineradores. Siga a rota enquanto faltar material. Procure Wynne em Ventobravo quando o registro confirmar a entrega."}, [12]={npc="Manoela Galante", tgt="Manoela Galante", desc="Separe 10 × Linho e 6 × Gema Energizada da Fenda. Quando voltar a Loch Modan, entre na mina pelo norte (perto de 35.9,18.2) e abra os caixotes dos mineradores. Siga a rota enquanto faltar material. Procure Wynne em Ventobravo quando o registro confirmar a entrega."}, [13]={npc="Manoela Galante", tgt="Manoela Galante", desc="Recompensa: Veste de fios de mana."}, [14]={npc="Manoela Galante", tgt="Manoela Galante", desc="Recompensa: Veste de fios de mana."}, [15]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante"}, [16]={npc="Takar, o Vidente", tgt="Takar, o Vidente", desc="Pegue o barco do porto de Ventobravo até Auberdine, siga a costa da Costa Negra para o sul até Vale Gris, entre nos Sertões pelo leste, pela Muralha de Mor'shan, e vá para o sul procurar Takar. A Encruzilhada e o Acampamento Taurajo são fortalezas da Horda; contorne-os."}, [17]={npc="Takar, o Vidente", tgt="Takar, o Vidente"}, [18]={npc="Takar, o Vidente", tgt="Takar, o Vidente"}, [19]={hint="Obtenha o Palocórdio no Vale Gris e leve-o a Gakin, o Neromante, no Distrito dos Magos de Ventobravo.", desc="Elimine primeiro os monstros ao lado da árvore e depois clique nessa árvore cenarina para obter palocórdio."}, [20]={hint="Obtenha a Estatueta de Madeira e leve para Gakin, o Neromante, no Distrito dos Magos de Ventobravo."}, [21]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante", desc="Ao terminar Vale Gris, use a pedra de regresso para voltar a Ventobravo. Se a pedra de regresso estiver em recarga, volte ao norte até Auberdine e pegue o barco para Ventobravo."}, [22]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante"}, [23]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante", desc="Use no círculo de evocação ao lado de Gakin, o Neromante, e derrote a súcubo evocada."}, [24]={hint="Usando o Cerne de Palocórdio, evoque e sobrepuje uma súcubo. Em seguida, devolva o Cerne de Palocórdio a Gakin, o Neromante, no Cordeiro Imolado.", desc="Use no círculo de evocação ao lado de Gakin, o Neromante, e derrote a súcubo evocada."}, [25]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante", desc="Use no círculo de evocação ao lado de Gakin, o Neromante, e derrote a súcubo evocada."}, [26]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante"}, [27]={hint="Usando a Estatueta de Madeira, evoque e subjugue um íncubo. Depois, devolva a Estatueta de Madeira para Gakin, o Neromante, no Cordeiro Imolado."}, [28]={npc="Gakin, o Neromante", tgt="Gakin, o Neromante"}, [29]={text="De Ventobravo, siga a estrada da Floresta de Elwynn para o leste; primeiro vá à Torre de Azora e aceite Olho vigilante com Teócrito; depois continue para o leste até a entrada das Montanhas Cristarrubra, procure o Guarda Florestan e siga a estrada até Vila Plácida.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé, Antes de ir para as Montanhas Cristarrubra, você pode comprar na casa de leilões (ou pedir para um alt enviar) 8 × Barbatana de Murloc (para Caçadores de murlocs)."}, [30]={npc="Teócrito", tgt="Teócrito"}, [31]={npc="Guarda Florestan", tgt="Guarda Florestan"}, [32]={to="Lakeshire", toA="{a:69}", tag="Antes de ir para as Montanhas Cristarrubra, você pode comprar na casa de leilões (ou pedir para um alt enviar) 8 × Barbatana de Murloc (para Caçadores de murlocs).", desc="Se ainda não desbloqueou o ponto de voo de Vila Plácida, vá de Ventobravo pela estrada da Floresta de Elwynn para leste até Vila Plácida."}, [33]={npc="Guarda Florestan", tgt="Guarda Florestan", desc="Guarda Florestan fica no cruzamento da estrada principal a oeste de Montanhas Cristarrubra, que leva a Floresta de Elwynn."}, [34]={npc="Darcy", tgt="Darcy"}, [35]={npc="Wiley, o Negro", tgt="Wiley, o Negro"}, [36]={npc="Wiley, o Negro", tgt="Wiley, o Negro"}, [37]={npc="Mestre de Doca Baren", tgt="Mestre de Doca Baren"}, [38]={npc="Mestre de Doca Baren", tgt="Mestre de Doca Baren", desc="Barbatana de Murloc pode ser comprada na casa de leilões. Com 8, não precisa farmar."}, [39]={npc="Magistrado Salomão", tgt="Magistrado Salomão"}, [40]={npc="Vervo Obom", tgt="Vervo Obom"}, [41]={npc="Subdelegado David", tgt="Subdelegado David"}, [42]={npc="Subdelegado David", tgt="Subdelegado David"}, [43]={npc="Subdelegado David", tgt="Subdelegado David"}, [44]={npc="Lucius", tgt="Lucius"}, [45]={npc="Lucius", tgt="Lucius", desc="Use Arrombar no baú perto da Serraria Alther."}, [46]={hint="Abra o Baú do Lucius, recupere o Símbolo de Ladroagem e devolva-o ao Lucius na Vila Plácida.", desc="Use Arrombar no baú perto da Serraria Alther."}, [47]={npc="Lucius", tgt="Lucius", desc="Use Arrombar no baú perto da Serraria Alther."}, [48]={npc="Arantir", tgt="Arantir", tag="Opcional"}, [49]={hint="Saque de: Gath'Ilzogg, Campeão Rocha Negra, Lança-sombras Rocha Negra", tag="Opcional"}, [50]={npc="Arantir", tgt="Arantir", tag="Opcional"}, [51]={nodeA="{a:69}", node="Lakeshire"}, [52]={npc="Yorus Cervevada", tgt="Yorus Cervevada", desc="As Cavernas Retibanas ficam no noroeste das Montanhas Cristarrubra e estão cheias de ogros."}, [53]={npc="Yorus Cervevada", tgt="Yorus Cervevada", desc="As Cavernas Retibanas ficam no noroeste das Montanhas Cristarrubra e estão cheias de ogros."}, [54]={npc="Yorus Cervevada", tgt="Yorus Cervevada"}, [55]={desc="Se ainda não estiver no nível 21 antes de sair das Montanhas Cristarrubra, vá ao acampamento dos gnolls ao norte de Vila Plácida e mate Esmagadores de Cristarrubra até o 21."}, [56]={to="Sentinel Hill", toA="{a:108}"}, [57]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [58]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [59]={to="Stormwind"}, [60]={npc="Alta-sacerdotisa Laurena", tgt="Alta-sacerdotisa Laurena", desc="Aprenda Retroalimentação."}, [61]={npc="Alta-sacerdotisa Laurena", tgt="Alta-sacerdotisa Laurena", desc="Aprenda Retroalimentação."}, [63]={npc="General Marcus Jonas", tgt="General Marcus Jonas"}, [64]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [65]={npc="Furen Barbalonga", tgt="Furen Barbalonga", tag="Faça se aguentar mobs de nível mais alto, Grupo recomendado, Opcional"}, [66]={hint="Colete as matérias-primas pedidas por Furen Barbalonga e leve-as para ele em Ventobravo.", tag="Faça se aguentar mobs de nível mais alto, Grupo recomendado, Opcional"}, [67]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [68]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [69]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [70]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [71]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [72]={npc="Furen Barbalonga", tgt="Furen Barbalonga"}, [74]={npc="General Marcus Jonas", tgt="General Marcus Jonas"}, [75]={npc="Ferreiro Argus", tgt="Ferreiro Argus"}, [76]={npc="Ferreiro Argus", tgt="Ferreiro Argus"}, [77]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw"}, [78]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw"}, [79]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw"}, [80]={to="Sentinel Hill", toA="{a:108}"}, [81]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [82]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [83]={npc="Alba Belua", tgt="Alba Belua", desc="Se você não a pegou em Cerro Oeste, pegue-a no Morro da Sentinela antes de perseguir o mensageiro."}, [84]={hint="Rastreie o Mensageiro Défias no Cerro Oeste e leve sua mensagem para Mantoforte."}, [85]={hint="Colete 8 Suprimentos Industriais Suspeitos no Arroio da Lua.", desc="Caixas de suprimentos que faltaram em Cerro Oeste: pegue-as em Arroio da Lua enquanto persegue o mensageiro."}, [86]={npc="Alba Belua", tgt="Alba Belua"}, [87]={npc="Alba Belua", tgt="Alba Belua"}, [88]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [89]={npc="Traidor Défias", tgt="Traidor Défias"}, [90]={hint="Escolte o Traidor Défias ao esconderijo secreto da Irmandade Défias. Quando o Traidor Défias mostrar onde VanCleef e seus comparsas estão escondidos, retorne a Miguel Mantoforte com a informação.", tag="Escolta", desc="Siga o traidor Défias até Arroio da Lua; os monstros no caminho o atacam, então ajude-o. Ao chegar, volte para Morro da Sentinela."}, [91]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [92]={npc="Agente Marta Hari", tgt="Agente Marta Hari"}, [93]={npc="Agente Marta Hari", tgt="Agente Marta Hari", desc="Roube a carta lacrada da Torre Défias no Cerro Oeste. Depois, aprenda Venenos."}, [94]={hint="Roube a chave, entre na Torre Défias e descubra o que tem dentro do Baú da Floresta do Crepúsculo. Leve todas as informações que coletar para Mathias Shaw em Ventobravo. Consulte o Diário de Marta se quiser mais detalhes sobre a torre.", desc="Roube a carta lacrada da Torre Défias no Cerro Oeste. Depois, aprenda Venenos."}, [95]={npc="Carta Não Enviada", npcObj=true, tag="Aceite se cair", desc="Cai do VanCleef nas Minas Mortas: clique com o botão direito para aceitar a missão."}, [96]={}, [97]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", desc="Roube a carta lacrada da Torre Défias no Cerro Oeste. Depois, aprenda Venenos."}, [98]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Opcional"}, [99]={npc="Doutor Mixilpixil", tgt="Doutor Mixilpixil", tag="Opcional"}, [100]={npc="Doutor Mixilpixil", tgt="Doutor Mixilpixil", tag="Opcional"}, [101]={npc="Doutor Mixilpixil", tgt="Doutor Mixilpixil", tag="Opcional"}, [102]={npc="Doutor Mixilpixil", tgt="Doutor Mixilpixil", tag="Opcional", desc="Flores Silvestres Simples e Ampola Chumbada são vendidos por comerciantes. Tubo de Bronze: dá para comprar na casa de leilões. Bobina de Seda Chartreuse Leve fica na alfaiataria dos Canais de Ventobravo."}, [103]={hint="Leve para o Doutor Mixilpixil um pacote de Flores Silvestres Simples, uma Ampola Chumbada, um Tubo de Bronze e uma Bobina de Seda Chartreuse Leve. \"Ite\" nenhuma se cura sozinha, minha jovem.", tag="Opcional"}, [104]={npc="Doutor Mixilpixil", tgt="Doutor Mixilpixil", tag="Opcional"}, [106]={text="Tubo de Bronze", npc="Billibub Rodagiros", desc="Estoque limitado. Só compre se estiver disponível."}, [107]={npc="Lorien Grenagem", tgt="Lorien Grenagem"}, [108]={npc="Baros Aleixo", tgt="Baros Aleixo"}, [109]={npc="Baros Aleixo", tgt="Baros Aleixo"}, [110]={npc="Carcereiro-chefe Thelágua", tgt="Carcereiro-chefe Thelágua"}, [111]={npc="Benedito Brião", tgt="Benedito Brião"}, [112]={npc="Benedito Brião", tgt="Benedito Brião"}, [113]={npc="Tomo de Valor", npcObj=true, desc="Clique com o botão direito em Tomo da Bravura na bolsa para iniciar a missão."}, [114]={npc="Benedito Brião", tgt="Benedito Brião", desc="Clique com o botão direito em Tomo da Bravura na bolsa para iniciar a missão."}, [115]={npc="Benedito Brião", tgt="Benedito Brião"}, [116]={npc="Dafne Calmafonte", tgt="Dafne Calmafonte"}, [117]={npc="Dafne Calmafonte", tgt="Dafne Calmafonte", desc="Escolte Dafne Calmafonte. No caminho, os Défias armam emboscadas."}, [118]={npc="Dafne Calmafonte", tgt="Dafne Calmafonte", desc="Escolte Dafne Calmafonte. No caminho, os Défias armam emboscadas."}, [119]={npc="Dafne Calmafonte", tgt="Dafne Calmafonte"}, [120]={npc="Benedito Brião", tgt="Benedito Brião"}, [121]={npc="Benedito Brião", tgt="Benedito Brião"}, [122]={npc="Jardel Calmafonte", tgt="Jardel Calmafonte"}, [123]={npc="Jardel Calmafonte", tgt="Jardel Calmafonte", desc="Requer materiais como uma Gema Kor e o Carregamento de minério do Bailor."}, [124]={hint="Usando as Anotações do Jardel sobre Armas, encontre Madeira de Carvalho de Pedralva, o Carregamento de Minério Refinado do Bailor, o Martelo de Ferreiro de Jardel e uma Gema Kor. Depois, entregue tudo a Jardel Calmafonte em Altaforja.", desc="Requer materiais como uma Gema Kor e o Carregamento de minério do Bailor."}, [125]={npc="Jardel Calmafonte", tgt="Jardel Calmafonte", desc="Requer materiais como uma Gema Kor e o Carregamento de minério do Bailor."}, [126]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento", tag="Opcional"}, [127]={hint="Leve a Gema Kor para Trovejius Tecevento, na Costa Negra.", tag="Opcional"}, [128]={npc="Trovejius Tecevento", tgt="Trovejius Tecevento", tag="Opcional"}, [129]={npc="Bailor Manopedra", tgt="Bailor Manopedra", tag="Opcional"}, [130]={hint="Leve o Carregamento de Minério do Jardel até Bailor Manopedra, em Loch Modan.", tag="Opcional"}, [131]={npc="Bailor Manopedra", tgt="Bailor Manopedra", tag="Opcional"}, [132]={npc="Jardel Calmafonte", tgt="Jardel Calmafonte"}, [133]={npc="Jardel Calmafonte", tgt="Jardel Calmafonte"}, [134]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [135]={npc="Grimand Elmore", tgt="Grimand Elmore", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [136]={hint="Leve 20 ampolas de Sangue Ardente e 1 Pedra Ardente para Grimand Elmore em Ventobravo.", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [137]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [138]={npc="Grimand Elmore", tgt="Grimand Elmore"}, [139]={npc="Grimand Elmore", tgt="Grimand Elmore"}}},
    ["05-d3"] = {name="Minas Mortas", entrance="Cerro Oeste 42.50, 71.70", pickup="Na primeira visita às Montanhas Cristarrubra, depois de entregar a escolta de volta em Cerro Oeste, pegue a Irmandade Défias e as bandanas de seda vermelha no Morro da Sentinela. Na última volta a Ventobravo, pegue as três missões da cidade, para não fazer uma viagem especial antes da masmorra.", pickupS={{"Na primeira visita às Montanhas Cristarrubra, depois de entregar a escolta de volta em Cerro Oeste, pegue a Irmandade Défias e as bandanas de seda vermelha no Morro da Sentinela"}, {"Na última volta a Ventobravo, pegue as três missões da cidade, para não fazer uma viagem especial antes da masmorra"}}, steps={[1]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [2]={npc="Wiley, o Negro", tgt="Wiley, o Negro", tag="Pré-requisito de masmorra"}, [3]={npc="Wiley, o Negro", tgt="Wiley, o Negro", tag="Pré-requisito de masmorra"}, [4]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [5]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [6]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Pré-requisito de masmorra"}, [7]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Pré-requisito de masmorra"}, [8]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [9]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [10]={hint="Rastreie o Mensageiro Défias no Cerro Oeste e leve sua mensagem para Mantoforte.", tag="Pré-requisito de masmorra"}, [11]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [12]={npc="Traidor Défias", tgt="Traidor Défias", tag="Pré-requisito de masmorra"}, [13]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte", tag="Pré-requisito de masmorra"}, [14]={npc="Miguel Mantoforte", tgt="Miguel Mantoforte"}, [15]={npc="Batedora Riell", tgt="Batedora Riell"}, 