    ["05-d15"] = {name="Caverna Ululante", entrance="Sertões 46.00, 36.30", tips={{k="取捨", text="A lasca faiscante, Encrencas nas docas e Bebidas inteligentes exigem ir a Vila Catraca. A Aliança ainda não desbloqueou Vila Catraca neste ponto, então não estão na lista."}, {k="說明", text="Entre na caverna externa em Oásis das Águas Claras (47.70, 35.00) e siga o túnel até o portal. Pegue primeiro as missões de Nalpak e Ebru na alcova acima da entrada externa.", s={{"Entre na caverna externa em Oásis das Águas Claras (47.70, 35.00) e siga o túnel até o portal"}, {"Pegue primeiro as missões de Nalpak e Ebru na alcova acima da entrada externa"}}}}, steps={[1]={text="Opcional e distante: antes de embarcar em Auberdine, voe de volta a Astranaar. Siga a estrada para o leste, pegue a estrada leste de Vale Gris para o sul passando pela Muralha de Mor'shan até os Sertões e siga a estrada norte para o sul até o oásis a sudoeste da Encruzilhada, onde fica a entrada da caverna. Todo o caminho é território da Horda. Ao sair da masmorra, volte a Astranaar, voe para Auberdine, pegue o barco para o Porto de Menethil e retome a {s:02-21}.", tag="Opcional"}, [2]={npc="Nalpak", tgt="Nalpak"}, [3]={npc="Ebru", tgt="Ebru"}, [4]={text="Entrada: Caverna Ululante"}, [5]={hint="Nalpak na Caverna Ululante quer 20 Pelegos Anormais.", desc="Os Deviate Slayers ficam na caverna externa em frente à entrada da masmorra. Local: Limpe as feras mutantes nas bifurcações rasas e nos dois flancos, coletando couros enquanto avança para os chefes.", spot="Mate as criaturas alteradas na bifurcação rasa e nas duas alas. Pegue os couros enquanto avança pelos chefes."}, [6]={hint="Ebru, na Caverna Ululante, quer que você mate 7 Assoladores Anormais, 7 Víboras Anormais, 7 Trôpegos Anormais e 7 Presáteras Anormais.", desc="Local: Limpe primeiro a bifurcação rasa e complete os quatro tipos de monstros nas alas oeste e leste do canal.", spot="Limpe primeiro a bifurcação rasa e complete os quatro tipos de monstros na