    ["02-17"] = {steps={[1]={to="Lakeshire", toA="{a:69}", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé", desc="Se você já liberou o ponto de voo de Vila Sombria, voe direto para Vila Sombria. Se não, voe até Vila Plácida, siga a estrada para oeste até o cruzamento no lado oeste de Cristarrubra e vá para o sul pela Floresta do Crepúsculo até Vila Sombria."}, [2]={npc="Madame Eva", tgt="Madame Eva", desc="Ao atravessar a Floresta do Crepúsculo, mate aranhas para pegar Pernas de Aranha Pegajosas."}, [3]={npc="Madame Eva", tgt="Madame Eva"}, [4]={npc="Tabelião Azambuja", tgt="Tabelião Azambuja"}, [5]={npc="Tabelião Azambuja", tgt="Tabelião Azambuja"}, [6]={npc="Sirra Von'Indi", tgt="Sirra Von'Indi"}, [7]={npc="Comandante Aldora Ebanez", tgt="Comandante Aldora Ebanez"}, [8]={npc="Elaine Carevino", tgt="Elaine Carevino"}, [9]={npc="Elaine Carevino", tgt="Elaine Carevino"}, [10]={npc="Elaine Carevino", tgt="Elaine Carevino"}, [11]={nodeA="{a:42}", node="Darkshire"}, [12]={text="Tubo de Bronze", desc="Estoque limitado. Só compre se estiver disponível e você ainda não tiver."}, [13]={npc="Vitório Prismado", tgt="Vitório Prismado", desc="A sequência de observar as estrelas precisa de um Tubo de Bronze para começar. Se não tiver, faça as outras partes primeiro e compre depois na Casa de Leilões."}, [14]={npc="Arco de Américo", npcObj=true, tag="Opcional", desc="Clique com o botão direito em Merrick's Bow na bolsa para iniciar a missão."}, [15]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", npcObj=true, tag="Opcional", desc="Clique com o botão direito na Adaga de Íria na mochila para aceitar a missão."}, [16]={npc="Vitório Prismado", tgt="Vitório Prismado"}, [17]={npc="Vitório Prismado", tgt="Vitório Prismado"}, [18]={npc="Maria Cega", tgt="Maria Cega"}, [19]={npc="Maria Cega", tgt="Maria Cega"}, [20]={hint="Recupere o Espelho de Maria do Carniçal Insano e entregue-o a Vitório na Vila Sombria."}, [21]={hint="A Comandante Aldora E