    ["05-d4"] = {name="O Cárcere", entrance="Ventobravo 52.41, 70.01", pickup="Pegue \"Tudo que vai...\" na Vila Plácida e \"Crime e castigo\" na Vila Sombria. Para \"Rebelião no Cárcere\", entregue primeiro a carta de VanCleef. Se você não a tiver, faça as outras missões. Forme um grupo para \"Fúria profunda\" após concluir \"A guerra dos Ferro Negro\" no Pantanal.", pickupS={{"Pegue \"Tudo que vai...\" na Vila Plácida e \"Crime e castigo\" na Vila Sombria"}, {"Para \"Rebelião no Cárcere\", entregue primeiro a carta de VanCleef"}, {"Se você não a tiver, faça as outras missões"}, {"Forme um grupo para \"Fúria profunda\" após concluir \"A guerra dos Ferro Negro\" no Pantanal"}}, steps={[1]={npc="Conselheiro Millstipe", tgt="Conselheiro Millstipe"}, [2]={text="Pré-requisito: Tudo que vai..."}, [3]={npc="Carta Não Enviada", npcObj=true, tag="Aceite se cair", desc="Cai do VanCleef nas Minas Mortas: clique com o botão direito para aceitar a missão."}, [4]={npc="Baros Aleixo", tgt="Baros Aleixo"}, [5]={npc="Baros Aleixo", tgt="Baros Aleixo"}, [6]={npc="Carcereiro-chefe Thelágua", tgt="Carcereiro-chefe Thelágua"}, [7]={npc="Carcereiro-chefe Thelágua", tgt="Carcereiro-chefe Thelágua"}, [8]={npc="Carcereiro-chefe Thelágua", tgt="Carcereiro-chefe Thelágua"}, [9]={npc="Nikova Raskol", tgt="Nikova Raskol"}, [10]={text="Entrada: O Cárcere"}, [11]={hint="O Carcereiro-chefe Thelágua de Ventobravo quer que você mate 10 Défias Prisioneiros, 8 Défias Condenados e 8 Défias Insurgentes em O Cárcere."}, [12]={hint="Mate Basílio Taborda e leve a cabeça dele para o Carcereiro-chefe Thelágua no Cárcere."}, [13]={hint="Nikova Raskol, de Ventobravo, quer que você colete 10 Bandanas Vermelhas de Lã."}, [14]={hint="O Conselheiro Millstipe da Vila Sombria quer que você leve a mão de Flávio Lúcio para ele."}, [15]={hint="Leve a cabeça de Targorr, o Horror para o Guarda Berto em Vila Plácida.", tag="Grupo recomendado, Opcional"}, [16]={hint="Rocio Garmason quer que você leve a cabeça de Kam Funda