    ["05-d5"] = {name="Profundezas Negras", entrance="Vale Gris 14.50, 14.20", pickup="Ao chegar na Costa Negra (2ª visita), pegue primeiro Pesquisar a corrupção. As três missões de Darnassus e Altaforja exigem níveis 18-20; pegue-as ao passar no nível certo.", pickupS={{"Ao chegar na Costa Negra (2ª visita), pegue primeiro Pesquisar a corrupção"}, {"As três missões de Darnassus e Altaforja exigem níveis 18-20; pegue-as ao passar no nível certo"}}, steps={[1]={npc="Gershala Umbrurmúrio", tgt="Gershala Umbrurmúrio"}, [2]={npc="Guarda Argênteo Manados", tgt="Guarda Argênteo Manados", desc="Requer nível 20. Se ainda não tiver o nível ao entrar em Darnassus na {s:02-13}, pegue-a na próxima passagem ou pule."}, [3]={npc="Vigilalva Saedlass", tgt="Vigilalva Saedlass", desc="Requer nível 18; pegue-a de passagem ao entrar em Darnassus na {s:02-13}."}, [4]={npc="Gerrig Agarrosso", tgt="Gerrig Agarrosso", desc="Requer nível 18. Na próxima passagem por Ventobravo, pegue o Metrô Correfundo até Altaforja para aceitar, ou pule se não quiser ir de propósito."}, [5]={text="Entrada: Profundezas Negras"}, [6]={hint="Leve o Manuscrito de Lorgalis para Gerrig Agarrosso na Caverna Esquecida, em Altaforja."}, [7]={hint="Gershala Umbrurmúrio em Auberdine quer 8 Troncos Encefálicos Corrompidos."}, [8]={npc="Guarda Argênteo Thaelrid", tgt="Guarda Argênteo Thaelrid"}, [9]={npc="Guarda Argênteo Thaelrid", tgt="Guarda Argênteo Thaelrid"}, [10]={hint="Leve 10 Pingentes do Crepúsculo para o Guarda Argênteo Manados em Darnassus."}, [11]={hint="Leve a cabeça do Senhor do Crepúsculo Kelris para o Vigilalva Selgorm em Darnassus."}, [12]={npc="Gershala Umbrurmúrio", tgt="Gershala Umbrurmúrio"}, [13]={npc="Guarda Argênteo Manados", tgt="Guarda Argênteo Manados"}, [14]={npc="Vigilalva Selgorm", tgt="Vigilalva Selgorm"}, [15]={npc="Gerrig Agarrosso", tgt="Gerrig Agarrosso"}}},
