    ["03-23"] = {steps={[1]={npc="Irmão Sarmo", tgt="Irmão Sarmo"}, [2]={npc="Shoni, a Shilenchiosa", tgt="Shoni, a Shilenchiosa", tag="Grupo recomendado, Opcional", desc="Missão da masmorra de Gnomeregan; só aceite se for fazer Gnomeregan."}, [3]={to="Menethil Harbor", toA="{a:150}"}, [4]={npc="Sylessa Murmussombra", tgt="Sylessa Murmussombra"}, [5]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [6]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [7]={npc="Primeiro Oficial Simonez", tgt="Primeiro Oficial Simonez"}, [8]={npc="Lépore Barnabé", tgt="Lépore Barnabé"}, [9]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte"}, [10]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte"}, [11]={npc="Baú Encharcado", npcObj=true}, [12]={npc="Baú Encharcado", npcObj=true}, [13]={hint="Recupere a Nord'el para Sylessa Murmussombra no Porto de Menethil."}, [14]={npc="Sylessa Murmussombra", tgt="Sylessa Murmussombra"}, [15]={hint="Colete 5 Lingotes da Forja de Luz e fale novamente com Glorin Testaço no Pantanal."}, [16]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [17]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [18]={hint="Mate 13 Marinheiros Amaldiçoados, 5 Fuzileiros Amaldiçoados e o Primeiro Oficial Expedito. Leve a Caixa de Rapé do Expedito ao Primeiro Oficial Simonez no Porto de Menethil."}, [19]={npc="Primeiro Oficial Simonez", tgt="Primeiro Oficial Simonez"}, [20]={npc="Primeiro Oficial Simonez", tgt="Primeiro Oficial Simonez"}, [21]={hint="Obtenha a Chave do Cofre do Intrépido do Capitão Halyndor.", desc="O Capitão Halyndor está no Intrépido encalhado; mate-o primeiro para pegar a chave e depois abra o cofre no navio."}, [22]={npc="Cofre Trancado do Intrépido", npcObj=true}, [23]={npc="Cofre Trancado do Intrépido", npcObj=true}, [24]={npc="Ormer Trançaferro", tgt="Ormer Trançaferro"}, [25]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [26]={hint="Ormer Trançaferro quer que você mate 10 Garrafoices Mosqueados e 10 Rasgaqueixos Mosqueados, depois fale novamente com ele no Sítio de Escavação Whelgar."}, [27]={hint="O Prospector Whelgar quer que você revire o sítio de escavação em busca dos 4 fragmentos perdidos da tabuleta: Ados, Modr, Golm e Neru."}, [28]={npc="Ormer Trançaferro", tgt="Ormer Trançaferro"}, [29]={npc="Ormer Trançaferro", tgt="Ormer Trançaferro"}, [30]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [31]={npc="Relíquia Titânica", npcObj=true, tag="Opcional, Aceite se cair", desc="Se você saquear a Relíquia Titânica do Guardião da Relíquia, clique nela com o botão direito para iniciar a missão."}, [32]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [33]={npc="Prospector Whelgar", tgt="Prospector Whelgar"}, [34]={text="Seu alvo fica no alto da encosta; siga a seta e suba contornando pelo oeste (31.99, 48.68 → 31.15, 49.05 → 32.41, 50.92)."}, [35]={hint="Ormer Trançaferro, no Sítio de Escavação Whelgar, quer que você mate o Sarilodonte e leve uma de suas garras até ele depois que tiver cumprido a tarefa."}, [36]={npc="Ormer Trançaferro", tgt="Ormer Trançaferro"}, [37]={npc="Alvinho Penagentil", tgt="Alvinho Penagentil"}, [38]={npc="Alvinho Penagentil", tgt="Alvinho Penagentil"}, [39]={npc="Einar Pegapétrea", tgt="Einar Pegapétrea", desc="Missão de entrega; entregue a Iago Halberque quando voltar ao Porto de Menethil."}, [40]={hint="O Capitão Punhoforte, na Bastilha Menethil, quer que você destrua os 4 conjuntos de Planos de Ataque no Acampamento Presirada."}, [41]={npc="Grimório Esfarrapado", npcObj=true, desc="Um livro no Acampamento Presirada; pegue-o e leve de volta ao Porto de Menethil."}, [42]={hint="O Malvino da Garra Preta quer que você lhe traga uma Lágrima de Tirsa da Vila Sombria e uma Raiz Almiscarada do Pantanal."}, [43]={hint="Colete 8 Escamas Carmesins Imaculadas e leve-as para Iago Halberque, no Porto de Menethil."}, [44]={hint="Leve 8 Estandartes de Guerra Presa do Dragão para o Capitão Punhoforte."}, [45]={hint="Colete 12 Ovos de Rasgaqueixo Perfeitos para Alvinho Penagentil."}, [46]={hint="Colete 10 Incisivos de Rasgaqueixo para Alvinho Penagentil."}, [47]={npc="Alvinho Penagentil", tgt="Alvinho Penagentil"}, [48]={npc="Alvinho Penagentil", tgt="Alvinho Penagentil"}, [49]={npc="Trançalonga, o Austero", tgt="Trançalonga, o Austero"}, [50]={npc="Trançalonga, o Austero", tgt="Trançalonga, o Austero", tag="Opcional, Grupo recomendado", desc="As continuações são missões de elite. Só faça em grupo."}, [51]={npc="Rocio Garmason", tgt="Rocio Garmason", tag="Opcional, Grupo recomendado"}, [52]={hint="Mate Balgaras, o Asqueroso e leve a orelha dele para Trançalonga, o Austero, que está do lado de fora de Dun Modr.", tag="Opcional, Grupo recomendado"}, [53]={hint="Rocio Garmason, em Dun Modr, quer que você mate 15 Anões Ferro Negro, 5 Escavadores Ferro Negro, 5 Sabotadores Ferro Negro e 5 Demolidores Ferro Negro.", tag="Opcional, Grupo recomendado"}, [54]={npc="Trançalonga, o Austero", tgt="Trançalonga, o Austero", tag="Opcional, Grupo recomendado"}, [55]={npc="Rocio Garmason", tgt="Rocio Garmason", tag="Opcional, Grupo recomendado"}, [56]={npc="Rocio Garmason", tgt="Rocio Garmason", tag="Grupo recomendado, Opcional", desc="Pegue esta missão ao entregar \"A guerra dos Ferro Negro\". Faça-a na próxima ida ao Cárcere e entregue-a quando voltar a Dun Modr."}, [57]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [58]={npc="Cadáver de Ebenezer Ferratranca", npcObj=true, desc="Pelo lado do Pantanal, procure a escada dentro da ponte leste e desça até Ebenezer. Entregue a missão e aceite a próxima no mesmo cadáver. Suba as mesmas escadas e volte a Dun Modr. Há inimigos de elite por perto. Se estiver só, espere uma abertura ou procure ajuda."}, [59]={npc="Cadáver de Ebenezer Ferratranca", npcObj=true}, [60]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [61]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [62]={hint="Destrua a Caixa de Explosivos.", desc="De Dun Modr, siga para o norte pela grande ponte de pedra intacta. Na saída da ponte, já no Planalto Arathi, vire à direita e atravesse a pequena ponte suspensa até o acampamento dos Ferro Negro. Destrua os explosivos na carroça."}, [63]={text="Pegue a carta no caminho de volta a Dun Modr. Antes de entrar na água, procure um trecho da margem por onde consiga voltar a subir. Mergulhe até o leito do rio sob a ponte destruída. Pegue o envelope encharcado junto à mão do anão preso nos escombros. Clique com o botão direito no envelope para aceitar a missão. Saia pela margem onde entrou e volte até Rhag no Pantanal."}, [64]={npc="Envelope Ensopado", npcObj=true, desc="Clique com o botão direito em Envelope Ensopado na bolsa para iniciar a missão."}, [65]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [66]={npc="Rhag Garmason", tgt="Rhag Garmason"}, [67]={npc="Capitã Nélia", tgt="Capitã Nélia"}, [68]={nodeA="{a:320}", node="Refuge Pointe"}, [69]={to="Altaforja"}, [70]={npc="Prospector Lançatroz", tgt="Prospector Lançatroz"}, [71]={npc="Sara Caxias", tgt="Sara Caxias", desc="Entregue a Sara, em Altaforja, a carta recebida ao aceitar a missão. O envelope encharcado serve para iniciar a missão."}, [72]={npc="Sara Caxias", tgt="Sara Caxias"}, [73]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}, [74]={npc="Rei Magni Barbabronze", tgt="Rei Magni Barbabronze"}, [75]={npc="Piloto Barbalonga", tgt="Piloto Barbalonga"}, [76]={npc="Grão-alvanel Oscarmeyer", tgt="Grão-alvanel Oscarmeyer"}, [77]={npc="Grão-alvanel Oscarmeyer", tgt="Grão-alvanel Oscarmeyer"}, [78]={npc="Mestre-faz-tudo Superchispa", tgt="Mestre-faz-tudo Superchispa"}, [79]={npc="Mestre-faz-tudo Superchispa", tgt="Mestre-faz-tudo Superchispa", tag="Grupo recomendado, Opcional", desc="Missão da masmorra de Gnomeregan; só aceite se for fazer Gnomeregan."}, [80]={npc="Grão-faz-tudo Mekkatorque", tgt="Grão-faz-tudo Mekkatorque", tag="Grupo recomendado, Opcional"}, [81]={npc="Mestre Mecânico Fundecano", tgt="Mestre Mecânico Fundecano", tag="Grupo recomendado, Opcional"}, [82]={to="Menethil Harbor", toA="{a:150}"}, [83]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte"}, [84]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte"}, [85]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte"}, [86]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte", tag="Faça se estiver passando, Opcional"}, [87]={npc="Iago Halberque", tgt="Iago Halberque"}, [88]={npc="Iago Halberque", tgt="Iago Halberque"}, [89]={npc="Iago Halberque", tgt="Iago Halberque", desc="Entregue a Alvinho Penagentil a caminho das catapultas."}, [90]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [91]={npc="Glorin Testaço", tgt="Glorin Testaço"}, [92]={npc="Alvinho Penagentil", tgt="Alvinho Penagentil"}, [93]={npc="Catapulta da Presa do Dragão", npcObj=true, tag="Faça se estiver passando, Opcional"}, [94]={npc="Catapulta da Presa do Dragão", npcObj=true, tag="Opcional, Grupo recomendado", desc="As continuações são missões de elite. Só faça em grupo."}, [95]={hint="Mate o Chefe Nek'rosh.", tag="Opcional, Grupo recomendado"}, [96]={npc="Capitão Punhoforte", tgt="Capitão Punhoforte", tag="Opcional, Grupo recomendado"}}},
    ["05-d7"] = {name="Gnomeregan", entrance="Dun Morogh 24.30, 39.80", pickup="Pegue as missões da masmorra ao passar: Vale Gris (2ª visita). Assim não precisa voltar antes de entrar.", pickupS={{"Pegue as missões da masmorra ao passar: Vale Gris (2ª visita)"}, {"Assim não precisa voltar antes de entrar"}}, tips={{k="說明", text="Para Resgate de Dados, saqueie um cartão branco dos inimigos próximos. Antes de entrar na masmorra, troque-o pelo amarelo no 3005-A, na passagem externa ao norte do elevador.", s={{"Para Resgate de Dados, saqueie um cartão branco dos inimigos próximos"}, {"Antes de entrar na masmorra, troque-o pelo amarelo no 3005-A, na passagem externa ao norte do elevador"}}}}, steps={[1]={npc="Gaxim Deuxabu", tgt="Gaxim Deuxabu"}, [2]={npc="Irmão Sarmo", tgt="Irmão Sarmo"}, [3]={npc="Shoni, a Shilenchiosa", tgt="Shoni, a Shilenchiosa", tag="Grupo recomendado, Opcional"}, [4]={npc="Mestre-faz-tudo Superchispa", tgt="Mestre-faz-tudo Superchispa", tag="Grupo recomendado, Opcional"}, [5]={npc="Grão-faz-tudo Mekkatorque", tgt="Grão-faz-tudo Mekkatorque", tag="Grupo recomendado, Opcional"}, [6]={npc="Mestre Mecânico Fundecano", tgt="Mestre Mecânico Fundecano", tag="Grupo recomendado, Opcional"}, [7]={npc="Cronomorfus Espanafuso", tgt="Cronomorfus Espanafuso"}, [8]={npc="Gnoarn", tgt="Gnoarn", tag="Opcional, Grupo recomendado"}, [9]={npc="Ozzie Mudavolt", tgt="Ozzie Mudavolt"}, [10]={npc="Ozzie Mudavolt", tgt="Ozzie Mudavolt", tag="Opcional, Grupo recomendado"}, [11]={npc="Ozzie Mudavolt", tgt="Ozzie Mudavolt", tag="Opcional, Grupo recomendado"}, [12]={npc="Mathiel", tgt="Mathiel", tag="Opcional", desc="Aceite em Darnassus, requer nível 24: voe de Auberdine até a Vila de Rut'theran e entre na cidade pelo portal. Se não quiser fazer o desvio, pule junto com a entrega depois da masmorra."}, [13]={text="Voe do Porto de Menethil para Altaforja, saia pelo portão da cidade e siga a estrada de Dun Morogh para o oeste até Gnomeregan."}, [14]={text="Entrada: Gnomeregan"}, [15]={hint="Use o Coletor de Chumbo Vazio nos Invasores Irradiados ou nos Pilhadores Irradiados para recolher resíduos radioativos. Depois que ele ficar cheio, leve-o de volta para Ozzie Mudavolt em Kharanos.", tag="Opcional, Grupo recomendado", spot="Você pode dividir a sequência entre várias visitas. Colete a primeira amostra nos túneis da entrada ou dentro da masmorra. Entregue-a a Ozzie em Kharanos para receber o frasco pesado."}, [16]={hint="Vá até Gnomeregan e traga o Resíduo Radioativo de Alta Potência. Tome cuidado, pois a radiação é instável e pode se esvair rapidamente.", tag="Opcional, Grupo recomendado", spot="Use o frasco pesado em um Visgo Irradiado, um Tocaieiro Corrosivo ou um horror irradiado. A amostra dura duas horas. Se não puder chegar a Kharanos a tempo, faça a coleta na próxima visita em grupo."}, [17]={hint="Leve o Cartão Perfurado Prismático para o Mestre Mecânico Fundecano em Altaforja.", tag="Opcional, Grupo recomendado"}, [18]={hint="Leve 24 Tripas Mecanobóticas para Shoni em Ventobravo.", tag="Grupo recomendado, Opcional", desc="Cai dos monstros mecânicos; entregue quando voltar a Ventobravo."}, [19]={npc="Anel Encardido", npcObj=true, tag="Aceite se cair, Opcional"}, [20]={hint="Descubra uma maneira de remover a crosta de sujeira do Anel Encardido.", tag="Opcional", spot="Fagulhomático 5200 na Zona Limpa. Leve 3 moedas de prata."}, [21]={npc="A Brastematic 5200", npcObj=true, tag="Opcional"}, [22]={npc="A Brastematic 5200", npcObj=true, tag="Opcional"}, [23]={npc="Kernobill", tgt="Kernobill", tag="Opcional, Grupo recomendado", spot="No dormitório perto da Zona Limpa. Libere o caminho de volta à saída e espere o grupo todo antes de falar com Kernobee."}, [24]={hint="Escolte Kernobill até a saída do Corredor dos Mecanismos, depois apresente-se a Scooty na Angra do Butim.", tag="Escolta, Opcional, Grupo recomendado", desc="Entregue a missão a Scooty na primeira passagem pela Angra do Butim, na Selva do Espinhaço."}, [25]={npc="Ozzie Muda