    ["03-24"] = {name="Contraforte de Eira dos Montes", steps={[1]={to="Southshore", toA="{a:271}", from="Menethil Harbor", fromA="{a:150}", desc="Pegue o barco para Auberdine no cais norte de Porto de Menethil e desça em Costa Sul no meio do caminho."}, [2]={npc="Phin Odelic", tgt="Phin Odelic"}, [3]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [4]={npc="Taberneiro Kelly", tgt="Taberneiro Kelly"}, [5]={npc="Mestre-cervejeiro Podrágua", tgt="Mestre-cervejeiro Podrágua"}, [6]={npc="Magistrado Henrique Maleb", tgt="Magistrado Henrique Maleb"}, [7]={npc="Dario Malavista", tgt="Dario Malavista", tag="Opcional"}, [8]={hint="Mate 10 Caçamarés Rancapinas e 10 Oráculos Rancapinas para o Tenente Fárrio Orinelle na Costa Sul."}, [9]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [10]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [11]={hint="Colete 10 Cabeças de Murloc dos murlocs da Praia Ocidental para o Tenente Fárrio Orinelle, que está na Costa Sul."}, [12]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [13]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [14]={npc="Delegado Trilharrubra", tgt="Delegado Trilharrubra"}, [15]={npc="Delegado Trilharrubra", tgt="Delegado Trilharrubra"}, [16]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [17]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [18]={hint="Mate 10 Caça-costas Espinhadaga e 10 Sirenas Espinhadaga para o Tenente Fárrio Orinelle na Costa Sul."}, [19]={hint="Entregue as garrafas de Varietal de Quedarroca em Dun Garok, no sudeste do Contraforte de Eira dos Montes, e traga de volta um saco do Lúpulo Artesanal deles."}, [20]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [21]={npc="Tenente Fárrio Orinelle", tgt="Tenente Fárrio Orinelle"}, [22]={npc="Mestre-cervejeiro Podrágua", tgt="Mestre-cervejeiro Podrágua"}, [23]={hint="O Grão-alvanel Oscarmeyer, de Altaforja, quer que você lhe traga