    ["05-d16"] = {name="Dalaran", entrance="Montanhas de Alterac 8.46, 59.21", pickup="Na primeira visita a Ventobravo, pegue Uma amostra verde e Poder esmagador. Ao chegar ao nível 30 no Contraforte de Eira dos Montes, pegue Um pedido alarmante com o Emissário Jacques em Costa Sul.", pickupS={{"Na primeira visita a Ventobravo, pegue Uma amostra verde e Poder esmagador"}, {"Ao chegar ao nível 30 no Contraforte de Eira dos Montes, pegue Um pedido alarmante com o Emissário Jacques em Costa Sul"}}, tips={{k="說明", text="A imagem de Modera e o portal da masmorra ficam em pontos diferentes. Vá pelo lado do esgoto do Espelho de Lordaeron. As restrições de facção valem para os portões externos de Dalaran e para falar com os NPCs da cidade.", s={{"A imagem de Modera e o portal da masmorra ficam em pontos diferentes"}, {"Vá pelo lado do esgoto do Espelho de Lordaeron"}, {"As restrições de facção valem para os portões externos de Dalaran e para falar com os NPCs da cidade"}}}}, steps={[1]={npc="Shylamiir", tgt="Shylamiir"}, [2]={npc="Grão-Feiticeiro Andromath", tgt="Grão-Feiticeiro Andromath"}, [3]={npc="Emissário Jacques", tgt="Emissário Jacques"}, [4]={text="Opcional: voe de Ventobravo para Costa Sul, siga para o norte pelo Contraforte de Eira dos Montes até as Montanhas de Alterac, contorne a margem norte do Espelho de Lordaeron para o oeste e procure a Imagem da Arquimaga Modera do lado de fora do esgoto de Dalaran. Ao sair da masmorra, use a pedra de regresso para voltar a Ventobravo e retome a {s:03-25}.", tag="Opcional"}, [5]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera"}, [6]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera"}, [7]={npc="Imagem da Arquimaga Modera", tgt="Imagem da Arquimaga Modera", desc="Ao aceitar a missão, você recebe a Chave do Esgoto de Dalaran."}, [8]={text="Entrada: Dalaran"}, [9]={hint="Derrote 8 Resquícios Caçadores, 8 Resquícios Saturados e 8 Ecos de Mana em Dalaran a pedido da Arquimaga Modera, nos arre