7]={npc="Krom Braçoforte", tgt="Krom Braçoforte"}, [28]={hint="Recupere o Tomo Mofado e o Manuscrito Rasgado para Krom Braçoforte em Altaforja.", desc="Voe de Altaforja para Costa Sul e, na volta, de novo para Altaforja."}, [29]={npc="Krom Braçoforte", tgt="Krom Braçoforte"}, [30]={npc="Krom Braçoforte", tgt="Krom Braçoforte"}, [31]={hint="Leve o Tomo Reformado e 3 Bastões de Canalização para Strahad Farsan na Vila Catraca.", desc="Voe de Altaforja para o Porto de Menethil para a parte do Pantanal."}, [32]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Pegue o barco do cais sul do Porto de Menethil até Theramore, descubra o ponto de voo e voe para Vila Catraca. Ou voe do Porto de Menethil para Angra do Butim (com escalas em Altaforja e Ventobravo) e pegue o barco de lá."}, [33]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Evoque e derrote o caçador vil no círculo perto de Strahad Farsan."}, [34]={hint="Usando the Tomo do Conluio, evoque e subjugue um caçador vil, depois devolva o Tomo do Conluio a Strahad Farsan na Vila Catraca.", desc="Evoque e derrote o caçador vil no círculo perto de Strahad Farsan."}, [35]={npc="Strahad Farsan", tgt="Strahad Farsan", desc="Evoque e derrote o caçador vil no círculo perto de Strahad Farsan."}, [36]={text="De Vila Catraca, siga a estrada dos Sertões para o norte, passe pela Encruzilhada e continue para o norte até entrar no Vale Gris; depois siga a estrada do Vale Gris para o oeste até Astranaar (34.41, 47.99).", desc="A Encruzilhada e o Posto Machadada são bases da Horda; contorne-os. Se Theramore estiver no seu mapa de voo, você pode voar direto para Astranaar (com conexão em Theramore e Auberdine)."}, [37]={npc="Cronomorfus Espanafuso", tgt="Cronomorfus Espanafuso"}, [38]={npc="Eldrun Rompe-procelas", tgt="Eldrun Rompe-procelas", desc="Chamado do Ar: procure Veyric Thunderhame no Planalto Arathi."}, [39]={to="Menethil Harbor", toA="{a:150}"}, [40]={npc="Mikhail", tgt="Mikhail"}, [41]={npc="Mikhail", tgt="Mikhail"}, [42]={hint="Impeça Tapoke Jahn de fugir e fale novamente com Mikhail em Menethil."}, [43]={npc="Mikhail", tgt="Mikhail"}, [44]={npc="Tapoke Slim Jahn", tgt="Tapoke Slim Jahn"}, [45]={npc="Mikhail", tgt="Mikhail"}, [46]={npc="Mikhail", tgt="Mikhail"}, [47]={npc="Vincent Hyal", tgt="Vincent Hyal", desc="Na mesma estalagem; leve a carta a Theramore."}, [48]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Este barco faz parada em Costa Sul. Desça em Auberdine."}}},
    ["03-28"] = {steps={[1]={to="Astranaar", toA="{a:415}"}, [2]={npc="Sentinela Melyria Algissombra", tgt="Sentinela Melyria Algissombra"}, [3]={npc="Iliana", tgt="Iliana"}, [4]={npc="Pelturas Lunalva", tgt="Pelturas Lunalva"}, [5]={text="Contorne pelo norte e entre no vale por aqui."}, [6]={hint="Vá para o Vale Uivante estudar o Tomo de Mel'Thandris, depois fale novamente com a Sentinela Melyria Algissombra no Altar de Aessina.", desc="Entre pela caverna para pegar o livro. É fácil puxar monstros demais, e fica mais difícil quando o raro está lá."}, [7]={hint="Recolha uma Pedra-da-lua Caída do Oráculo Umbrárvore, depois leve-a para Pelturas em Astranaar."}, [8]={text="Volte à estrada principal ao norte e entre no vale por esta entrada."}, [9]={hint="Liberte a alma dos Altaneiros na Trilha da Noite e em Satyrnaar, depois fale novamente com Dinis, o Purificador, no Entreposto de Maestra."}, [10]={npc="Anilia", tgt="Anilia"}, [11]={npc="Anilia", tgt="Anilia"}, [12]={hint="Mate Geltharis e leve o Ramo de Cenarius para Iliana no Altar de Aessina."}, [13]={npc="Kainet Brisacalma", tgt="Kainet Brisacalma"}, [14]={npc="Maseara Lunautumna", tgt="Maseara Lunautumna"}, [15]={hint="Maseara Lunautumna quer que você vasculhe a região oeste de Cantilenda, em meio aos demônios de Satyrnaar. Ao retornar, relate qualquer sinal que tenha encontrado de Kurothel, marido dela."}, [16]={npc="Maseara Lunautumna", tgt="Maseara Lunautumna"}, [17]={nodeA="{a:3137}", node="Talrendis Point", desc="De Cantilenda, siga a estrada para o leste até entrar em Azshara; o acampamento fica logo ao lado da entrada."}, [18]={to="Astranaar", toA="{a:415}"}, [19]={npc="Pelturas Lunalva", tgt="Pelturas Lunalva"}, [20]={npc="Sentinela Melyria Algissombra", tgt="Sentinela Melyria Algissombra"}, [21]={npc="Sentinela Melyria Algissombra", tgt="Sentinela Melyria Algissombra", tag="Opcional"}, [22]={npc="Iliana", tgt="Iliana"}, [23]={npc="Dinis, o Purificador", tgt="Dinis, o Purificador"}}},
    ["03-29"] = {grind={[1]={mob="Observador Sal-gema", note="Extremo sul da Chapada Cintilante; monstros comuns, na mesma área dos basiliscos de Tinha um calombo no meio do caminho."}, [2]={mob="Cristalderme Sal-gema", note="Misturados com os Observadores; mais numerosos, de nível um pouco mais baixo."}}, steps={[1]={to="Rut'theran Village", toA="{a:702}", tag="Opcional", desc="Pouca experiência no trecho de Darnassus. Pule se estiver com pressa."}, [2]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus.", tag="Opcional"}, [3]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [4]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [5]={hint="Vasculhe o baú de Velinde atrás do seu diário, depois leve-o junto com a chave para Thyn'tel Tecelâmina em Darnassus.", tag="Opcional"}, [6]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [7]={npc="Thyn'tel Tecelamina", tgt="Thyn'tel Tecelamina", tag="Opcional"}, [8]={text="Entre no portal de Darnassus para voltar à Vila de Rut'theran.", tag="Opcional"}, [9]={text="Se fez as missões opcionais de Darnassus, voe da Vila de Rut'theran para Vila Catraca (com escalas em Auberdine e Campo Talrendis); se pulou, voe de Astranaar (com escala em Campo Talrendis). Siga a estrada principal para o sul, contorne o Acampamento Taurajo e desça para Mil Agulhas pelo Grande Elevador. Só use a Muralha de Mor'shan se nenhum dos dois pontos estiver descoberto."}, [10]={text="Desça até o fim no Grande Elevador."}, [11]={nodeA="{a:489}", node="Thalanaar"}, [12]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [13]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [14]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [15]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [16]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [17]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [18]={npc="Relé", tgt="Relé"}, [19]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [20]={hint="Obtenha 10 Ossos Ocos de Abutre para Relé no Salar Cintilante."}, [21]={hint="Mate 10 Basiliscos Sal-gema, 10 Cristaldermes Sal-gema e 6 Observadores Sal-gema para o Mestre de Pistas Zheran no Salar Cintilante."}, [22]={hint="Leve 9 Cascos Endurecidos de Tartaruga para Capu Latafuso no Salar Cintilante."}, [23]={hint="Leve 30 Peças de Carro-foguete para Kravel Barbakarvão no Salar Cintilante."}, [24]={hint="Leve 6 Peçonhas Salgadas de Escorpídeo para Xabu Latafuso no Salar Cintilante."}, [25]={npc="Relé", tgt="Relé"}, [26]={npc="Mestre de Pistas Zheran", tgt="Mestre de Pistas Zheran"}, [27]={npc="Capu Latafuso", tgt="Capu Latafuso"}, [28]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [29]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [30]={desc="Se ainda não estiver no nível 35 antes de sair da Chapada Cintilante, mate Observadores Sal-gema e Cristaldermes Sal-gema ao sul da pista de corrida até o 35."}, [31]={text="Da Chapada Cintilante, siga a estrada para o sul até Tanaris e libere o ponto de voo de Geringontzan.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [32]={nodeA="{a:976}", node="Gadgetzan"}}},
    ["05-d17"] = {name="Urzal dos Tuscos", entrance="Sertões (1413), perto do portal da masmorra no túnel de espinhos, por volta de 42.30, 89.90.", pickup="Ao voar para Vila Catraca na primeira ida às Mil Agulhas, pegue Tubérculos Folhazul com Cáliper Porcatraca e apanhe a caixa, o bastão de comando e o manual ao lado dele. No pé do Grande Elevador, pegue o Diário de Henrig Monocelha, entregue a Falfindel Trilhemas em Thalanaar e depois pegue A bruxa má do Urzal.", pickupS={{"Ao voar para Vila Catraca na primeira ida às Mil Agulhas, pegue Tubérculos Folhazul com Cáliper Porcatraca e apanhe a caixa, o bastão de comando e o manual ao lado dele"}, {"No pé do Grande Elevador, pegue o Diário de Henrig Monocelha, entregue a Falfindel Trilhemas em Thalanaar e depois pegue A bruxa má do Urzal"}}, tips={{k="取捨", text="A mortalidade se esvanece é entregue em Darnassus. Se não quiser ir só para isso, entregue na próxima vez que passar por Darnassus."}, {k="說明", text="Urzal dos Tuscos fica a oeste do Grande Elevador; Urzal dos Mortos fica a leste. 42.30, 89.90 é a marca da entrada no cliente Forever. Pela estrada principal, siga o túnel de espinhos a oeste até o portal.", s={{"Urzal dos Tuscos fica a oeste do Grande Elevador"}, {"Urzal dos Mortos fica a leste"}, {"42.30, 89.90 é a marca da entrada no cliente Forever"}, {"Pela estrada principal, siga o túnel de espinhos a oeste até o portal"}}}}, steps={[1]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca", desc="Pegue a caixa, o bastão de comando e o manual com o mesmo NPC de Vila Catraca antes de entrar."}, [2]={npc="Diário de Henrig Monocelha", npcObj=true, desc="Pegue o Diário de Henrig Monocelha no pé do Grande Elevador e clique com o botão direito nele para iniciar a missão."}, [3]={npc="Falfindel Trilhemas", tgt="Falfindel Trilhemas"}, [4]={npc="Falfindel Trilhemas", tgt="Falfindel Trilhemas"}, [5]={text="Opcional: de Geringontzan volte para o norte até a Chapada Cintilante, suba pelo Grande Elevador até os Sertões e siga o túnel de espinhos a oeste até o portal da masmorra. Ao sair, retome a {s:03-38}.", tag="Opcional"}, [6]={text="Entrada: Urzal dos Tuscos"}, [7]={hint="Pegue um Caixote com Furos.", desc="Local: Cave tubérculos ao longo do caminho de espinhos; também dá para cavar na volta com Willix.", spot="Cave tubérculos ao longo do caminho de espinhos; também dá para cavar na volta com Willix."}, [8]={npc="Heralath Corregofulvo", tgt="Heralath Corregofulvo", spot="Atrás do chefe final, ao lado de Willix"}, [9]={hint="Encontre e devolva o Pingente de Treshala para Treshala Corregofulvo em Darnassus.", desc="Com a missão aceita, tanto os javatuscos quanto os chefes da masmorra podem derrubar o pingente."}, [10]={hint="Leve o Medalhão da Talhaflanco para Falfindel Trilhemas em Thalanaar.", desc="Local: Saia da caverna dos morcegos, suba na plataforma e mate Charlga na última cabana.", spot="Saia da caverna dos morcegos, suba na plataforma e mate Charlga na última cabana."}, [11]={npc="Importador Willix", tgt="Importador Willix", desc="A escolta começa na tenda ao lado do chefe final. Limpe primeiro o caminho de volta à entrada e só então aceite."}, [12]={hint="Escolte o Importador Willix para fora do Urzal dos Tuscos.", desc="Limpe primeiro o caminho de volta à entrada e depois aceite a escolta de Willix. Proteja-o até a entrada. Local: parta da tenda ao lado do chefe final e volte à entrada com Willix.", spot="Encontre Willix em uma tenda perto do último chefe e acompanhe-o de volta à entrada."}, [13]={npc="Importador Willix", tgt="Importador Willix", desc="Comece a escolta do NPC dentro da masmorra.", spot="Na entrada da masmorra, onde a escolta termina"}, [14]={npc="Cáliper Porcatraca", tgt="Cáliper Porcatraca"}, [15]={npc="Falfindel Trilhemas", tgt="Falfindel Trilhemas"}, [16]={npc="Treshala Corregofulvo", tgt="Treshala Corregofulvo"}}},
    ["03-38"] = {tips={{k="取捨", text="1440 exige escoltar Dalinda pela emboscada no portão da fortaleza, e O Livro dos Anciãos e Reagentes para Recuperação Ilimitada (Ltda) exigem elites ou grupos de demônios; sozinho, não pegue."}}, grind={[1]={mob="Centauro Kolkar", note="Vale do leste; complete o nível enquanto faz a recompensa."}, [2]={mob="Aniquilador da Lâmina Ardente", note="Fora da Fortaleza Machado do Trovão; inimigos normais."}}, steps={[1]={text="Na primeira visita a Geringontzan, se ainda não puder voar para o Pico da Garra de Pedra: volte para o norte até a Chapada Cintilante nas Mil Agulhas, suba o grande elevador até os Sertões, contorne o Acampamento Taurajo para o leste até Vila Catraca e voe para o Pico da Garra de Pedra."}, [2]={to="Stonetalon Peak", toA="{a:467}", desc="Se já liberou o Posto do Nijel, voe direto para lá (com conexão em Theramore) e pule o próximo passo. Se o Morro das Torres de Pedra não estiver liberado, voe até Astranaar e entre na Cordilheira das Torres de Pedra pela caverna ao sul do Vale Gris."}, [3]={text="Do Morro das Torres de Pedra, siga a estrada para o sul montanha abaixo, contorne o acampamento da Horda ao passar pelo Retiro Rocha do Sol e entre em Desolação pelo sudoeste da Cordilheira das Torres de Pedra. O Posto do Nijel fica no norte de Desolação.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [4]={to="Nijel's Point", toA="{a:608}"}, [5]={nodeA="{a:608}", node="Nijel's Point"}, [6]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [7]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [8]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [9]={npc="Vahlarriel Matademônios", tgt="Vahlarriel Matademônios"}, [10]={hint="Leve 10 Garras Furiódio e 10 Chifres Furiódio para Kreldig Ungor na Desolação."}, [11]={npc="Baú de Malem", npcObj=true, desc="Siga a estrada do norte para o oeste; o baú fica ao lado da carroça tombada na beira da estrada."}, [12]={npc="Baú de Malem", npcObj=true}, [13]={npc="Vahlarriel Matademônios", tgt="Vahlarriel Matademônios"}, [14]={npc="Vahlarriel Matademônios", tgt="Vahlarriel Matademônios"}, [15]={npc="Vahlarriel Matademônios", tgt="Vahlarriel Matademônios"}, [16]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [17]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [18]={text="Siga a estrada do norte para o oeste até Ethel Rethor, desça até o naufrágio na costa oeste e volte para o leste até a Fortaleza Machado do Trovão."}, [19]={npc="Azore Albamorte", tgt="Azore Albamorte"}, [20]={npc="Baú de Karnitol", npcObj=true}, [21]={npc="Baú de Karnitol", npcObj=true}, [22]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [23]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [24]={hint="Encontre Tyranis Malem na Desolação."}, [25]={hint="Pegue o Cetro de Luz e devolva-o para Azore Albamorte na torre de Ethel Rethor."}, [26]={hint="Mate orcs Lâmina Ardente na Fortaleza Machado do Trovão, em Desolação, e então fale novamente com Vahlarriel Matademônios no Posto do Nijel."}, [27]={npc="Dalinda Malem", tgt="Dalinda Malem"}, [28]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [29]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [30]={npc="Vahlarriel Matademônios", tgt="Vahlarriel Matademônios"}, [31]={npc="Cabo Melquias", tgt="Cabo Melquias"}, [32]={npc="Capitão Pentigast", tgt="Capitão Pentigast"}, [33]={npc="Irmão Anton", tgt="Irmão Anton"}, [34]={text="Da Ponta de Nijel, siga a estrada do leste para o sul até o vale dos centauros Kolkar."}, [35]={hint="Entregue 15 Orelhas de Centauro para Cabo Melquias no Posto do Nijel em Desolação."}, [36]={hint="Obtenha 5 Totens de Centauro Entalhados matando centauros de qualquer clã em Desolação e depois leve-os para o Capitão Pentigast no Posto do Nijel."}, [37]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela"}, [38]={hint="Leve 7 ampolas de Peçonha de Scorpachi e 3 Pelegos Envelhecidos de Kodo para Kreldig Ungor na Desolação."}, [39]={npc="Smid Rabiscafuso", tgt="Smid Rabiscafuso"}, [40]={hint="Leve cinco Kodos Domados e o Kodoagrupandador para Smid Rabiscafuso no Acampamento do Rabiscafuso.", desc="Leve cada kodo até Smeed, espere ele pedir para examinar e clique com o botão direito no kodo domado; só vá buscar o próximo depois que a contagem subir. Pegue os ossos de kodo de Ossos do ofício no caminho e cuidado com as aparições de kodo que podem surgir ao pegá-los."}, [41]={hint="Entregue 10 Ossos de Kodo do Cemitério dos Kodos para Bibbly Ferrafivela no Barraco do Kormek."}, [42]={npc="Smid Rabiscafuso", tgt="Smid Rabiscafuso"}, [43]={npc="Guido Zumbidorla", tgt="Guido Zumbidorla"}, [44]={text="Do Cemitério de Kodos, siga a estrada para o sul até o Vale dos Ossos. O acampamento de demônios a leste da estrada é o Conciliábulo de Mannoroc; fique longe dele."}, [45]={hint="Destrua 30 Assoladores Mortos-vivos, depois fale novamente com o Irmão Anton no Posto do Nijel."}, [46]={hint="Leve 8 Fantasmoplasmas e o Caixote de Ímãs Fantasmais para Guido Zumbidorla na Desolação.", desc="Coloque a caixa de ímãs fantasmagóricos entre os dois esqueletos gigantes do Vale dos Ossos, afaste-se e mate um a um os espíritos de centauro atraídos até ter 8 ectoplasmas. Limpe ou evite os monstros de nível 38-40 por perto; se não conseguir, pule Vá catar fantasmoplasma!."}, [47]={npc="Guido Zumbidorla", tgt="Guido Zumbidorla"}, [48]={npc="Bibbly Ferrafivela", tgt="Bibbly Ferrafivela"}, [49]={text="Da cabana de Bibbly, siga para o noroeste até Ethel Rethor para entregar o Cetro da Luz, depois para o norte até a costa atrás dos nagas Lâmina Sinuosa e volte pela estrada do norte até a Ponta de Nijel para entregar tudo de uma vez."}, [50]={npc="Azore Albamorte", tgt="Azore Albamorte"}, [51]={hint="Encontre a Algibeira de Karnitol e leve-a de volta para Kreldig Ungor em Desolação."}, [52]={npc="Cabo Melquias", tgt="Cabo Melquias"}, [53]={npc="Capitão Pentigast", tgt="Capitão Pentigast"}, [54]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [55]={npc="Irmão Anton", tgt="Irmão Anton"}, [56]={npc="Irmão Anton", tgt="Irmão Anton", tag="Opcional, Grupo recomendado"}, [57]={npc="Kreldig Ungor", tgt="Kreldig Ungor"}, [58]={npc="Kreldig Ungor", tgt="Kreldig Ungor", desc="Guarde a bolsa e entregue em Altaforja depois dos Ermos."}, [59]={}}},
    ["03-30"] = {name="Planalto Arathi", grind={[1]={mob="Kobold Bigodesseco", note="Região da entrada da Garganta Seca; monstros comuns, bem ao lado de onde você conclui A princesa aprisionada."}, [2]={mob="Escavador Bigodesseco", note="Junto ao cristal no fundo da garganta; nível mais adequado."}, [3]={mob="Brutamontes Punho de Pedra", note="Ogros ao redor do Forte Punho de Pedra; ficam no caminho quando você for pegar a varinha."}, [4]={mob="Caçador Sombrio Cascasseca", note="Aldeia Cascasseca, a sudeste; os mesmos trolls de Isto vale ouro."}}, steps={[1]={to="Refuge Pointe", toA="{a:320}", desc="Se a Ponta do Refúgio não estiver liberada, voe até Porto de Menethil, siga a estrada para nordeste pelo Pantanal, atravesse a Ponte Thandol até o Planalto Arathi e depois siga a estrada até a Ponta do Refúgio."}, [2]={npc="Capitã Nélia", tgt="Capitã Nélia"}, [3]={npc="Quadro de Procurados", npcObj=true, tag="Grupo recomendado, Opcional"}, [4]={npc="Quadro de Procurados", npcObj=true, tag="Grupo recomendado, Opcional", desc="Otto e Falcocrista são elites de nível 38 e 40."}, [5]={npc="Rodapeh", tgt="Rodapeh"}, [6]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten"}, [7]={npc="Estilhaços de Myzrael", npcObj=true}, [8]={hint="Colete 12 Grânulos of Myzrael, depois leve-os até os Fragmentos Iridescentes, em Garganta Seca."}, [9]={npc="Fragmentos Iridescentes", npcObj=true}, [10]={desc="Suba até cerca de três quartos do nível 36; mate Kobolds Bigodesseco e Escavadores Bigodesseco aqui mesmo, na Garganta Seca."}, [11]={npc="Fragmentos Iridescentes", npcObj=true, desc="A Pedra da União Oriental fica no caminho para oeste, pegue primeiro; pegue a Pedra de Vínculo Exterior a caminho da Ponta do Refúgio."}, [12]={npc="Quae", tgt="Quae"}, [13]={npc="Quae", tgt="Quae"}, [14]={hint="Encontre a Mensageira Renegada e leve a Pasta Lacrada dela para Quae nas redondezas da Fazenda Go'Shek.", desc="A Mensageira Renegada patrulha a estrada na região da Fazenda Go'Shek; mate-a quando a vir e pegue a Pasta Lacrada."}, [15]={hint="Obtenha 10 Presas de Cascasseca, 4 Bolsas Medicinais de Cascasseca e uma Faca de Caçador Sombrio para o Aprendiz Kraiten, que aguarda na Ponta do Refúgio.", desc="Cuidado com a Mensageira Renegada que patrulha."}, [16]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten"}, [17]={npc="Capitã Nélia", tgt="Capitã Nélia", desc="Entregue a Demar Brant na Bastilha de Ermoforte, em Sendas do Rio; você vai lá na próxima parada."}, [18]={npc="Rodapeh", tgt="Rodapeh"}, [19]={desc="Se ainda não estiver no nível 37 antes de enfrentar Kor'gresh Furiafria (nível 39), mate Brutamontes Punho de Pedra do lado de fora do Forte Punho de Pedra ou vá à Aldeia Cascasseca, a leste, e mate Trolls Cascasseca até o 37."}, [20]={hint="Encontre a Varinha de Evocação de Trelane e entregue-a a Rodapeh, na Ponta do Refúgio."}, [21]={npc="Quae", tgt="Quae"}, [22]={npc="Quae", tgt="Quae"}, [23]={npc="Kinelory", tgt="Kinelory"}, [24]={npc="Kinelory", tgt="Kinelory"}, [25]={hint="Proteja Kinelory até que ela volte para Quae.", desc="Missão de escolta; siga Kinelory, haverá emboscadas pelo caminho."}, [26]={npc="Quae", tgt="Quae"}, [27]={npc="Quae", tgt="Quae"}, [28]={npc="Rodapeh", tgt="Rodapeh"}, [29]={npc="Rodapeh", tgt="Rodapeh", tag="Grupo recomendado, Opcional"}, [30]={hint="Consiga a Chave Ardente, a Chave Troante e a Chave Trovejante nas Pedras da União Ocidental, da União Oriental e de União Exterior."}, [31]={hint="Mate 10 Bandoleiros da Camarilha e 6 Mercenários da Camarilha."}, [32]={npc="Capitã Nélia", tgt="Capitã Nélia"}, [33]={npc="Capitã Nélia", tgt="Capitã Nélia", tag="Grupo recomendado, Opcional"}, [34]={npc="Pedra de Vínculo Interior", npcObj=true}, [35]={hint="Entregue a Cabeça de Marez para a Capitã Nélia na Ponta do Refúgio.", tag="Grupo recomendado, Opcional"}, [36]={hint="Entregue a Cabeça de Otto e a Cabeça de Falcocrista para a Capitã Nélia na Ponta do Refúgio.", tag="Grupo recomendado, Opcional"}, [37]={hint="Entregue Insígnias de Stromgarde para a Capitã Nélia na Ponta do Refúgio.", tag="Grupo recomendado, Opcional"}, [38]={hint="Consiga uma Ágata Lazúli e entregue-a ao Aprendiz Kraiten, na Ponta do Refúgio.", tag="Grupo recomendado, Opcional"}, [39]={npc="Capitã Nélia", tgt="Capitã Nélia", tag="Grupo recomendado, Opcional"}, [40]={npc="Capitã Nélia", tgt="Capitã Nélia", tag="Grupo recomendado, Opcional"}, [41]={npc="Capitã Nélia", tgt="Capitã Nélia", tag="Grupo recomendado, Opcional"}, [42]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten", tag="Grupo recomendado, Opcional"}, [43]={npc="Aprendiz Kraiten", tgt="Aprendiz Kraiten"}, [44]={npc="Rodapeh", tgt="Rodapeh"}, [45]={npc="Rodapeh", tgt="Rodapeh"}, [46]={hint="Encontre o Filactério de Trelane, o Orbe de Trelane e a Ágata-de-fogo de Trelane e entregue-os a Rodapeh na Ponta do Refúgio.", tag="Faça depois, quando passar por lá"}, [47]={npc="Rodapeh", tgt="Rodapeh"}, [48]={npc="Rodapeh", tgt="Rodapeh"}, [49]={hint="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.", desc="Roube um uniforme da Camarilha em Casa Grande do Norte, no Planalto Arathi."}, [50]={npc="Syndicate Footlocker", npcObj=true}, [51]={npc="Syndicate Footlocker", npcObj=true}, [52]={hint="Enquanto estiver com o disfarce de membro da Camarilha, encontre alguém na Bastilha de Stromgarde que saiba sobre o acordo secreto."}, [53]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [54]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [55]={hint="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal."}, [56]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [57]={npc="Anastasia Miller", tgt="Anastasia Miller"}, [58]={hint="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor."}, [59]={npc="Mirokos Formassilente", tgt="Mirokos Formassilente"}, [60]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular"}, [61]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Grupo recomendado, Opcional", desc="É preciso fazer Urzal dos Tuscos (a masmorra no sul dos Sertões); faça quando tiver grupo; pule também a continuação, Tempestade, terra e fogo."}, [62]={hint="Derrote Charlga Talhaflanco no Urzal dos Tuscos e colete informações sobre os planos dos javatuscos.", tag="Grupo recomendado, Opcional"}, [63]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Grupo recomendado, Opcional", desc="Veyric Thunderhame também pode ser encontrado em Altaforja (47.10, 13.79)."}, [64]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Opcional", desc="Os quatro tipos de totem retorcido caem dos monstros do Pântano Vadeoso, de Ermos, do Pântano das Mágoas e de Desolação; colete-os pelo caminho nas próximas paradas; por fim, entregue a Veyric Thunderhame em Altaforja."}, [65]={to="Southshore", toA="{a:271}"}, [66]={npc="Phin Odelic", tgt="Phin Odelic"}, [67]={npc="Magistrado Henrique Maleb", tgt="Magistrado Henrique Maleb"}, [68]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional"}, [69]={desc="Se a pedra de regresso estiver em recarga, voe de Costa Sul a Altaforja e pegue o Metrô Correfundo de volta a Ventobravo."}}},
    ["05-d8"] = {name="Monastério Escarlate", entrance="Clareiras de Tirisfal 82.60, 33.80", pickup="Pegue as missões da masmorra ao passar: Pantanal (2ª visita). Assim não precisa voltar antes de entrar.", pickupS={{"Pegue as missões da masmorra ao passar: Pantanal (2ª visita)"}, {"Assim não precisa voltar antes de entrar"}}, steps={[1]={npc="Bibliotecária Maé Palidopó", tgt="Bibliotecária Maé Palidopó"}, [2]={to="Southshore", toA="{a:271}", desc="Você fará conexão em Altaforja."}, [3]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional"}, [4]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional, Grupo recomendado"}, [5]={npc="Olvek, o Mago", tgt="Olvek, o Mago", tag="Opcional"}, [6]={text="De Eira dos Montes, vá a oeste para a Floresta de Pinhaprata e siga pela estrada principal ao norte até Tirisfal. Contorne os guardas do Sepulcro, da Cidade Baixa e de Brill, e prossiga ao Monastério Escarlate a nordeste."}, [7]={text="Entrada: Monastério Escarlate"}, [8]={hint="Recupere o livro Mitologia dos Titãs no Monastério e leve-o para a Bibliotecária Maé Palidopó em Altaforja.", desc="Local: Estante nas últimas salas da biblioteca.", spot="Estante nas últimas salas da biblioteca."}, [9]={hint="Recupere o livro A Magia Perdida dos Mestres de Runas no Monastério Escarlate.", tag="Opcional"}, [10]={hint="Mate a Alta-inquisidora Cristalba, o Comandante Escarlate Mograine, Herodes, o Campeão Escarlate e o Mestre de Matilha Lobato, depois volte a falar com Raul, o Devotado na Costa Sul.", tag="Opcional", desc="Derrote Lobato na Biblioteca, Herodes no Arsenal e Mograine e Cristalba na Catedral. Você pode completar as alas em visitas separadas."}, [11]={npc="Olvek, o Mago", tgt="Olvek, o Mago", tag="Opcional"}, [12]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional, Requer materiais"}, [13]={npc="Bibliotecária Maé Palidopó", tgt="Bibliotecária Maé Palidopó", tag="Opcional", desc="Volte por Tirisfal e pela Floresta de Pinhaprata até a Costa Sul. Voe para Altaforja se a rota estiver disponível. Caso contrário, pegue o barco para o Porto de Menethil, siga a estrada de montanha no sul do Pantanal até Loch Modan e atravesse o túnel para Dun Morogh. Dali, siga até Altaforja. Se a Pedra de Regresso estiver pronta e vinculada a Ventobravo, você também pode voltar para lá e pegar o Metrô Correfundo."}}},
    ["03-31"] = {tips={{k="提醒", text="Rog'mar, no centro do mapa, é uma cidade da Horda; não se aproxime.", s={{"Rog'mar, no centro do mapa, é uma cidade da Horda; não se aproxime"}}}}, steps={[1]={to="Lakeshire", toA="{a:69}", tag="Antes de ir para Sendas do Rio, você pode comprar na casa de leilões (ou pedir para um alt enviar) 8 × Pedra de Afiar Maciça (para A lâmina mais afiada).", desc="A Bastilha de Ermoforte ainda não tem ponto de voo; na primeira visita, siga a estrada para o leste a partir de Vila Plácida até a entrada oeste de Sendas do Rio."}, [2]={npc="Dorin Espada-cantante", tgt="Dorin Espada-cantante", tag="Opcional, Grupo recomendado"}, [3]={text="Depois da entrada a leste das Montanhas Cristarrubra ficam as Colinas Cerdosas; os gnolls de nível 36-38 da entrada batem forte.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [4]={npc="Batedor Boleno", tgt="Batedor Boleno"}, [5]={npc="Cedrico Dalton", tgt="Cedrico Dalton"}, [6]={npc="Cedrico Dalton", tgt="Cedrico Dalton"}, [7]={npc="Cedrico Dalton", tgt="Cedrico Dalton"}, [8]={npc="Cedrico Dalton", tgt="Cedrico Dalton", tag="Opcional, Grupo recomendado", desc="Snargl é um elite de nível 40; se não conseguir vencê-lo, pule."}, [9]={npc="Nodoso", tgt="Nodoso"}, [10]={npc="Halligan Turner", tgt="Halligan Turner"}, [11]={npc="Halligan Turner", tgt="Halligan Turner"}, [12]={npc="Donoso", tgt="Donoso"}, [13]={npc="Donoso", tgt="Donoso"}, [14]={hint="Vá com Donoso salvar Nodoso.", desc="Siga Donoso para resgatar Nodoso."}, [15]={hint="Mate 8 Místicos de Cristarrubra, 8 Coureadores de Cristarrubra e 6 Brutamontes de Cristarrubra para Cedrico Dalton na Vigia do Sul."}, [16]={hint="Recupere 8 Lâminas Serrilhadas dos acampamentos dos gnolls nas Colinas Cerdosas para Halligan Turner na serraria.", desc="As lâminas de serra estão espalhadas pelo chão do acampamento dos gnolls."}, [17]={hint="Localize Snargl nas Colinas Cerdosas, mate-o e leve o focinho dele para Cedrico Dalton na Vigia do Sul.", tag="Opcional, Grupo recomendado", desc="Snargl é um elite de nível 40; se não conseguir vencê-lo, pule."}, [18]={npc="Halligan Turner", tgt="Halligan Turner"}, [19]={npc="Halligan Turner", tgt="Halligan Turner"}, [20]={npc="Eleanor Holmsby", tgt="Eleanor Holmsby"}, [21]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [22]={npc="Watcher Fredericks", tgt="Watcher Fredericks"}, [23]={npc="Cedrico Dalton", tgt="Cedrico Dalton"}, [24]={npc="Cedrico Dalton", tgt="Cedrico Dalton", tag="Opcional"}, [25]={npc="Benjy Macário", tgt="Benjy Macário"}, [26]={hint="Mate 8 Oráculos Nadalama e 8 Guerreiros Nadalama no rio perto da Granja dos Macário."}, [27]={hint="Junte 4 Cascos de Lagostim Gigante, 4 amostras de Esterco Fresco e 8 Cabeças de Murloc Nadalama para Halligan Turner.", desc="Mate os murlocs Barbatana-de-lama pela cabeça junto com os demônios d'água doce; depois vá ao norte, mate os Lagostins Grandes e pegue Adubo Fresco."}, [28]={hint="Find Robbie's Hat somewhere along the river near the murlocs.", desc="Encontre o chapéu no acampamento dos murlocs Barbatana-de-lama."}, [29]={nodeA="{a:16724}", node="Farholde Keep"}, [30]={npc="Demar Brant", tgt="Demar Brant"}, [31]={npc="Demar Brant", tgt="Demar Brant"}, [32]={npc="Demar Brant", tgt="Demar Brant"}, [33]={npc="Demar Brant", tgt="Demar Brant"}, [34]={npc="Ashe Larambar", tgt="Ashe Larambar"}, [35]={npc="Ashe Larambar", tgt="Ashe Larambar"}, [36]={npc="Brasa Gumurmúria", tgt="Brasa Gumurmúria"}, [37]={npc="Irmã Rolando", tgt="Irmã Rolando"}, [38]={npc="Bertrão Testa de Ferro", tgt="Bertrão Testa de Ferro"}, [39]={npc="Cassandra Macário", tgt="Cassandra Macário"}, [40]={hint="Elimine 5 Quiropúsculos Empoleirados na Catedral de Ermoforte para a Irmã Rolando."}, [41]={npc="Irmã Rolando", tgt="Irmã Rolando"}, [42]={npc="Irmã Rolando", tgt="Irmã Rolando", tag="Opcional, Requer materiais", desc="Requer 5 Velas Sagradas, vendidas por vendedores de reagentes. Se não tiver, pule esta missão e a seguinte."}, [43]={npc="Irmã Rolando", tgt="Irmã Rolando", tag="Opcional"}, [44]={npc="Irmã Rolando", tgt="Irmã Rolando"}, [45]={hint="Place 3 Memorial Candles on graves in the chapel graveyard for Sister Rowland at Farholde Keep.", desc="O túmulo fica ao lado da capela de Farholde."}, [46]={npc="Irmã Rolando", tgt="Irmã Rolando"}, [47]={hint="Colete 3 Feixes de Feno para Brasa no campo de treinamento.", desc="Os fardos de feno ficam nos campos perto de Farholde."}, [48]={npc="Brasa Gumurmúria", tgt="Brasa Gumurmúria"}, [49]={npc="Brasa Gumurmúria", tgt="Brasa Gumurmúria", tag="Opcional, Requer materiais", desc="Precisa de 8 × Pedra de Afiar Maciça. Compre na casa de leilões ou peça a um ferreiro. Pule se não tiver com você."}, [50]={npc="Brasa Gumurmúria", tgt="Brasa Gumurmúria", tag="Opcional"}, [51]={npc="Benjy Macário", tgt="Benjy Macário"}, [52]={npc="Benjy Macário", tgt="Benjy Macário"}, [53]={npc="Benjy Macário", tgt="Benjy Macário"}, [54]={hint="Search near the stables at Wheeler's Grange for evidence of the missing horses' whereabouts.", desc="Procure provas ao redor dos currais da fazenda."}, [55]={npc="Benjy Macário", tgt="Benjy Macário"}, [56]={npc="Benjy Macário", tgt="Benjy Macário"}, [57]={npc="Benjy Macário", tgt="Benjy Macário"}, [58]={hint="Saque de: Sootfur"}, [59]={hint="Encontre um dos cavalos que fugiram da Granja dos Macário depois do ataque dos coiotes e dê comida para ele.", desc="O cavalo perdido está perto da fazenda."}, [60]={npc="Cavalo Perdido", tgt="Cavalo Perdido"}, [61]={npc="Cavalo Perdido", tgt="Cavalo Perdido"}, [62]={hint="Leve o cavalo perdido de volta para a Granja dos Macário.", desc="Leve o cavalo perdido de volta à fazenda."}, [63]={npc="Benjy Macário", tgt="Benjy Macário"}, [64]={npc="Benjy Macário", tgt="Benjy Macário"}, [65]={npc="Robbie Holmsby", tgt="Robbie Holmsby"}, [66]={npc="Halligan Turner", tgt="Halligan Turner"}, [67]={npc="Halligan Turner", tgt="Halligan Turner"}, [68]={npc="Halligan Turner", tgt="Halligan Turner"}, [69]={hint="Plante 5 brotos pe