    ["03-32"] = {steps={[1]={to="Menethil Harbor", toA="{a:150}", desc="Você faz escala em Thelsamar."}, [2]={to="Theramore", from="Menethil Harbor", fromA="{a:150}", desc="Embarque no cais sul de Porto de Menethil."}, [3]={node="Theramore"}, [4]={to="Ratchet", toA="{a:392}"}, [5]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho"}, [6]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho"}, [7]={npc="Mestre Portuário Caruncho", tgt="Mestre Portuário Caruncho", tag="Opcional"}, [8]={to="Gadgetzan", toA="{a:976}", desc="Você fará uma conexão em Theramore. Se não liberou Geringontzan na {s:03-29}, vá de Vila Catraca para o sudoeste pelos Sertões, desça pelo Grande Elevador até Mil Agulhas e siga para leste até a Chapada Cintilante."}, [9]={text="De Geringontzan siga a estrada ao norte até Chapada Cintilante, em Mil Agulhas."}, [10]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [11]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [12]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [13]={npc="Xabu Latafuso", tgt="Xabu Latafuso"}, [14]={npc="Capu Latafuso", tgt="Capu Latafuso", tag="Opcional, Grupo recomendado"}, [15]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [16]={text="Vá para o sul até Tanaris e pegue o voo em Geringontzan."}, [17]={to="Theramore"}, [18]={text="Temperos Reconfortantes"}, [19]={npc="Guarda Byron", tgt="Guarda Byron"}, [20]={npc="Capitão Garrido Valente", tgt="Capitão Garrido Valente"}, [21]={npc="Comandante Samaul", tgt="Comandante Samaul"}, [22]={npc="Comandante Samaul", tgt="Comandante Samaul"}, [23]={npc="Tabetha", tgt="Tabetha"}, [24]={npc="Tabetha", tgt="Tabetha"}, [25]={npc="Tirth, o Mago", tgt="Tirth, o Mago"}, [26]={npc="Tirth, o Mago", tgt="Tirth, o Mago"}, [27]={hint="Encontre a frase que abre o cofre de Tirth e fale novamente com ele."}, [28]={npc="Tirth, o Mago", tgt="Tirth, o Mago"}, [29]={npc="Tirth, o Mago", tgt="Tirth, o Mago", tag="Grupo recomendado, Opcional", desc="O livro está na Bib