    ["05-d19"] = {name="Urzal dos Mortos", entrance="Sertões (1413), por volta de 49.10, 93.40 (portal no fundo do túnel de espinhos)", tips={{k="取捨", text="O Olho do Frigífero é pego nas Montanhas de Alterac, por onde a rota da Aliança não passa, então não está na lista."}, {k="說明", text="Grupo de cinco, sem chave. A entrada fica no caminho leste ao norte do Grande Elevador, diferente do Urzal dos Tuscos, a oeste.", s={{"Grupo de cinco, sem chave"}, {"A entrada fica no caminho leste ao norte do Grande Elevador, diferente do Urzal dos Tuscos, a oeste"}}}}, steps={[1]={npc="Arcebispo Benedictus", tgt="Arcebispo Benedictus", tag="Opcional", desc="Pegue ao passar por Ventobravo a partir do nível 39; se não pegar, pule."}, [2]={text="Opcional: voe de Theramore para Thalanaar, ande para o leste até o Grande Elevador, suba até os Sertões e siga o caminho de espinhos a leste até o portal da masmorra. Ao sair, voe de volta a Theramore e retome a {s:03-33}.", tag="Opcional"}, [3]={npc="Mírian Lunacanto", tgt="Mírian Lunacanto", desc="Myriam fica fora do portal, no extremo sul dos Sertões (49.01, 94.94). Pegue a missão e limpe os arredores antes de entrar."}, [4]={hint="Mate 8 Guerreiros do Urzal, 8 Tecespinhos do Urzal e 8 Sectários da Cabeça da Morte, depois fale novamente com Mírian Lunacanto perto da entrada do Urzal dos Mortos."}, [5]={npc="Mírian Lunacanto", tgt="Mírian Lunacanto"}, [6]={text="Entrada: Urzal dos Mortos"}, [7]={npc="Belnistrasz", tgt="Belnistrasz", desc="Encontre Belnistrasz nas celas. Todos devem concluir o diálogo do juramento antes de iniciar a escolta."}, [8]={hint="Se você concordar em ajudar Belnistrasz, fale novamente com ele e devolva a pedra de juramento que ele lhe deu.", desc="Local: Vá até a cela perto de Mordresh Olho de Fogo e procure Belnistrasz. Ordem: O grupo todo entrega primeiro na Pedra do Juramento e depois pega a escolta.", spot="Encontre Belnistrasz nas células próximas a Mordresh Olho-de-Fogo."}, [9]={npc="Belnistrasz", tgt="Belni