    ["03-34"] = {name="Selva do Espinhaço", steps={[1]={text="Vincule sua pedra de regresso na estalagem da Angra do Butim (27.00, 77.00).", bindA="{a:35}"}, [2]={npc="Krazek", tgt="Krazek"}, [3]={npc="Krazek", tgt="Krazek"}, [4]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [5]={npc="Kebok", tgt="Kebok"}, [6]={npc="Correspondência dos Vela Sangrenta", npcObj=true}, [7]={npc="Correspondência dos Vela Sangrenta", npcObj=true}, [8]={hint="Leve 5 Miúdos de Gorila do Vale da Névoa para \"Phillipe \"Sacode\" na Angra do Butim."}, [9]={text="Saia primeiro do vale pelo noroeste e depois siga para o norte."}, [10]={hint="Raciliano Gramos, da Expedição do Rosarães, quer que você mate 10 Panteras Umbragorja."}, [11]={hint="Recupere 8 Cristais Rolados e entregue-os a Kebok na Angra do Butim."}, [12]={hint="Rosarães Guima quer que você mate 10 Raptores Batecauda."}, [13]={hint="Consiga 15 Orelhas de Sanguescalpo e entregue-as a Kebok na Angra do Butim."}, [14]={npc="Suprimentos Completamente Saqueados", npcObj=true, desc="É preciso recuperar 8 mercadorias roubadas nas Ruínas de Zul'Kanda; procure-as pelo caminho dentro das ruínas; se não encontrar todas, pule."}, [15]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca", desc="O goblin preso nas Ruínas de Zul'Kanda."}, [16]={hint="Obtenha a Chave Primitiva com os trolls das Ruínas de Zul'Kanda, na Selva do Espinhaço, e leve-a a Zimmix Cospefaísca."}, [17]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca"}, [18]={npc="Zimmix Cospefaísca", tgt="Zimmix Cospefaísca", tag="Escolta", desc="Escolte-o para fora das ruínas e depois volte a Angra do Butim para avisar o mestre do cais."}, [19]={hint="Merília Ceireles da Expedição do Rosarães quer que você mate Sin'Dall e lhe traga a pata dela."}, [20]={hint="Leve 10 Estilhaços de Cristal Cantante para Cranque Mirrabolha."}, [21]={hint="Leve 2 Peles de Crocolisco Grande do Rio para o Drizzlik na Angra do Butim."}, [22]={npc="Raciliano Gramos", tgt="Raciliano Gramos"}, [23]={npc="R