    ["05-d18"] = {name="The Drowned City", entrance="Selva do Espinhaço 21.50, 27.70", pickup="Na segunda ida a Selva do Espinhaço, ao entregar O boateiro a Krazek em Angra do Butim, pegue também Divinassais escusos e O capitão dos Divinassais.", pickupS={{"Na segunda ida a Selva do Espinhaço, ao entregar O boateiro a Krazek em Angra do Butim, pegue também Divinassais escusos e O capitão dos Divinassais"}}, tips={{k="取捨", text="As missões de decalques e ídolos de Dibbs em Costa Sul exigem antes O mistério de Kurzen e Bruxaria trólica do Acampamento Rebelde. A rota não as inclui, então não estão na lista."}, {k="說明", text="A entrada da masmorra fica numa caverna submersa a oeste de Grom'gol. Leve poções de respiração aquática ou peça a um colega com a habilidade que a lance.", s={{"A entrada da masmorra fica numa caverna submersa a oeste de Grom'gol"}, {"Leve poções de respiração aquática ou peça a um colega com a habilidade que a lance"}}}}, steps={[1]={npc="Krazek", tgt="Krazek"}, [2]={npc="Krazek", tgt="Krazek"}, [3]={text="Opcional: encaixa melhor antes do voo para Ventobravo na Selva do Espinhaço. De Angra do Butim, siga a costa oeste para o norte passando por Grom'gol até o lado oeste do recife e mergulhe na caverna submersa até o portal. Ao sair, entregue em Angra do Butim e retome a {s:03-35}.", tag="Opcional"}, [4]={text="Entrada: The Drowned City"}, [5]={hint="Colete 10 Artefatos Infusos em Vodu de piratas Divinassais na Cidade Afogada.", desc="Se não conseguir juntar tudo, continue limpando piratas na área dos navios. Local: entre na área do navio pirata de Saltseer e saqueie artefatos dos piratas pelo caminho. Ordem: limpe na mesma área do Capitão Saltseer.", spot="Elimine os piratas Saltseer perto dos navios e saqueie os artefatos."}, [6]={hint="Mate 3 Legistas Divinassais e o Capitão Pavoral na Cidade Afogada.", desc="Local: Vá à área dos navios e limpe os legistas nas passagens perto do capitão. Ordem: Interaja com a pérola brilhante depois de matar o 