    ["03-36"] = {steps={[1]={to="Darkshire", toA="{a:42}"}, [2]={npc="Mestre-Vigia Sorigal", tgt="Mestre-Vigia Sorigal"}, [3]={text="De Vila Sombria, vá para leste pela Trilha do Vento Morto até o Pântano das Mágoas."}, [4]={npc="Vigia Biggs", tgt="Vigia Biggs"}, [5]={hint="Leve 10 Partículas de Pó Onírico para Krazek na Angra do Butim. O Pó Onírico é coletado dos dragonetes no Pântano das Mágoas."}, [6]={hint="Mate 8 Crocoliscos Dentesserras Jovens, 10 Tece-mágoas e 10 Jaguares do Pântano, então fale novamente com Vigia Biggs no Pântano das Mágoas."}, [7]={npc="Vigia Biggs", tgt="Vigia Biggs"}, [8]={npc="Vigia Biggs", tgt="Vigia Biggs"}, [9]={npc="Clava de Noboru", npcObj=true, tag="Opcional", desc="Clique com o botão direito em Clava de Noboru na bolsa para iniciar a missão. Mate Noboru, a Borduna, para pegar uma clava cinza e clique com o botão direito para iniciar a missão."}, [10]={npc="Magtoor", tgt="Magtoor", tag="Opcional"}, [11]={npc="Magtoor", tgt="Magtoor"}, [12]={hint="Leve 6 Cristais de Draenetista para Magtoor no Pântano das Mágoas."}, [13]={hint="Encontre o Baú da Caravana no Retiro Alqueivado, obtenha os Reagentes do Teurgo e leve-os para Vigia Biggs."}, [14]={npc="Galen Boaguarda", tgt="Galen Boaguarda"}, [15]={hint="Escolte Galen até a segurança para, então, encontrar seu acampamento no Pântano das Mágoas e abrir seu cofre.", tag="Escolta", desc="Siga Galen para fora do Retiro Alqueivado (o acampamento dos Perdidos); os monstros no caminho o atacam, então proteja-o; depois da escolta, vá ao acampamento dele e abra o cofre."}, [16]={npc="Cofre do Galen", npcObj=true}, [17]={npc="Magtoor", tgt="Magtoor"}, [18]={npc="Vigia Biggs", tgt="Vigia Biggs"}, [19]={npc="Vigia Biggs", tgt="Vigia Biggs"}, [20]={hint="Leve 8 peças de Madeira Flutuante Seca ao Sol para Vigia Biggs no Pântano das Mágoas."}, [21]={hint="Brohann Barrilga, em Ventobravo, quer que você saia à procura do Templo de Atal'Hakkar.", desc="Conclui ao se aproximar do Templo Submerso."}, [22]=