    ["03-37"] = {tips={{k="提醒", text="Rog'mar, no centro do mapa, é uma cidade da Horda; não se aproxime.", s={{"Rog'mar, no centro do mapa, é uma cidade da Horda; não se aproxime"}}}}, steps={[1]={to="Farholde Keep", toA="{a:16724}", tag="Antes de ir para Sendas do Rio, você pode comprar na casa de leilões (ou pedir para um alt enviar) 20 × Magitrama (para Curativos para os feridos).", desc="Você faz escala em Vila Sombria e Vila Plácida."}, [2]={npc="Demar Brant", tgt="Demar Brant"}, [3]={npc="Demar Brant", tgt="Demar Brant"}, [4]={npc="Demar Brant", tgt="Demar Brant", desc="Você precisa entregar antes o Registro do Marechal-de-campo ativado por drop para poder pegá-la."}, [5]={npc="Ashe Larambar", tgt="Ashe Larambar"}, [6]={npc="Bertrão Testa de Ferro", tgt="Bertrão Testa de Ferro"}, [7]={npc="Irmão Lowley", tgt="Irmão Lowley", tag="Opcional, Requer materiais", desc="Precisa de 20 × Magitrama. Dá para comprar na casa de leilões. Pule se não tiver com você."}, [8]={npc="Irmão Lowley", tgt="Irmão Lowley", tag="Opcional"}, [9]={npc="Irmão Lowley", tgt="Irmão Lowley"}, [10]={hint="Enfaixe 3 Soldados Feridos para o Irmão Lowley.", desc="Os soldados feridos estão bem ao lado do Irmão Lowley."}, [11]={npc="Irmão Lowley", tgt="Irmão Lowley"}, [12]={npc="Irmão Lowley", tgt="Irmão Lowley"}, [13]={npc="Irmã Rolando", tgt="Irmã Rolando"}, [14]={npc="Tessa Claraurora", tgt="Tessa Claraurora"}, [15]={hint="Junte 6 Maçãs Frescas para Tessa Claraurora na Bastilha de Ermoforte.", desc="As maçãs frescas ficam sob as árvores frutíferas perto de Farholde."}, [16]={npc="Tessa Claraurora", tgt="Tessa Claraurora"}, [17]={npc="Tessa Claraurora", tgt="Tessa Claraurora"}, [18]={hint="Colete 3 Peles de Coiote para Tessa Claraurora na Bastilha de Ermoforte."}, [19]={npc="Tessa Claraurora", tgt="Tessa Claraurora"}, [20]={npc="Tessa Claraurora", tgt="Tessa Claraurora"}, [21]={npc="Vigia Cornélio", tgt="Vigia Cornélio"}, [22]={text="Do Mirante de Terral, vá para o oeste, passando ao sul de Sol