    ["05-d21"] = {name="Maraudon", entrance="Desolação 29.10, 62.50", pickup="Se já estiver no nível 39 no Pântano Vadeoso, pegue a missão dos fragmentos sombrios com o Arquimago Tervosh em Theramore. O resto se pega em Desolação: Talendria e o Guardião Marandis no Posto do Nijel, Faia, o Centauro Pária e, por fim, Cavindra na entrada da caverna.", pickupS={{"Se já estiver no nível 39 no Pântano Vadeoso, pegue a missão dos fragmentos sombrios com o Arquimago Tervosh em Theramore"}, {"O resto se pega em Desolação: Talendria e o Guardião Marandis no Posto do Nijel, Faia, o Centauro Pária e, por fim, Cavindra na entrada da caverna"}}, tips={{k="取捨", text="Para pegar o cetro na primeira corrida, faça as duas linhas, laranja e roxa. Se quiser só a princesa e o crocodilo, quem do grupo tiver o cetro pode entrar direto na ala interna. Se a missão exigir criaturas sombrias fora da masmorra ou outro ramo, não pule pelo atalho."}, {k="說明", text="29.10, 62.50 é a entrada da caverna, ao ar livre; para achar os dois portais da masmorra, o laranja e o roxo, siga o túnel da cor correspondente. O caminho roxo e o laranja se encontram perto da cachoeira de água envenenada.", s={{"29.10, 62.50 é a entrada da caverna, ao ar livre; para achar os dois portais da masmorra, o laranja e o roxo, siga o túnel da cor correspondente"}, {"O caminho roxo e o laranja se encontram perto da cachoeira de água envenenada"}}}}, steps={[1]={npc="Arquimago Tervosh", tgt="Arquimago Tervosh"}, [2]={text="Opcional: voe do Domínio de Plumaluna para o Posto do Nijel para pegar as missões, depois vá ao sul atrás de Faia e do Centauro Pária e, por fim, à caverna de Maraudon, a sudoeste. Ao sair, voe para a Vila de Rut'theran e retome a {s:04-42}.", tag="Opcional"}, [3]={npc="Talendria", tgt="Talendria"}, [4]={npc="Guardião Marandis", tgt="Guardião Marandis"}, [5]={npc="Faia", tgt="Faia"}, [6]={npc="Centauro Pária", tgt="Centauro Pária", desc="O Centauro Pária patrulha o sul de Desolação."}, [7]={npc="Pilar de Shen'dralar", npcObj=true, tag="Opcional"}, [8]={hint="Explore Shen'dralas para tentar encontrar outros pilares como o primeiro.", tag="Opcional"}, [9]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [10]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="Pilares estranhos"}, [11]={hint="Recupere estilhaços e fragmentos dos pilares, que estão protegidos nas aldeias dos Magram e dos Gelkis. Leve-os de volta a Morden Sombracerta.", tag="Opcional", desc="As coordenadas são, em ordem, os dois itens nas aldeias de centauros Magram e Gelkis."}, [12]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [13]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", desc="Verifique no registro de missões a quantidade de mana necessária.", preText="Fragmentos dos pilares"}, [14]={hint="Obtenha o Filtro de Mana dentro do templo em Shen'dralas e use-o para coletar Cristais de Mana Ancestral. Quando tiver obtido mana suficiente, potencialize os pilares e fale novamente com Morden Sombracerta.", tag="Opcional", desc="A quantidade de mana depende do seu diário de missões. Pegue a peneira no andar mais alto do templo e reúna 8 de mana no total, 4 por torre. As torres oeste e leste podem ser usadas em furtividade."}, [15]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", desc="Verifique no registro de missões a quantidade de mana necessária."}, [16]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="Potencializando os pilares"}, [17]={hint="Fale com Morden Sombracerta em Shen'dralas para obter informações sobre os cristais que você consertou.", tag="Opcional"}, [18]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional"}, [19]={npc="Morden Sombracerta", tgt="Morden Sombracerta", tag="Opcional", preText="Uma breve aula de história"}, [20]={hint="Localize o Magíster Kirandis dentro do templo de Shen'dralas.", tag="Opcional"}, [21]={npc="Magíster Kirandis", tgt="Magíster Kirandis", tag="Opcional"}, [22]={npc="Mithera", tgt="Mithera", tag="Opcional", preText="Conhecendo o magíster"}, [23]={hint="Investigue os Jardins Desolados perto de Shen'dralas e então fale novamente com Mithera no templo próximo.", tag="Opcional"}, [24]={npc="Mithera", tgt="Mithera", tag="Opcional"}, [25]={npc="Mithera", tgt="Mithera", tag="Opcional", preText="Jardins Desolados"}, [26]={npc="Selwyrd", tgt="Selwyrd", tag="Opcional"}, [27]={npc="Selwyrd", tgt="Selwyrd", tag="Opcional", desc="Entregue A palavra da floresta primeiro. Traga isso para o Maraudon interno.", preText="A palavra da floresta"}, [28]={npc="Cavindra", tgt="Cavindra", desc="Cavindra está fora do portal laranja. Saqueie um item do chefe de cada lado."}, [29]={hint="Colete 10 Fragmentos de Lascanegra em Maraudon e leve-os para o Arquimago Tervosh, em Theramore, na costa do Pântano Vadeoso."}, [30]={text="Entrada: Maraudon"}, [31]={text="Lado laranja: Caverna Esporelama (45-53). Procure por cristais laranja e pela piscina no fundo da caverna. Preencha o frasco antes de entrar no portal."}, [32]={hint="Encha a Ampola Cerúlea Tampada na poça de cristal laranja, em Maraudon.", desc="Local: Encha o frasco na piscina fora do portal laranja. Encontre vinhas dentro.", spot="Encha o frasco na piscina fora do portal laranja. Encontre vinhas dentro."}, [33]={text="Lado roxo: Wicked Grotto (45-53). Pegue a passagem de cristal roxo na bifurcação de três vias. Saqueie o diamante de Lorde Torpelíngua."}, [34]={hint="Colete 25 Entalhes de Cristal Terádrico para Faia, na Desolação.", desc="Guie-se pela quantidade do seu diário de missões. Local: Mate primeiro os centauros nas cavernas externas laranja e roxa e, depois de entrar, saqueie as estátuas por todo o caminho.", spot="Mate centauros fora de ambos os portais e saqueie estátuas conforme avança."}, [35]={hint="Leia as Instruções do Pária. Depois, obtenha em Maraudon o Amuleto da União e devolva-o ao Centauro Pária, na parte sul de Desolação.", desc="O primeiro fica entre as linhas laranja e roxa. O segundo e o terceiro ficam nas passagens fora das portas. O quarto e o quinto ficam atrás das portas laranja e roxa, cada um em patrulha. Local: Encontre os três primeiros na bifurcação laranja e roxa e nas duas cavernas externas, e um atrás de cada porta.", spot="Encontre os três primeiros khans na bifurcação laranja/roxa e nas duas cavernas externas, depois um dentro de cada portal."}, [36]={hint="Recupere as duas partes do Cetro de Celebras: o Bastão de Celebras e o Diamante de Celebras.", desc="Local: Pegue a varinha na linha laranja e o diamante na roxa e lute com Celebras no ponto de encontro. Ordem: É preciso passar pelas linhas laranja e roxa. Só entregue quando tiver todos os materiais.", spot="Pegue a varinha na linha laranja e o diamante na roxa. Mate Celebras no ponto de encontro."}, [37]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="Depois de derrotar o chefe, fale com Celebras, o Redimido. Depois da derrota, entregue ao Redimido na sala.", spot="Na sala do chefe Celebras: Celebras, o Redimido"}, [38]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="O Redimido está na sala do chefe; siga-o durante o ritual.", preText="Lendas de Maraudon"}, [39]={hint="Ajude Celebras, o Redimido, a criar o Cetro de Celebras.", desc="O Redimido está na sala do chefe. Siga-o durante o ritual. Local: Sala do chefe de Celebras: siga o Redimido durante todo o ritual.", spot="Siga Celebras, o Redimido através do ritual na sala do chefe."}, [40]={npc="Celebras, o Redimido", tgt="Celebras, o Redimido", desc="O Redimido está na sala do chefe; siga-o durante o ritual.", spot="Na sala do chefe Celebras: Celebras, o Redimido"}, [41]={text="Rota interna: Cachoeiras do Canção Telúrica (48-57). Desça da junção laranja/roxa ou faça com que um jogador com o cetro abra o atalho."}, [42]={hint="Vá até Maraudon, recupere uma Ampola de Água da Canção Telúrica e entregue-a a Selwyrd nos Jardins Desolados, em Desolação.", tag="Opcional", desc="Putrigarra patrulha o poço; a pequena fonte fica na superfície da água. Pule na piscina de Putrigarra, abaixo da caverna da Princesa. Encontre a fonte na superfície da água. Use primeiro a fonte na superfície e depois mergulhe.", spot="Pule na piscina de Putrigarra, abaixo da caverna da Princesa. Encontre a fonte na superfície da água."}, [43]={hint="Mate a Princesa Theradras e fale novamente com o Guardião Marandis no Posto do Nijel, na Desolação.", desc="Local: Siga pelas Cachoeiras do Canção Telúrica até a caverna de Zaetar e chegue à plataforma da Princesa.", spot="Siga pelas Cachoeiras do Canção Telúrica até a caverna de Zaetar e chegue à plataforma da Princesa."}, [44]={npc="Espírito de Zaetar", tgt="Espírito de Zaetar", desc="O espírito de Zaetar aparece depois que a princesa Theradras morre. Pegue a missão agora e entregue fora da masmorra."}, [45]={npc="Guardião Marandis", tgt="Guardião Marandis"}, [46]={npc="Talendria", tgt="Talendria"}, [47]={npc="Faia", tgt="Faia"}, [48]={npc="Centauro Pária", tgt="Centauro Pária"}, [49]={npc="Arquimago Tervosh", tgt="Arquimago Tervosh"}, [50]={hint="Vá até Maraudon, recupere uma Ampola de Água da Canção Telúrica e entregue-a a Selwyrd nos Jardins Desolados, em Desolação.", tag="Opcional"}, [51]={npc="Selwyrd", tgt="Selwyrd", tag="Opcional"}, [52]={hint="Procure Remulos, na Clareira da Lua, e entregue a ele a Semente da Vida.", desc="Guarde para quando passar pela Clareira da Lua."}, [53]={npc="Guardião Remulos", tgt="Guardião Remulos", desc="Pode esperar até a Clareira da Lua."}}},
    ["04-42"] = {grind={[1]={mob="Estalagarra da Areia", note="A praia em frente ao Domínio de Plumaluna, na outra margem; você chega assim que desce do barco."}, [2]={mob="Guerreiro Cristafúria", note="Nagas no extremo sul da Ilha de Sardor; perto do Domínio, de nível um pouco mais baixo."}}, steps={[1]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [2]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [3]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [4]={npc="Feralas: Uma História", npcObj=true}, [5]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [6]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [7]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus.", tag="Você já pode comprar na casa de leilões (ou pedir para um alt enviar) 15 × Seda (para Calça arriada!, mais tarde na Garganta Abrasadora)."}, [8]={npc="Gracinha Forçânima", tgt="Gracinha Forçânima"}, [9]={npc="Tyrande Murmuréolo", tgt="Tyrande Murmuréolo"}, [10]={bindA="{a:1116}"}, [11]={desc="O Templo Submerso só pode ser aceita no nível 46; se faltar pouco, mate monstros perto do Domínio de Plumaluna até o 46; O círculo de pedra vem logo depois dela."}, [12]={npc="Ângela Brisaluna", tgt="Ângela Brisaluna"}, [13]={to="Gadgetzan", toA="{a:976}"}, [14]={npc="Crista Dapinote", tgt="Crista Dapinote"}, [15]={npc="Crista Dapinote", tgt="Crista Dapinote"}, [16]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [17]={hint="Use o treco de coleta vazio junto à poça d'água perto do Posto Silitriste. Depois que você coletar a amostra, leve o treco de coleta cheio para o Topógrafo Sênior Secamolha em Geringontzan."}, [18]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [19]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}}},
    ["04-43"] = {steps={[1]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [2]={npc="Andi Lynn", tgt="Andi Lynn", tag="Opcional"}, [3]={npc="Tran'rek", tgt="Tran'rek", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [4]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [5]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [6]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [7]={hint="Andi Lynn em Geringontzan quer que você destrua o Complexo Dunamalho. Para isso, deve matar 10 Brutamontes Dunamalho, 10 Impositores Dunamalho e Gor'marok, o Assolador.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [8]={hint="O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você um recupere bracelete particularmente brilhante que foi perdido próximo ao complexo ôgrico de Dunamalho."}, [9]={hint="Leve cinco Pedaços de Inseto Centiparte do Covil Nóxio para o Alquimista Almofarrista em Geringontzan."}, [10]={hint="Marlon Catarrebite, em Tanaris, quer que você colete 30 Ornamentos de Gahz'ridian."}, [11]={hint="Colete uma Glândula de Orvalho Cheia e leve para Marin Nublacuca em Geringontzan."}, [12]={hint="Tran'rek, em Geringontzan, quer que você mate 8 Moitagulhas Rotos e 8 Fazraízes Moitagulhas.", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [13]={npc="Transmissor de Emergência OOX-17/TN", npcObj=true, tag="Aceite se cair, Opcional", desc="Clique com o botão direito em Transmissor de Emergência OOX-17/TN na bolsa para aceitar a missão."}, [14]={npc="Tuga", tgt="Tuga", tag="Opcional, Escolta, Faça se você ver", desc="Aceite a missão somente se encontrar Tooga e puder escoltá-lo a pé."}, [15]={hint="Leve Tuga até a mulher dele, Tarta.", tag="Opcional, Escolta", desc="Escolte Tooga a pé até Torta, a sudoeste do Porto Bondebico. Cuidado com as emboscadas."}, [16]={npc="Robô Teleguiado OOX-17/TN", tgt="Robô Teleguiado OOX-17/TN", tag="Opcional", desc="Missão de escolta: em grupo, espere todos estarem no mesmo ponto antes de aceitar e desligue o aceite automático."}, [17]={npc="Robô Teleguiado OOX-17/TN", tgt="Robô Teleguiado OOX-17/TN", tag="Opcional"}, [18]={hint="Escolte o OOX-17/TN até Porto de Bondebico e apresente-se ao Olhatorto Obnótico, na Angra do Butim.", tag="Opcional"}, [19]={hint="Escolte o OOX-17/TN até Porto de Bondebico e apresente-se ao Olhatorto Obnótico, na Angra do Butim.", tag="Opcional", desc="Escolta falhou: abandone a missão no registro e aceite-a de novo com o robô."}, [20]={npc="Yeh'kinya", tgt="Yeh'kinya"}, [21]={npc="Tarta", tgt="Tarta", tag="Opcional, Escolta"}, [22]={text="A escolta de Tooga falhou. Você pode continuar pela rota principal. Para tentar de novo, abandone a missão e procure Tooga outra vez."}, [23]={npc="Chefe de Segurança Silvadágua", tgt="Chefe de Segurança Silvadágua"}, [24]={npc="Andi Lynn", tgt="Andi Lynn", tag="Opcional"}, [25]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [26]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [27]={npc="Sguisha", tgt="Sguisha"}, [28]={npc="Sguisha", tgt="Sguisha"}, [29]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [30]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [31]={npc="Tran'rek", tgt="Tran'rek"}, [32]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [33]={text="O equipamento fica no fundo da caverna; desça a rampa a partir da entrada (55.00, 70.00 → 54.20, 72.90 → 56.30, 72.20)."}, [34]={hint="Descubra qual foi a sina do Topógrafo Júnior Caranduru, e leve ele ou seus equipamentos de topografia para o Topógrafo Sênior Secamolha, em Geringontzan."}, [35]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [36]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [37]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [38]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista"}, [39]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [40]={npc="Topógrafo Sênior Secamolha", tgt="Topógrafo Sênior Secamolha"}, [41]={to="Theramore"}, [42]={to="Menethil Harbor", toA="{a:150}", from="Theramore", desc="O barco do cais de Theramore vai direto para Porto de Menethil."}, [43]={to="Stormwind", desc="Se você não pegou Em busca do templo, não precisa ir a Ventobravo; voe direto de Porto de Menethil para Costa Sul."}, [44]={npc="Brohann Barrilga", tgt="Brohann Barrilga"}, [45]={npc="Brohann Barrilga", tgt="Brohann Barrilga"}}},
    ["04-44"] = {grind={[1]={mob="Feruja Selvagem", note="Bosque no centro das Terras Agrestes; muitos monstros, os mesmos das Penas de Coruscante."}, [2]={mob="Espreitador Jubaprata", note="As alcateias mais a leste; espalhadas, dá para matar um de cada vez."}}, steps={[1]={to="Southshore", toA="{a:271}", desc="Se Costa Sul não estiver liberada, voe até Porto de Menethil, pegue o barco para Auberdine no cais norte e desça em Costa Sul."}, [2]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional"}, [3]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional, Grupo recomendado", desc="Derrote Lobato na Biblioteca, Herodes no Arsenal e Mograine e Cristalba na Catedral. Você pode completar as alas em visitas separadas."}, [4]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional, Requer materiais"}, [5]={text="Pegue a trilha da montanha para nordeste até as Terras Agrestes."}, [6]={npc="Falstad Martelo Feroz", tgt="Falstad Martelo Feroz"}, [7]={nodeA="{a:348}", node="Aerie Peak"}, [8]={npc="Falstad Martelo Feroz", tgt="Falstad Martelo Feroz"}, [9]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [10]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [11]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [12]={npc="Explodar Mantrovejante", tgt="Explodar Mantrovejante"}, [13]={npc="Explodar Mantrovejante", tgt="Explodar Mantrovejante"}, [14]={text="Vincule sua pedra de regresso na estalagem do Ninho da Águia (13.80, 41.60).", bindA="{a:348}"}, [15]={npc="Rapsódico Festanjeiro", tgt="Rapsódico Festanjeiro", desc="No caminho para as ferujas; a continuação exige levar bebida, não aceite."}, [16]={hint="Pegue 15 Penas de Coruscante nas Terras Agrestes para Erelas Ambarcéu na Vila de Rut'theran."}, [17]={hint="Verifique as jaulas nas duas aldeias Cascasseca, depois fale novamente com o Mestre de Grifos Garra-de-acha."}, [18]={desc="Se ainda não estiver no nível 47, siga para o leste e mate Ferujas Selvagens e Espreitadores Jubaprata até o 47, coletando Penas de Coruscante de passagem."}, [19]={hint="Leve 5 Colares Tribais Troll para Explodar Mantrovejante no Ninho da Águia."}, [20]={hint="Sguisha, em Geringontzan, quer que você colete um Tragão Violeta e fale novamente com ela."}, [21]={hint="Mate 10 Lodos Verdes e 10 Gosmas Jade, depois apresente-se novamente a Explodar Mantrovejante no Ninho da Águia."}, [22]={npc="Explodar Mantrovejante", tgt="Explodar Mantrovejante"}, [23]={npc="Explodar Mantrovejante", tgt="Explodar Mantrovejante"}, [24]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [25]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [26]={hint="Verifique o topo do Altar de Zul, depois fale novamente com o Mestre de Grifos Garra-de-acha."}, [27]={npc="Transmissor de Emergência OOX-09/HL", npcObj=true, tag="Aceite se cair, Opcional", desc="Clique com o botão direito em Transmissor de Emergência OOX-09/HL na bolsa para aceitar a missão."}, [28]={npc="Robô Teleguiado OOX-09/HL", tgt="Robô Teleguiado OOX-09/HL", tag="Opcional"}, [29]={npc="Robô Teleguiado OOX-09/HL", tgt="Robô Teleguiado OOX-09/HL", tag="Opcional"}, [30]={hint="Escolte o OOX-09/HL até a costa além dos Penhascos Panorâmicos, então se apresente a Olhatorto Obnótico, na Angra do Butim.", tag="Opcional"}, [31]={hint="Escolte o OOX-09/HL até a costa além dos Penhascos Panorâmicos, então se apresente a Olhatorto Obnótico, na Angra do Butim.", tag="Opcional", desc="Escolta falhou: abandone a missão no registro e aceite-a de novo com o robô."}, [32]={hint="Use a Superinstantânea FX para tirar uma foto da Gammerita, depois fale novamente com Daryn Aelumnis na Vila de Rut'theran."}, [33]={hint="Aldo Isque, na Angra do Butim, quer que você leve para ele as garrafas de Xerez de Pupellyverbos que ele perdeu."}, [34]={bindA="{a:348}"}, [35]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [36]={npc="Mestre de Grifos Garra-de-acha", tgt="Mestre de Grifos Garra-de-acha"}, [37]={to="Thelsamar", toA="{a:144}"}, [38]={text="Vincule sua Pedra de Regresso na estalagem de Thelsamar (35.40, 48.40).", bindA="{a:144}"}, [39]={text="Saia de Loch Modan pelo sul e pegue aqui a trilha da montanha para os Ermos."}, [40]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Grupo recomendado, Opcional", desc="Você precisa concluir Auxílio elemental (Urzal dos Tuscos) e Tempestade, terra e fogo antes de poder aceitar esta."}, [41]={hint="Saque de: Tempestade Devastadora", tag="Grupo recomendado, Opcional", desc="Voe da Ponta do Refúgio para o Porto de Menethil, pegue o barco do cais sul até Theramore, voe para Thalanaar e caminhe para o leste até Mil Agulhas."}, [42]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Grupo recomendado, Opcional", desc="Voe de Thalanaar para Theramore, pegue o barco até o Porto de Menethil e voe para a Ponta do Refúgio."}, [43]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Opcional"}, [44]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", tag="Opcional"}, [45]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos"}, [46]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", desc="Precisa de Presa de Sanguescalpo ×30, Raiz-da-vida ×8 e Essência dos Exilados ×1. Para Essência dos Exilados, leve 8 × de cada um de Patuá Ardente, Patuá Trovejante e Patuá Pontudo ao caldeirão ao lado. Raiz-da-vida e os três patuás podem ser comprados na casa de leilões."}, [47]={hint="Leve os itens listados no Pergaminho de Bath'rah para Bath'rah, o Vigia dos Ventos, em Alterac."}, [48]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos"}, [49]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos"}, [50]={hint="Leve o Coração Rodopiante para Bath'rah, o Vigia dos Ventos."}, [51]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos"}, [52]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", desc="Recompensa: uma arma do redemoinho."}, [53]={npc="Bath'rah, o Vigia dos Ventos", tgt="Bath'rah, o Vigia dos Ventos", desc="Recompensa: uma arma do redemoinho."}}},
    ["04-45"] = {tips={{k="取捨", text="Mate os cinco itens de coleta juntos. Para entregar tudo, são necessários 5 mandíbulas, 6 pulmões de javali, 6 pinças de escorpião, 11 cérebros de lagarto e 14 moelas de abutre. Cada entrega consome materiais."}, {k="取捨", text="Se houver muita disputa pelos urubus ou pelos basiliscos, deixe A mordida do basilisco ou O vigor do abutre inacabada e siga para o norte até o Pântano das Mágoas, como planejado."}}, grind={[1]={mob="Capataz Ferro Negro", note="Anões Ferro Negro nos arredores do Caldeirão; nível adequado."}, [2]={mob="Feitor Ferro Negro", note="Lado sul do Caldeirão; nível um pouco mais baixo, monstros espalhados."}}, steps={[1]={npc="Sigrun Derrubaferro", tgt="Sigrun Derrubaferro", tag="Opcional", desc="Pelo caminho, você costuma conseguir Encantamentos de Labareda Abrasadora. Se não cair nenhum, abandone."}, [2]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional", desc="É preciso matar dois dracos negros elite de nível 50; pule se não tiver grupo."}, [3]={hint="Use o Signo da Terra para ativar os Pilares de Ametista, Opala e Diamante, e obter as Pedras Rúnicas.", tag="Faça depois, quando passar por lá, Grupo recomendado, Opcional"}, [4]={npc="Selo da Terra", npcObj=true, tag="Grupo recomendado, Opcional"}, [5]={npc="Selo da Terra", npcObj=true, tag="Grupo recomendado, Opcional"}, [6]={npc="Garek", tgt="Garek", tag="Grupo recomendado, Opcional"}, [7]={npc="Sigrun Derrubaferro", tgt="Sigrun Derrubaferro", tag="Opcional"}, [8]={hint="Mate o Embaixador Infernus na Fortaleza Angor e leve a prova de sua morte para o Conselheiro Belgrum em Altaforja.", tag="Grupo recomendado, Opcional"}, [9]={text="Das Ermos, vá para oeste e entre na Garganta Abrasadora pela trilha da montanha ao lado do acampamento da Horda em Karrath. Contorne Karrath.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [10]={npc="Banheiro de Madeira", npcObj=true, desc="Seda pode ser comprada na casa de leilões. Você precisa de 15."}, [11]={hint="Mate 8 Geólogos Ferro Negro e leve 15 pedaços de Seda para a pessoa que está trancada na casinha na Garganta Abrasadora."}, [12]={text="Mate Margol, a Enfurecida, para ganhar muita experiência.", tag="Opcional", desc="O Chifre de Margol inicia a cadeia de missões da Chave da Garganta Abrasadora; se não quiser enfrentá-lo, pule: as etapas relacionadas mais adiante serão puladas automaticamente e, no fim, você voa de Altaforja de volta ao Posto de Tório."}, [13]={npc="Chifre de Margol", npcObj=true, tag="Opcional, Grupo recomendado", desc="Clique com o botão direito em Chifre de Margol na bolsa para iniciar a missão."}, [14]={npc="Banheiro de Madeira", npcObj=true}, [15]={npc="Banheiro de Madeira", npcObj=true, tag="Opcional", desc="A entrega pede quatro coisas: o livro-caixa ao lado da latrina, pernas de Aranha Teia-de-vidro ×20, o pacote atrasado do Pântano Vadeoso e a espada de Jarquia do Pântano das Mágoas. Não vá de propósito buscar o que faltar."}, [16]={hint="Pegue a cópia do Livro-Caixa de Rugov A. Massoaço e encontre os itens listados antes de ir falar com ele em Tanaris.", tag="Requer materiais"}, [17]={npc="Dório Tratapedra", tgt="Dório Tratapedra", desc="Escolte Dório para o norte; depois da emboscada, pegue a Carta Chamuscada no local e entregue."}, [18]={npc="Carta Chamuscada", npcObj=true}, [19]={npc="Carta Chamuscada", npcObj=true}, [20]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [21]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [22]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [23]={nodeA="{a:1446}", node="Thorium Point"}, [24]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true, tag="Grupo recomendado, Opcional", desc="O Capataz Maltorius é uma elite de nível 50; pule se não tiver grupo."}, [25]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true}, [26]={npc="Procurados/Desaparecidos/Achados e Perdidos", npcObj=true}, [27]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [28]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada", tag="Opcional"}, [29]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [30]={npc="Mestre Ferreiro Queimatar", tgt="Mestre Ferreiro Queimatar"}, [31]={bindA="{a:144}"}, [32]={npc="Montanhista Pedrabrita", tgt="Montanhista Pedrabrita", tag="Opcional"}, [33]={npc="Montanhista Pedrabrita", tgt="Montanhista Pedrabrita"}, [34]={to="Altaforja"}, [35]={npc="Veyric Tonitrular", tgt="Veyric Tonitrular", tag="Opcional"}, [37]={npc="Curador Tórius", tgt="Curador Tórius"}, [38]={npc="Curador Tórius", tgt="Curador Tórius"}, [39]={npc="Curador Tórius", tgt="Curador Tórius", tag="Opcional"}, [40]={npc="Curador Tórius", tgt="Curador Tórius"}, [41]={npc="Conselheiro Belgrum", tgt="Conselheiro Belgrum", tag="Grupo recomendado, Opcional"}, [42]={npc="Conselheiro Belgrum", tgt="Conselheiro Belgrum", tag="Opcional, Grupo recomendado"}, [43]={to="Thelsamar", toA="{a:144}", tag="Opcional", desc="Só volte à Montanhista Pedrabrita para pegar a chave se tiver Finalmente!; se não tiver, pule e voe direto de Altaforja de volta ao Posto de Tório."}, [44]={npc="Montanhista Pedrabrita", tgt="Montanhista Pedrabrita", tag="Opcional"}, [45]={text="Use a chave da Garganta Abrasadora que acabou de pegar para abrir o portão ao lado da montanhista Pebblebitty e atravesse o túnel até a Garganta Abrasadora.", tag="Opcional"}, [46]={to="Thorium Point", toA="{a:1446}", desc="Se não tiver a chave da Garganta Abrasadora, voe direto de Altaforja de volta à Garganta Abrasadora. Se você já entrou pelo túnel, pule."}, [47]={hint="Colete 4 Corações das Chamas e 4 globos de Óleo de Golem, e leve-os para Velarok Lamicélere."}, [48]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [49]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [50]={hint="Encontre e devolva o Alcaraviz de Ferraria e a Luneta do Espia ao Capataz Scrange na Garganta Abrasadora."}, [51]={hint="Mate 15 Capatazes Ferro Negro e 15 Feitores Ferro Negro. Depois, fale novamente com Capataz Scrange, na Garganta Abrasadora."}, [52]={hint="Hansel Mão-pesada quer que você mate 20 Golens de Guerra Pesados."}, [53]={hint="Hansel Mão-pesada quer que você mate 20 Grandes Aranhas de Lava na Garganta Abrasadora. Você pode encontrá-las nos platôs e poços de lava do local.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [54]={text="Da entrada leste onde ficam os mineiros, vire à direita e siga pelo corredor inferior à margem da lava até a caverna dos incendossauros."}, [55]={hint="Hansel Mão-pesada quer que você mate 20 Incendossauros."}, [56]={desc="Se ainda faltar experiência para o nível 48, continue na mina e atraia os incendossauros normais um de cada vez pelo corredor já limpo. Se não houver alvos seguros, saia pelo mesmo caminho e termine o nível nos feitores ou escravistas Ferro Negro nos arredores da Caldeira."}, [57]={hint="Nas profundezas do Fosso de Lava do Caldeirão, na Garganta Abrasadora, você encontrará o anão traidor dos Ferro Negro chamado Feitor Maltorius.", tag="Faça depois, quando passar por lá, Grupo recomendado, Opcional"}, [58]={text="No acesso leste aos planos, atravesse a ponte e vire à esquerda no salão. Os planos ficam na plataforma superior, sobre a mesa atrás do feitor. Se houver elites de guarda, pule esta etapa e retome quando estiver livre ou com um grupo."}, [59]={hint="Em algum lugar do Fosso de Lava do Caldeirão você encontra as Instruções Secretas: Fluxo Ígneo que o Feitor Maltorius roubou. Encontre as instruções e devolva-as ao Mestre Ferreiro Queimatar na Garganta Abrasadora.", desc="O feitor Maltorius ou uma sentinela de elite pode guardar a plataforma superior. Se estiver só, veja se o caminho até a mesa está livre. Só a missão de recompensa exige matar o feitor."}, [60]={hint="Leve 8 Punhais de Placas de Tório para Velarok Lamicélere."}, [61]={npc="Arqueólogo Moribundo", tgt="Arqueólogo Moribundo"}, [62]={npc="Arqueólogo Moribundo", tgt="Arqueólogo Moribundo"}, [63]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [64]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Opcional"}, [65]={hint="Encontre o Artefato Misterioso que está protegido pelos Idólatras do Martelo do Crepúsculo no quadrante noroeste da Garganta Abrasadora.", tag="Faça depois, quando passar por lá", desc="O artefato fica no acampamento do Crepúsculo ao lado do poço de lava ao norte, guardado por idólatras do Crepúsculo de elite nível 49-51. Espere os elites se afastarem, pegue e saia. Se não conseguir, pule esta etapa e a entrega de Liberta os outros."}, [66]={hint="Encontre e leve um Símbolo de Ragnaros para Velarok Lamicélere.", tag="Grupo recomendado, Opcional, Faça depois, quando passar por lá", desc="Só os elites derrubam o Símbolo de Ragnaros."}, [67]={npc="Zamael Luncardo", tgt="Zamael Luncardo"}, [68]={npc="Zamael Luncardo", tgt="Zamael Luncardo"}, [69]={npc="Zamael Luncardo", tgt="Zamael Luncardo", tag="Grupo recomendado, Opcional"}, [70]={npc="Capitão-vigia Lolo Longalcance", tgt="Capitão-vigia Lolo Longalcance", tag="Grupo recomendado, Opcional"}, [71]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [72]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada", tag="Opcional"}, [73]={npc="Hansel Mão-pesada", tgt="Hansel Mão-pesada"}, [74]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [75]={npc="Capataz Scrange", tgt="Capataz Scrange"}, [76]={npc="Mestre Ferreiro Queimatar", tgt="Mestre Ferreiro Queimatar"}, [77]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina", tag="Opcional"}, [78]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [79]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [80]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [81]={npc="Tocha da Retribuição", npcObj=true}, [82]={npc="Kalaran Finalâmina", tgt="Kalaran Finalâmina"}, [83]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque"}, [84]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque"}, [85]={hint="Incendeie as Torres de Sentinela Norte, Sul, Leste e Oeste usando a Tocha da Retribuição dentro de cada prédio."}, [86]={npc="Altar de Suntara", npcObj=true}, [87]={npc="Arqueólogo Moribundo", tgt="Arqueólogo Moribundo", tag="Grupo recomendado, Opcional", desc="Latórico, o Negro, e Obsidião são ambos elites de nível 52; procure um grupo para fazer."}, [88]={hint="Mate Obsidião e Latórico, o Negro, e então fale novamente com Tórius em Altaforja com o Coração de Obsidião e a Cabeça de Latórico, o Negro.", tag="Grupo recomendado, Opcional"}, [89]={npc="Escudeiro Maltraque", tgt="Escudeiro Maltraque"}, [90]={npc="Tesouro da Revoada Negra", npcObj=true}, [91]={npc="Tesouro da Revoada Negra", npcObj=true, desc="Guarde a Muda de Pele da Revoada Negra e entregue a Ciro Terepento nas Estepes Ardentes."}, [92]={tag="Opcional, Grupo recomendado", desc="Upe aqui até o 52 só com grupo para o Abismo Rocha Negra. Sozinho, pule."}, [93]={to="Altaforja", desc="Se a pedra de regresso estiver pronta, use-a para voltar a Thelsamar e voe de lá; se não, volte ao Posto de Tório (37.90, 30.40) e procure o mestre de voo."}, [94]={npc="Curador Tórius", tgt="Curador Tórius", tag="Grupo recomendado, Opcional"}, [95]={npc="Alto-explorador Magellas", tgt="Alto-explorador Magellas"}, [96]={npc="Alto-explorador Magellas", tgt="Alto-explorador Magellas", desc="Só dá para aceitar depois de fazer Os discos de platina em Uldaman."}, [97]={npc="Historiador Karnik", tgt="Historiador Karnik"}, [98]={npc="Historiador Karnik", tgt="Historiador Karnik"}, [99]={text="Vincule sua Pedra de Regresso na estalagem de Altaforja (18.60, 51.60).", bind="Altaforja"}, [100]={to="Nethergarde Keep", toA="{a:1438}", desc="Se a Bastilha de Etergarde não estiver liberada, voe até Vila Sombria, vá para leste pela Trilha do Vento Morto até o Pântano das Mágoas e depois para o sul, pela Barreira do Inferno, até a Bastilha de Etergarde."}, [101]={npc="Tádius Sombraustera", tgt="Tádius Sombraustera"}, [102]={npc="Tádius Sombraustera", tgt="Tádius Sombraustera", tag="Opcional, Grupo recomendado"}, [103]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [104]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [105]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [106]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [107]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [108]={hint="Traga três Mandíbulas de Rasgarrindo, dois Pulmões de Javali Destroçados e uma Tenaz de Escórpode para o Mago Sangrento Drazial."}, [109]={hint="Leve 3 Pulmões de Javali Destroçado, 2 Tenazes de Escórpode e 1 Cérebro de Basilisco para o Mago Sangrento Drazial."}, [110]={hint="Leve 3 Tenazes de Escórpode, 2 Moelas de Abutre e 1 Pulmão de Javali Destroçado para o Mago Sangrento Drazial."}, [111]={hint="Leve 10 Cérebros de Basilisco e 2 Moelas de Abutre para a Maga Sangrenta Lynnore."}, [112]={hint="Leve 10 Moelas de Abutre e 2 Mandíbulas de Rasgarrindo para a Maga Sangrenta Lynnore."}, [113]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [114]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [115]={npc="Mago Sangrento Drazial", tgt="Mago Sangrento Drazial"}, [116]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [117]={npc="Maga Sangrenta Lynnore", tgt="Maga Sangrenta Lynnore"}, [118]={npc="Charada do Cortello", npcObj=true, tag="Aceite se cair, Opcional", desc="Clique com o botão direito em Charada do Cortello na bolsa para iniciar a missão."}, [119]={text="Do acampamento dos magos de sangue, volte à estrada do norte, saia das Terras Devastadas para o norte, entrando no Pântano das Mágoas, e siga a estrada para o oeste até o lado oeste do pântano."}, [120]={npc="Pergaminho Encharcado", npcObj=true}, [121]={npc="Pergaminho Encharcado", npcObj=true}}},
    ["04-46"] = {grind={[1]={mob="Gorila Grenhacéu", note="A ilhota onde fica o Rei Mukla; monstros comuns. Limpe-os de passagem depois de matar o rei."}, [2]={mob="Desconhecido", note="Lado oeste da mesma ilha."}}, steps={[1]={to="Booty Bay", toA="{a:35}", desc="O Pântano das Mágoas não tem ponto de voo da Aliança: vá para oeste pela Trilha do Vento Morto de volta a Vila Sombria e voe de lá."}, [2]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [3]={npc="Cranque Mirrabolha", tgt="Cranque Mirrabolha"}, [4]={npc="Aldo Isque", tgt="Aldo Isque"}, [5]={npc="MacKinley Lobo do Mar", tgt="MacKinley Lobo do Mar"}, [6]={npc="Fino Algazarro", tgt="Fino Algazarro"}, [7]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [8]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [9]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [10]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [11]={npc="Olhatorto Obnótico", tgt="Olhatorto Obnótico", tag="Opcional"}, [12]={npc="Bilhete Cuidadosamente Dobrado", npcObj=true, desc="Clique com o botão direito em Bilhete Cuidadosamente Dobrado na bolsa para iniciar a missão. Clique agora com o botão direito no bilhete dobrado que você pegou antes para iniciar a missão."}, [13]={npc="Princesa Manda-chuva", tgt="Princesa Manda-chuva"}, [14]={npc="Princesa Manda-chuva", tgt="Princesa Manda-chuva", tag="Grupo recomendado, Opcional"}, [15]={hint="Mate o Rei Mukla e fale novamente com a Princesa Manda-chuva com a Chave para libertá-la.", tag="Grupo recomendado, Opcional"}, [16]={npc="Princesa Manda-chuva", tgt="Princesa Manda-chuva", tag="Grupo recomendado, Opcional"}, [17]={npc="Mandingueiro Unbagwa", tgt="Mandingueiro Unbagwa", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [18]={hint="Saque de: Gorila do Vale da Névoa, Trovejador da Selva, Gorila Costalva Enfurecido", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [19]={npc="Mandingueiro Unbagwa", tgt="Mandingueiro Unbagwa", desc="Aceite Febre da Selva do Espinhaço antes de entregar as presas para acionar o evento."}, [20]={hint="Procure o Mandingueiro Unbagwa e faça-o evocar Mokk, o Selvagem. Leve o Coração de Mokk para Fino Algazarro.", desc="Entregar Febre da Selva do Espinhaço invoca Mokk. Se faltarem presas de gorila ou não aguentar as ondas de gorilas, pule esta etapa e a entrega de Febre da Selva do Espinhaço abaixo; nada depois depende disso."}, [21]={desc="Se ainda não estiver no nível 49, continue matando gorilas no Vale da Névoa até o 49."}, [22]={npc="Fino Algazarro", tgt="Fino Algazarro"}, [23]={to="Ratchet", toA="{a:392}", from="Booty Bay", fromA="{a:35}"}, [24]={hint="Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca."}, [25]={to="Theramore"}, [26]={npc="Pergaminho Mofado", npcObj=true}, [27]={npc="Pergaminho Mofado", npcObj=true, tag="Opcional"}}},
    ["05-d22"] = {name="Alcaz Prison", entrance="Pântano Vadeoso 75.30, 14.10", pickup="Na {s:04-46}, antes de voar de Vila Sombria para Angra do Butim, voe primeiro a Ventobravo se estiver no nível 48 e pegue a missão com o Mestre Mathias Shaw. Quando a {s:04-46} terminar com o voo para Theramore, procure Saulo Maclério para continuar.", pickupS={{"Na {s:04-46}, antes de voar de Vila Sombria para Angra do Butim, voe primeiro a Ventobravo se estiver no nível 48 e pegue a missão com o Mestre Mathias Shaw"}, {"Quando a {s:04-46} terminar com o voo para Theramore, procure Saulo Maclério para continuar"}}, tips={{k="提醒", text="Opcional a partir do nível 48: combinem antes de entrar que vão poupar o Interrogador. Depois de derrotar o chefe final, falem com o prisioneiro acorrentado. Aceitem a missão, voltem para matar o Interrogador e levem a chave ao prisioneiro.", s={{"Opcional a partir do nível 48: combinem antes de entrar que vão poupar o Interrogador"}, {"Depois de derrotar o chefe final, falem com o prisioneiro acorrentado"}, {"Aceitem a missão, voltem para matar o Interrogador e levem a chave ao prisioneiro"}}}}, steps={[1]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw"}, [2]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [3]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [4]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [5]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [6]={hint="Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."}, [7]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [8]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [9]={npc="Saulo Maclério", tgt="Saulo Maclério", tag="Opcional"}, [10]={text="Opcional: de Theramore, siga a costa leste para o norte até a margem nordeste do Pântano Vadeoso e nade até a Ilha de Alcaz; o portal fica no corredor sob a torre da ilha. Ao sair, entregue em Theramore e retome a {s:04-47}.", tag="Opcional"}, [11]={text="Entrada: Alcaz Prison"}, [12]={hint="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary.", tag="Opcional", desc="Local: Encontre Senhora das Marés Ca'zass pelas células superiores. Limpe as nagas ao longo do corredor.", spot="Encontre Senhora das Marés Ca'zass pelas células superiores. Limpe as nagas ao longo do corredor."}, [13]={hint="Enter Alcaz Prison and learn what became of the King of Stormwind.", desc="Local: Abra a porta inferior e mate o último chefe; depois entre na câmara dos fundos e procure o bilhete no chão. Ordem: Pegue primeiro a chave com o carcereiro.", spot="Abra a porta inferior e mate o último chefe. Encontre a nota na sala escondida."}, [14]={npcObj=true, spot="Bilhete no chão da sala secreta atrás de Blazeroar"}, [15]={npcObj=true}, [16]={tag="Opcional", desc="Depois do chefe final, fale com o prisioneiro acorrentado ao lado. O interrogador precisa estar vivo para você conseguir a chave."}, [17]={hint="Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison.", tag="Opcional"}, [18]={tag="Opcional", spot="Ao lado do chefe final, o prisioneiro acorrentado"}, [19]={npc="Saulo Maclério", tgt="Saulo Maclério", tag="Opcional"}, [20]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [21]={npc="Saulo Maclério", tgt="Saulo Maclério"}, [22]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", desc="Entregue na próxima vez que passar por Ventobravo."}}},
    ["04-47"] = {steps={[1]={to="Gadgetzan", toA="{a:976}", desc="O pergaminho está na caverna de raptores a sudoeste do Pântano Vadeoso. Caminhe primeiro para o leste de volta a Theramore (67.48, 51.30) e depois voe."}, [2]={npc="Rugov A. Massoaço", tgt="Rugov A. Massoaço", tag="Requer materiais"}, [3]={npc="Sguisha", tgt="Sguisha"}, [4]={npc="Sguisha", tgt="Sguisha"}, [5]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [6]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [7]={npc="Marin Nublacuca", tgt="Marin Nublacuca"}, [8]={text="De Geringontzan siga a estrada ao norte até Chapada Cintilante, em Mil Agulhas."}, [9]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [10]={npc="Kravel Barbakarvão", tgt="Kravel Barbakarvão"}, [11]={npc="Chefe dos Boxes Gnomo", tgt="Chefe dos Boxes Gnomo"}, [12]={npc="Capu Latafuso", tgt="Capu Latafuso", tag="Opcional"}, [13]={npc="Capu Latafuso", tgt="Capu Latafuso", tag="Opcional, Grupo recomendado"}, [14]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite"}, [15]={npc="Pedestal de Uldum", npcObj=true}, [16]={npc="Vigia Pétreo de Norgannon", tgt="Vigia Pétreo de Norgannon"}, [17]={npc="Pedestal de Uldum", npcObj=true}, [18]={npc="Pedestal de Uldum", npcObj=true}, [19]={text="Vá para noroeste até o início da trilha para a Cratera Un'Goro."}}},
    ["04-48"] = {grind={[1]={mob="Açoitadeira Pétala Sangrenta", note="As plantas do lado leste; mate-as assim que entrar na cratera."}, [2]={mob="Gorila de Un'Goro", note="Do lado de fora da caverna dos gorilas, a nordeste; os mesmos monstros das peles de gorila."}, [3]={mob="Pterrordax", note="O paredão a leste do Refúgio do Marshal."}, [4]={mob="Tocaieiro de Piche", note="Os poços de piche ao sul do acampamento; nível um pouco alto, puxe um de cada vez."}}, steps={[1]={text="Pela estrada de montanha a oeste de Tanaris, desça a rampa até a Cratera Un'Goro. Torwa Mateiro está bem ao lado da entrada, no fim da rampa.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [3]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [4]={npc="Bote Naufragado", npcObj=true, desc="Colete 7 cristais de cada cor (vermelho, azul, verde e amarelo) e pegue \"Um Diário Destroçado\" dos raptores."}, [5]={npc="Um Pacote Pequeno", npcObj=true}, [6]={npc="Um Pacote Pequeno", npcObj=true}, [7]={hint="Encontre a carcaça mais recente de uma presa morta por Lar'korwi e roube um Pedaço de Carcaça de Manguadonte. Depois disso, fale novamente com Torwa Mateiro na Cratera Un'Goro."}, [8]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [9]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [10]={hint="Leve 2 Glândulas de Feromônio de Ravassauro para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro."}, [11]={npc="Escama Infusa com Cristal", npcObj=true, tag="Opcional"}, [12]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional, Requer materiais"}, [13]={text="Use a Escama Infusa com Cristal na bolsa para iniciar Contaminação microcristalina. Depois, entregue as duas missões a Torwa."}, [14]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [15]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Opcional"}, [16]={hint="Use o conteúdo do Bornal do Torwa para evocar Lar'korwi e derrotá-lo. Então, leve a Cabeça do Lar'korwi para Torwa Mateiro, que está perto da entrada da Cratera Un'Goro.", tag="Grupo recomendado, Opcional", desc="Esta é mais difícil. Pode deixar para quando voltar a Un'Goro."}, [17]={npc="Karna Trilheiro", tgt="Karna Trilheiro"}, [18]={npc="Linken", tgt="Linken"}, [19]={npc="Linken", tgt="Linken"}, [20]={nodeA="{a:541}", node="Marshal's Refuge"}, [21]={npc="Williden Marshal", tgt="Williden Marshal"}, [22]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [23]={npc="Chispa Minanilo", tgt="Chispa Minanilo"}, [24]={npc="J.D. Neri", tgt="J.D. Neri", desc="Colete cristais de poder pelo caminho. Se já tiver sete de cada cor ao encontrar J.D. Neri pela primeira vez, entregue-os na hora. Se faltarem cristais, conclua na próxima visita."}, [25]={npc="Cuidado com o Pterrordax", npcObj=true}, [26]={npc="Melco", tgt="Melco"}, [27]={npc="Chislo", tgt="Chislo"}, [28]={hint="Leve 8 Ossos de Dinossauro para Chispa Minanilo na Cratera Un'Goro."}, [29]={hint="Leve 2 Pelagens de Gorila de Un'Goro, 2 Pelagens de Pisoteador de Un'Goro, 2 Pelagens de Trovejador de Un'Goro para Torwa Mateiro na entrada da Cratera Un'Goro.", tag="Faça se aguentar mobs de nível mais alto, Opcional"}, [30]={desc="Se ainda não estiver no nível 50, fique do lado de fora da caverna dos gorilas e mate Gorilas de Un'Goro até o 50."}, [31]={hint="Colha 15 Pétalas Sangrentas e fale novamente com Melco."}, [32]={text="Pegue o caixote de mantimentos no acampamento a leste."}, [33]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [34]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [35]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [36]={text="Para a amostra, entre na colmeia: vá para sudoeste até a entrada da caverna e siga para dentro (50.40, 78.80 → 48.70, 85.20)."}, [37]={hint="Use a Ampola de Amostra para coletar uma Amostra de Parede de Colmeia de uma das incubadoras Gorishi na Cratera Un'Goro. Procure as câmaras com larvas."}, [38]={text="Termine as missões de matar e coletar que você tem."}, [39]={hint="Leve um Caixote de Comestíveis e o Equipamento de Pesquisa para Williden Marshal in Cratera Un'Goro.", desc="O Caixote de Comestíveis fica a leste (a caminho da caverna dos gorilas e de Torwa) e o Equipamento de Pesquisa a sudoeste (no caminho da colmeia aos pterrordáctilos), então pegue um de cada no caminho."}, [40]={hint="Colete 8 Escamas de Dimetrodonte Palmado e 8 Escamas de Pterrordax Palmado para Chislo no Refúgio do Marshal."}, [41]={hint="Mate 10 Pterrordaxes e 15 Pterrordaxes Frenéticos, então fale com Espraga Froque no Refúgio do Marshal."}, [42]={npc="Chislo", tgt="Chislo"}, [43]={npc="Melco", tgt="Melco"}, [44]={npc="Melco", tgt="Melco"}, [45]={npc="Espraga Froque", tgt="Espraga Froque"}, [46]={npc="Chispa Minanilo", tgt="Chispa Minanilo"}, [47]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal"}, [48]={npc="Williden Marshal", tgt="Williden Marshal"}, [49]={npc="Um Diário Destroçado", npcObj=true, tag="Opcional", desc="Clique com o botão direito para aceitar só se conseguir Um Diário Destroçado dos monstros."}, [50]={npc="Williden Marshal", tgt="Williden Marshal", tag="Opcional"}, [51]={desc="Se ainda não estiver no nível 51, mate pterrordaxes a leste do acampamento ou Tocaieiros de Piche nos poços de piche ao sul até o 51."}, [52]={bind="Altaforja", desc="Se sua Pedra de Regresso estiver vinculada a Altaforja, espere até poder usá-la para voltar à cidade. Sacerdotes podem aceitar «Ajuda aos cenarianos» com o Sumo Sacerdote Rohan. Magos que quiserem aceitar «Magiaria» podem procurar Dink."}, [53]={text="Só vá se quiser aceitar a missão de introdução de Ventobravo: pegue o Metrô Correfundo de Altaforja para Ventobravo.", tag="Opcional"}, [54]={npc="Maginor Dumas", tgt="Maginor Dumas", tag="Opcional", desc="Você pode pular a introdução de Ventobravo. Ao chegar a Azshara, ainda é preciso procurar primeiro Sanath Lim-yo para ser teleportado ao alto do penhasco."}, [55]={text="Voe de Ventobravo para o Porto de Menethil e retome a rota.", tag="Opcional"}, [56]={npc="Sumo Sacerdote Rohan", tgt="Sumo Sacerdote Rohan", tag="Você já pode comprar na casa de leilões (ou pedir para um alt enviar) 1 × Linfa de Morte-viva (para A linfa de morte-viva, mais tarde em Azshara).", desc="Entregue a Ogtinc em Azshara."}, [57]={to="Menethil Harbor", toA="{a:150}", desc="Confira o mapa de voos no Refúgio do Marshal. Voe para Auberdine ou para a Vila de Rut'theran se houver um voo disponível. Caso contrário, volte a Tanaris pela rampa a sudeste e confira os voos em Geringontzan."}, [58]={to="Auberdine", from="Menethil Harbor", fromA="{a:150}", desc="Este barco faz parada em Costa Sul. Desça em Auberdine."}, [59]={to="Rut'theran Village", toA="{a:702}", desc="Faça a conexão em Auberdine para a Vila de Rut'theran. Se estiver a bordo, desembarque quando o navio atracar. Pegue um voo disponível ou o navio no píer norte (33.3, 39.8)."}, [60]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [61]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [62]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [63]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus.", tag="Você já pode comprar na casa de leilões (ou pedir para um alt enviar) 1 × Carcaça de Mithril (para Procura-se A-Me 01, mais tarde na Cratera Un'Goro)."}, [64]={npc="Gracinha Forçânima", tgt="Gracinha Forçânima"}, [65]={npc="Gracinha Forçânima", tgt="Gracinha Forçânima"}, [66]={npc="Astarii Mirestela", tgt="Astarii Mirestela", tag="Grupo recomendado, Opcional"}, [67]={npc="Dorion", tgt="Dorion", desc="Aceite em Darnassus (ou Altaforja, Ventobravo) e entregue a Ogtinc em Azshara."}, [68]={text="Entre no portal de Darnassus para voltar à Vila de Rut'theran."}, [69]={to="Astranaar", toA="{a:415}"}, [70]={text="Vincule sua Pedra de Regresso na estalagem de Astranaar (37.00, 49.20).", bindA="{a:415}"}, [71]={text="Confira sua localização. Se estiver a bordo, espere o navio atracar no seu destino antes de desembarcar. Em Auberdine, faça a conexão para a Vila de Rut'theran. Em terra na vila, entregue suas missões."}, [72]={text="Antes de ir aos Reinos do Leste para aceitar uma missão de classe, confira no Refúgio do Marshal se há um voo para Auberdine. Caso não haja voo disponível, volte a Tanaris pela rampa a sudeste e confira os voos em Geringontzan. Ao chegar a Auberdine, pegue o barco direto para Ventobravo."}, [73]={text="Em Auberdine, pegue o barco direto para Ventobravo. Se ainda estiver a bordo, espere o barco atracar antes de desembarcar e vá esperar no píer de embarque para Ventobravo (30.5, 40.9)."}, [74]={text="No Porto de Ventobravo, espere o barco de volta para Auberdine no píer (21.8, 56.9). Ao desembarcar em Auberdine, retome a rota em Kalimdor."}, [75]={text="Confira primeiro sua localização e o espaço no registro de missões. Se for aos Reinos do Leste para aceitar uma missão de classe, deixe uma vaga livre. Se ainda estiver a bordo, espere o barco atracar no porto de destino antes de desembarcar."}, [76]={text="Desembarque quando o barco atracar no Porto de Ventobravo e procure na cidade o NPC que oferece sua missão de classe. Se ainda estiver em alto-mar, permaneça a bordo."}, [77]={npc="Irmão Josué", tgt="Irmão Josué"}, [78]={npc="Dink", tgt="Dink", tag="Opcional"}, [79]={text="Consulte o mestre de voo de Altaforja para ver se há um voo para o Porto de Menethil. Se não houver, pegue o Metrô Correfundo até Ventobravo e embarque no porto para Auberdine."}, [80]={to="Talrendis Point", toA="{a:3137}"}, [81]={npc="Loh'atu", tgt="Loh'atu"}, [82]={npc="Loh'atu", tgt="Loh'atu"}, [83]={hint="Destrua 6 Aparições Altaneiras e 6 Subliches Altaneiros. Depois, fale com Loh'atu em Azshara."}, [84]={hint="Mate 6 Sátiros Haldarr, 2 Trapaceiros Haldarr e 2 Devotos Vil Haldarr. Depois, fale novamente com Loh'atu na fronteira do Vale Gris."}, [85]={npc="Loh'atu", tgt="Loh'atu"}, [86]={npc="Loh'atu", tgt="Loh'atu"}, [87]={npc="Sanath Lim-yo", tgt="Sanath Lim-yo", tag="Opcional", desc="Só entregue aqui se tiver aceitado a introdução."}, [88]={text="Fale com Sanath Lim-yo e peça que ele o teleporte ao alto do penhasco para encontrar o Arquimago Tauriel."}, [89]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel"}, [90]={hint="Leve 10 Poeiras Reluzentes para o Arquimago Tauriel."}, [91]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", desc="A poeira fica ao pé da montanha; volte a Sanath Lim-yo do mesmo modo para ser teleportado para cima."}, [92]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel"}, [93]={hint="Obtenha 6 Corais Encantados e entregue-os ao Arquimago Tauriel."}, [94]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel"}, [95]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Grupo recomendado, Opcional", desc="Morphaz fica no Templo de Atal'Hakkar."}, [96]={hint="Recupere o Estilhaço Arcano de posse de Morphaz e fale novamente com o Arquimago Tauriel.", tag="Grupo recomendado, Opcional", desc="Morphaz fica no Templo de Atal'Hakkar."}, [97]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Grupo recomendado, Opcional", desc="Morphaz fica no Templo de Atal'Hakkar."}, [98]={text="Siga para a Selva Maleva via Astranaar. Se a sua Pedra de Regresso estiver vinculada a Astranaar e disponível, use-a para voltar à estalagem. Depois de descer do penhasco com segurança, consulte o mapa de voo no Campo Talrendis. Voe para Astranaar se puder. Caso contrário, siga a estrada principal para oeste pela parte leste do Vale Gris. De Astranaar, siga a estrada principal para o norte até a Selva Maleva."}, [99]={npc="Ogtinc", tgt="Ogtinc"}, [100]={npc="Ogtinc", tgt="Ogtinc"}, [101]={hint="Obtenha 4 Glândulas de Ginete Saudável leve-as para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath."}, [102]={npc="Ogtinc", tgt="Ogtinc"}, [103]={npc="Ogtinc", tgt="Ogtinc", desc="Linfa de Morte-viva ×1: dá para comprar na casa de leilões."}, [104]={hint="Obtenha uma Linfa de Morte-viva para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath."}, [105]={npc="Ogtinc", tgt="Ogtinc"}, [106]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="Morphaz fica no Templo de Atal'Hakkar."}, [107]={text="Se ainda estiver em Azshara, volte à Ponta Talrendis, voe para Astranaar e siga ao norte até a Selva Maleva. Ao sair do templo, vá direto ao Santuário Esmeralda na Selva Maleva."}, [108]={npc="Ogtinc", tgt="Ogtinc", desc="Aceite em Darnassus (ou Altaforja, Ventobravo) e entregue a Ogtinc em Azshara."}, [109]={npc="Ogtinc", tgt="Ogtinc"}, [110]={hint="Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath."}, [111]={npc="Ogtinc", tgt="Ogtinc"}, [112]={npc="Ogtinc", tgt="Ogtinc"}, [113]={hint="Leve 6 Escamas de Fura-ondas para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath."}, [114]={npc="Ogtinc", tgt="Ogtinc"}, [115]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="O draco verde fica no Templo de Atal'Hakkar."}, [116]={hint="Leve o Dente de Morphaz para Ogtinc em Azshara. Ogtinc mora no alto dos penhascos a nordeste das Ruínas de Eldarath.", tag="Grupo recomendado, Opcional", desc="O draco verde fica no Templo de Atal'Hakkar."}, [117]={npc="Ogtinc", tgt="Ogtinc", tag="Grupo recomendado, Opcional", desc="O draco verde fica no Templo de Atal'Hakkar."}, [118]={text="Volte ao Campo Talrendis e voe para Astranaar; depois siga a estrada para o norte até entrar na Selva Maleva."}, [119]={to="Astranaar", toA="{a:415}"}}},
    ["04-49"] = {grind={[1]={mob="Guardião de Jaedenar", note="Região da entrada de Jaedenar; monstros comuns."}, [2]={mob="Sectário de Jaedenar", note="Misturados com os Guardiões; conjuradores."}}, steps={[1]={text="De Astranaar, siga a estrada para o norte até a Selva Maleva.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={npc="Arathandris Argencélio", tgt="Arathandris Argencélio"}, [3]={npc="Grazle", tgt="Grazle"}, [4]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [5]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", tag="Grupo recomendado, Opcional, Requer materiais"}, [6]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [7]={npc="Taronn Pena Vermelha", tgt="Taronn Pena Vermelha"}, [8]={hint="Grazle quer que você prove seu valor matando 6 Guerreiros de Lenha Morta, 6 Desbravadores de Lenha Morta e 6 Jardineiros de Lenha Morta. Quando você terminar, fale novamente com ele na parte sul da Selva Maleva, perto do Santuário Esmeralda."}, [9]={npc="Grazle", tgt="Grazle"}, [10]={npc="Grazle", tgt="Grazle"}, [11]={hint="Mate 11 Devotos Vis Flamejade, 9 Assombrantes Flamejade, 9 Desgarrados Flamejade e Xavathras. Fale novamente com Eridan Brisazul na Selva Maleva quando a tarefa estiver completa."}, [12]={hint="Entre em Jaedenar e mate 4 Cães de Jaedenar, 4 Guardas de Jaedenar, 6 Adeptos de Jaedenar e 6 Sectários de Jaedenar. Depois, fale novamente com Greta Musgo no Casco, na Selva Maleva."}, [13]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [14]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [15]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [16]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [17]={hint="Leve o Cantil Vazio para o Poço Lunar no meio de Jaedenar e encha-o. Depois, fale novamente com Greta Musgo no Casco na Selva Maleva."}, [18]={desc="Mate monstros perto de 35, 59 em Jaedenar."}, [19]={hint="Procure e destrua 2 Feras Entrópicas e 2 Horrores Entrópicos enquanto explora o Vale das Escaras Pungentes. Depois de ver se as crateras ainda estão cheias de água contaminada com vileza, fale novamente com Taronn Pena Vermelha, na Selva Maleva."}, [20]={hint="Eridan Brisazul, na Selva Maleva, quer que você mate 8 Infernarautos Flamejade, 8 Traidores Flamejade, 8 Trapaceiros Flamejade e Xavaric. Fale novamente com Eridan quando a tarefa estiver concluída."}, [21]={npc="Flauta de Xavaric", npcObj=true, desc="Clique com o botão direito em Flauta de Xavaric na bolsa para iniciar a missão."}, [22]={hint="Leve a Flauta de Xavaric e 5 amostras de Ligavil de Flamejade para Eridan Brisazul, na parte sul da Selva Maleva."}, [23]={hint="Leve 15 Âmbares de Sangue para Arathandris Argencélio na Selva Maleva."}, [24]={nodeA="{a:1998}", node="Talonbranch Glade"}, [25]={npc="Nafien", tgt="Nafien"}, [26]={npc="Nafien", tgt="Nafien"}, [27]={hint="Nafien quer que você mate 6 Vigias do Covil de Lenha Morta, 6 Vingadores de Lenha Morta e 6 Xamãs de Lenha Morta. Fale novamente com ele na parte norte da Selva Maleva, perto da entrada do Domínio dos Presamatos."}, [28]={npc="Nafien", tgt="Nafien"}, [29]={text="Entre aqui na caverna do Domínio dos Presamatos e atravesse-a para chegar a Hibérnia."}, [30]={node="Clareira da Lua", desc="Na caverna de Domínio dos Presamatos há uma bifurcação para Clareira da Lua; vá primeiro abrir o ponto de voo e depois volte à caverna e siga para Hibérnia. Na parte do Monte Hyjal mais adiante, você voará para Clareira da Lua."}, [31]={npc="Salfa", tgt="Salfa"}, [32]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [33]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [34]={npc="Meggi Roquenrou", tgt="Meggi Roquenrou"}, [35]={npc="Jéssica Trilharrubra", tgt="Jéssica Trilharrubra"}, [36]={nodeA="{a:2255}", node="Everlook"}, [37]={npc="Niby, o Todo-poderoso", tgt="Niby, o Todo-poderoso"}, [38]={npc="Diabretim", tgt="Diabretim"}, [39]={npc="Diabretim", tgt="Diabretim", desc="Tecido Vil ×1: dá para comprar na casa de leilões."}, [40]={hint="Leve um pedaço de Tecido Vil para Diabretim, em Selva Maleva."}, [41]={npc="Diabretim", tgt="Diabretim"}, [42]={npc="Diabretim", tgt="Diabretim"}, [43]={hint="Leve 10 pedaços de Madeira Podre e 4 Essências de Peçonha para Diabretim em Selva Maleva."}, [44]={npc="Diabretim", tgt="Diabretim"}, [45]={npc="Diabretim", tgt="Diabretim", tag="Grupo recomendado, Opcional"}, [46]={hint="Leve um total de 6 Penas Vodu dos trolls do templo submerso.", tag="Grupo recomendado, Opcional"}, [47]={npc="Diabretim", tgt="Diabretim", tag="Grupo recomendado, Opcional"}, [48]={npc="Diabretim", tgt="Diabretim"}, [49]={hint="Leve três Essências Vis Impecáveis, originárias de três locais distintos, para Diabretim na Selva Maleva."}, [50]={npc="Diabretim", tgt="Diabretim"}, [51]={npc="Diabretim", tgt="Diabretim", desc="Kroshius fica no norte da Selva Maleva. É preciso grupo."}, [52]={hint="Procure os restos mortais de Kroshius no Vale das Escaras Pungentes, que fica na Selva Maleva. Ao encontrá-los, use o Fogo Vil perto deles e aguarde o retorno de Kroshius. Quando o infernal acordar, mate-o e retire do corpo dele o Núcleo Infernal de Kroshius.", desc="Kroshius fica no norte da Selva Maleva. É preciso grupo."}, [53]={npc="Niby, o Todo-poderoso", tgt="Niby, o Todo-poderoso", desc="Kroshius fica no norte da Selva Maleva. É preciso grupo."}}},
    ["05-d14"] = {name="Templo de Atal'Hakkar", entrance="Pântano das Mágoas (1435), 69.50, 52.50. Marca a parte externa do templo.", steps={[1]={npc="Ângela Brisaluna", tgt="Ângela Brisaluna", tag="Pré-requisito de masmorra"}, [2]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Pré-requisito de masmorra"}, [3]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Pré-requisito de masmorra"}, [4]={hint="Busque o Círculo de Pedra na oficina de Marlon Catarrebite em Vila Catraca.", tag="Pré-requisito de masmorra"}, [5]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", tag="Pré-requisito de masmorra"}, [6]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", preText="O círculo de pedra"}, [7]={npc="Marlon Catarrebite", tgt="Marlon Catarrebite", preText="O círculo de pedra"}, [8]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [9]={hint="Capture os espíritos de 3 guinchadores em Feralas, e depois fale novamente com Yeh'kinya no Porto de Bondebico.", tag="Pré-requisito de masmorra", desc="Mate gritadores do vale na costa da Ilha do Medo, em Feralas. Use a Morácea de Yeh'Kinya em cada cadáver e fale com o espírito que aparecer, até o registro de missões contar três."}, [10]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [11]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [12]={hint="Leve a Primeira e a Segunda Tabuleta Mosh'Aru para Yeh'kinya, em Tanaris.", tag="Pré-requisito de masmorra"}, [13]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [14]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [15]={hint="Leve o Ovo Velho para Yeh'kinya, em Tanaris.", tag="Pré-requisito de masmorra"}, [16]={npc="Yeh'kinya", tgt="Yeh'kinya", tag="Pré-requisito de masmorra"}, [17]={npc="Yeh'kinya", tgt="Yeh'kinya", preText="O ovo velho"}, [18]={npc="Arquimago Tauriel", tgt="Arquimago Tauriel", tag="Pré-requisito de masmorra"}, [19]={hint="Leve 10 Poeiras Reluzentes pa