    ["04-52"] = {name="Cratera Un'Goro", steps={[1]={to="Marshal's Refuge", toA="{a:541}"}, [2]={npc="Linken", tgt="Linken"}, [3]={npc="Linken", tgt="Linken"}, [4]={npc="J.D. Neri", tgt="J.D. Neri"}, [5]={npc="J.D. Neri", tgt="J.D. Neri"}, [6]={npc="Espraga Froque", tgt="Espraga Froque"}, [7]={npc="Hol'anyee Marshal", tgt="Hol'anyee Marshal", tag="Opcional, If offered", desc="Missão de entrega de livro: aceite se o NPC a oferecer e leve ao Pico da Eternidade, no Monte Hyjal, para entregar. Se não vir a missão, pule por ora."}, [8]={hint="Colete 12 amostras de Piche Supergrudento para Tran'rek em Geringontzan."}, [9]={npc="Gualter", tgt="Gualter"}, [10]={hint="Colete 9 amostras das Cinzas de Un'Goro dos elementais de fogo ao redor do vulcão da Cratera Un'Goro, e leve-as para Fanny Quito, em Vila Catraca."}, [11]={hint="Gualter, na Cratera Un'Goro, quer que você encontre a área mais quente do Pico Penacho de Fogo.", desc="Suba pela trilha da Serra do Penacho de Fogo para medir a temperatura. Se tiver a missão das cinzas, recolha-as no caminho. Depois de medir a temperatura, siga a trilha até Ringo. Depois de iniciar a escolta, siga direto para o norte até o Refúgio do Marshal."}, [12]={npc="Ringo", tgt="Ringo", desc="Missão de escolta: em grupo, espere todos estarem no mesmo ponto antes de aceitar e desligue o aceite automático."}, [13]={npc="Ringo", tgt="Ringo"}, [14]={hint="Leve Ringo até Espraga Froque, no Refúgio do Marshal.", tag="Escolta", desc="Leve Ringo de volta ao Refúgio do Marshal. Ele desmaia no caminho; quando isso acontecer, use o Cantil da Espraga nele."}, [15]={npc="Espraga Froque", tgt="Espraga Froque"}, [16]={npc="A-Me 01", tgt="A-Me 01"}, [17]={npc="A-Me 01", tgt="A-Me 01"}, [18]={hint="Encontre uma Carcaça de Mithril e leve A-Me 01 de volta para a Cratera Un'Goro.", desc="Compre antes o invólucro de mithril na casa de leilões ou peça a um engenheiro que o faça."}, [19]={npc="A-Me 01", tgt="A-Me 01"}, [20]={hint="Leve Pelagem de U'cha para Torwa Mateiro na entrada da Cratera Un'Goro."}, [21]={npc="A-Me 01", tgt="A-Me 01"}, [22]={hint="Escolte A-Me 01 de volta para Karna Trilheiro na Cratera Un'Goro.", tag="Escolta", desc="Escolte A-Me 01 de volta a Karna Trilheiro; os monstros no caminho o atacam, então proteja-o."}, [23]={npc="Karna Trilheiro", tgt="Karna Trilheiro"}, [24]={hint="Colete 7 Cristais de Poder de cada uma das seguintes cores: vermelho, azul, amarelo e verde. Leve-os para J.D. Neri no Refúgio do Marshal.", desc="Cristais de quatro cores estão espalhados pelo chão por toda a cratera; complete os que ficaram faltando antes."}, [25]={npc="J.D. Neri", tgt="J.D. Neri"}, [26]={npc="J.D. Neri", tgt="J.D. Neri"}, [27]={npc="J.D. Neri", tgt="J.D. Neri"}, [28]={npc="J.D. Neri", tgt="J.D. Neri"}, [29]={hint="Descubra a localização da Torre de Cristal Norte, que fica na Cratera Un'Goro."}, [30]={hint="Descubra a localização da Torre de Cristal Leste, que fica na Cratera Un'Goro."}, [31]={hint="Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.", tag="Opcional", desc="Procure vespas ou operários Gorishi na colmeia ao sul para obter a glândula. Recolha cinco porções de terra dos montes que encontrar. Se estiver só, atraia insetos isolados sem avançar à procura da rainha."}, [32]={hint="Leve uma Glândula Odorífera Gorishi e 5 Amostras de Solo de Un'Goro ao Alquimista Almofarrista em Geringontzan.", tag="Opcional", desc="Procure vespas ou operários Gorishi na colmeia ao sul para obter a glândula. Recolha cinco porções de terra dos montes que encontrar. Se estiver só, atraia insetos isolados sem avançar à procura da rainha."}, [33]={hint="Descubra a localização da Torre de Cristal Oeste, que fica na Cratera Un'Goro."}, [34]={npc="Gualter", tgt="Gualter"}, [35]={npc="Gualter", tgt="Gualter"}, [36]={npc="J.D. Neri", tgt="J.D. Neri"}, [37]={npc="J.D. Neri", tgt="J.D. Neri"}, [38]={npc="J.D. Neri", tgt="J.D. Neri"}, [39]={npc="J.D. Neri", tgt="J.D. Neri"}, [40]={npc="J.D. Neri", tgt="J.D. Neri"}, [41]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [42]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [43]={hint="Colete 8 Cogumelos Vermelhos e 8 Ferrões de Gorishi e fale novamente com Torwa Mateiro na Cratera Un'Goro."}, [44]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [45]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [46]={npc="Torwa Mateiro", tgt="Torwa Mateiro"}, [47]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Grupo recomendado, Opcional"}, [48]={hint="Consiga uma Trepadeira Pútrida do guardião no fundo do Templo Submerso e fale novamente com Torwa Mateiro.", tag="Grupo recomendado, Opcional"}, [49]={npc="Torwa Mateiro", tgt="Torwa Mateiro", tag="Grupo recomendado, Opcional"}, [50]={text="Se ainda estiver no norte e não tiver nada a fazer com Torwa, consulte o mapa de voo no Refúgio do Marshal e voe para Geringontzan se o destino estiver disponível. Para entregar a pele de U'cha ou fazer as missões de druida de Torwa, visite-o primeiro no sudeste. De Torwa, ou se não puder voar, suba a rampa a sudeste até Tanaris e siga para nordeste até Geringontzan."}, [51]={npc="Tran'rek", tgt="Tran'rek"}, [52]={npc="Alquimista Almofarrista", tgt="Alquimista Almofarrista", tag="Opcional"}, [53]={to="Ratchet", toA="{a:392}", desc="Você fará uma conexão em Theramore."}, [54]={npc="Fanny Quito", tgt="Fanny Quito"}, [55]={bindA="{a:415}"}, [56]={to="Auberdine"}, [57]={text="Vincule sua Pedra de Regresso com Estalajadeira Shaussiy na estalagem de Auberdine (37.04, 44.13)."}, [58]={to="Rut'theran Village", toA="{a:702}"}, [59]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [60]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus."}, [61]={hint="Viaje para Darnassus e use a Ampola de Eridan para coletar uma Ampola de Água Benta no Templo da Lua. Fale novamente com Eridan, levando a ampola cheia."}, [62]={text="Entre no portal de Darnassus para voltar à Vila de Rut'theran."}, [63]={to="Astranaar", toA="{a:415}"}, [64]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco"}, [65]={npc="Greta Musgo no Casco", tgt="Greta Musgo no Casco", tag="Opcional, If offered", desc="Missão de entrega de carta: aceite se o NPC a oferecer e leve ao Monte Hyjal para entregar ao eremita Ketharas. Se não vir a missão, pule por ora."}, [66]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [67]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [68]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [69]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [70]={npc="Eridan Brisazul", tgt="Eridan Brisazul"}, [71]={hint="Colete 11 Garras Prateadas e 1 Coração de Ferrárbol para Eridan Brisazul na Selva Maleva.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [72]={npc="Eridan Brisazul", tgt="Eridan Brisazul", tag="Opcional"}, [73]={desc="Se estiver em recarga, volte a pé até Astranaar e voe para Auberdine."}, [74]={to="Menethil Harbor", toA="{a:150}", from="Auberdine", desc="Em Auberdine, pegue o barco para o Porto de Menethil e desça na próxima parada."}, [75]={to="Altaforja"}, [76]={npc="Historiador Karnik", tgt="Historiador Karnik"}, [77]={npc="Historiador Karnik", tgt="Historiador Karnik"}, [78]={npc="Alto-explorador Magellas", tgt="Alto-explorador Magellas"}, [79]={npc="Alto-explorador Magellas", tgt="Alto-explorador Magellas"}, [80]={npc="Historiadora Real Arquefilis", tgt="Historiadora Real Arquefilis"}, [81]={npc="Historiadora Real Arquefilis", tgt="Historiadora Real Arquefilis"}, [82]={npc="Historiadora Real Arquefilis", tgt="Historiadora Real Arquefilis"}}},
    ["05-d11"] = {name="Abismo Rocha Negra", entrance="Garganta Abrasadora 34.80, 85.30", pickup="Na rota principal, forme um grupo em Altaforja depois da segunda visita à Cratera Un'Goro. O próximo destino é a Estepe Ardente. Se encontrar um grupo antes na Garganta Abrasadora, entre na Montanha Rocha Negra pela ponta sul da garganta.", pickupS={{"Na rota principal, forme um grupo em Altaforja depois da segunda visita à Cratera Un'Goro"}, {"O próximo destino é a Estepe Ardente"}, {"Se encontrar um grupo antes na Garganta Abrasadora, entre na Montanha Rocha Negra pela ponta sul da garganta"}}, tips={{k="動線", text="De Altaforja, voe para o Posto de Tório se tiver o voo e entre na Montanha Rocha Negra pela ponta sul da Garganta Abrasadora. Sem o voo, saia de Dun Morogh pelo leste para Loch Modan. Vá para o sul até os Ermos e depois para oeste, contornando Karrath, até a Garganta Abrasadora. → Se encontrar um grupo em Hibérnia, voe para Auberdine. Sem o voo, volte pelo Domínio dos Presamatos até a Selva Maleva e atravesse o Vale Gris até Auberdine, na Costa Negra. Pegue o barco para Ventobravo e voe para o Posto de Tório. Sem os pontos de voo no leste, saia de Ventobravo pela Floresta de Elwynn rumo às Montanhas Cristarrubra. Siga a estrada ao norte de Vila Plácida até a Estepe Ardente e vá para oeste até a Montanha Rocha Negra. → Para continuar na Estepe Ardente, saia pelo portão sul da Montanha Rocha Negra e siga a estrada para leste até a Vigia de Morgan. → Para retornar ao Domínio de Plumaluna, use a pedra de regresso se estiver disponível e vinculada a Astranaar. Caso contrário, saia da Estepe Ardente e atravesse as Montanhas Cristarrubra e a Floresta de Elwynn até o porto de Ventobravo. Pegue o barco para Auberdine e voe para o Domínio de Plumaluna. Sem o voo, saia do Vale Gris, atravesse a Cordilheira das Torres de Pedra e Desolação até Feralas e pegue o barco para a ilha no cais da costa oeste."}}, steps={[1]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice", desc="Fale com Franclorn como fantasma dentro da Montanha Rocha Negra. Aceite e entregue a primeira parte e aceite a segunda antes de ressuscitar. Veja nesta página as rotas para chegar à montanha."}, [2]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice"}, [3]={npc="Franclorn Forjífice", tgt="Franclorn Forjífice"}, [4]={text="Entrada: Abismo Rocha Negra"}, [5]={hint="Mate Fineous Forçanegra e recupere o grande martelo Ferrovil. Leve-o para o Santuário de Thaurissan e coloque-o na estátua de Franclorn Forjífice."}, [6]={npc="Monumento de Franclorn Forjífice", npcObj=true, desc="Entregue aqui a missão Legado dos Ferro Negro. Para continuar na Estepe Ardente, use o portão sul da Montanha Rocha Negra. Para voltar a Kalimdor, siga as indicações desta página para o barco ou a pedra de regresso."}}},
    ["04-54"] = {steps={[1]={text="Se já liberou Vigia de Morgan, voe direto de Altaforja. Se não, voe até Vila Plácida e siga a estrada para o norte até as Estepes Ardentes; Vigia de Morgan fica logo na entrada.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={nodeA="{a:2418}", node="Morgan's Vigil"}, [3]={npc="Oralius", tgt="Oralius"}, [4]={npc="Oralius", tgt="Oralius"}, [5]={npc="Helendis Flumicórnio", tgt="Helendis Flumicórnio", tag="Grupo recomendado, Opcional"}, [6]={npc="Vera Brequim", tgt="Vera Brequim"}, [7]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio"}, [8]={hint="Vá até as Ruínas de Thaurissan, nas Estepes Ardentes, e descubra informações sobre as Relíquias de Thaurissan. Fale novamente com a Historiadora Real Arquefilis quando terminar."}, [9]={hint="Leve a Transcrição de Tabuleta para Maxwort Uberraio nas Estepes Ardentes."}, [10]={hint="Mate 15 Ogros-magos Pirobucho, 7 Ogros Pirobucho e 7 Brutamontes Ogros Pirobucho e fale novamente com Oralius quando terminar."}, [11]={hint="Leve 8 Essências da Reprodução e o Draco-incarcinatrix 900 a Vera Brequim no Monte Candente, que fica nas Estepes Ardentes."}, [12]={hint="Mate 15 Filhotes Negros, 10 Dragomorfos Negros, 4 Draconoides Negros e 1 Draco Negro. Fale novamente com Helendis Flumicórnio quando a tarefa estiver concluída.", tag="Grupo recomendado, Opcional", desc="Os draconoides negros e os dracos são elites de nível 51-53."}, [13]={npc="Ciro Terepento", tgt="Ciro Terepento"}, [14]={npc="Ciro Terepento", tgt="Ciro Terepento"}, [15]={npc="Vera Brequim", tgt="Vera Brequim"}, [16]={npc="Maxwort Uberraio", tgt="Maxwort Uberraio"}, [17]={npc="Oralius", tgt="Oralius"}, [18]={npc="Oralius", tgt="Oralius"}, [19]={npc="Helendis Flumicórnio", tgt="Helendis Flumicórnio", tag="Grupo recomendado, Opcional"}, [20]={npc="Helendis Flumicórnio", tgt="Helendis Flumicórnio"}, [21]={hint="Encontre Gor'tesh em algum lugar a oeste do Rochedo Malhorrendo. Mate Gor'tesh e depois leve a Cabeça Decepada do Gor'tesh de volta a Oralius nas Estepes Ardentes."}, [22]={hint="Oralius quer 50 Medalhões Rocha Negra. Há grandes chances de esses medalhões serem encontrados com orcs nas Estepes Ardentes."}, [23]={npc="Oralius", tgt="Oralius"}, [24]={npc="Oralius", tgt="Oralius"}, [25]={to="Lakeshire", toA="{a:69}", desc="Se não for fazer Os verdadeiros mestres, voe direto para Ventobravo e pule os dois próximos passos."}, [26]={npc="Magistrado Salomão", tgt="Magistrado Salomão"}, [27]={npc="Magistrado Salomão", tgt="Magistrado Salomão"}, [28]={to="Stormwind"}, [29]={npc="Wu Shen", tgt="Wu Shen", tag="Opcional"}, [31]={npc="Lorde Grayson Quebrassombra", tgt="Lorde Grayson Quebrassombra", desc="Entregue no Acampamento Ventogelante, nas Terras Pestilentas Ocidentais."}, [33]={npc="Grão-lorde Bolvar Fordragon", tgt="Grão-lorde Bolvar Fordragon"}, [34]={npc="Grão-lorde Bolvar Fordragon", tgt="Grão-lorde Bolvar Fordragon"}, [35]={npc="Grão-lorde Bolvar Fordragon", tgt="Grão-lorde Bolvar Fordragon"}, [36]={npc="Grão-lorde Bolvar Fordragon", tgt="Grão-lorde Bolvar Fordragon"}, [37]={npc="Brados Bonhomme", tgt="Brados Bonhomme"}, [38]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [39]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [40]={hint="Mate 7 Javiltuscos na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tag="Opcional"}, [41]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [42]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [43]={hint="Mate os Devotos da Sombra na Barreira do Inferno e fale novamente com o Herói Caído da Horda.", tag="Opcional"}, [44]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Opcional"}, [45]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Grupo recomendado, Opcional"}, [46]={hint="Leve as Penas Vodu dos trolls do Templo Submerso para o Herói Caído da Horda.", tag="Grupo recomendado, Opcional"}, [47]={npc="Herói Caído da Horda", tgt="Herói Caído da Horda", tag="Grupo recomendado, Opcional"}}},
    ["04-55"] = {steps={[1]={to="Aerie Peak", toA="{a:348}", desc="Se já liberou o Acampamento Ventogelante, voe direto e pule o próximo passo. Se o Ninho da Águia não estiver no seu mapa de voo, voe até Costa Sul e corra para leste até o Ninho da Águia pelo mesmo caminho da visita às Terras Agrestes."}, [2]={text="Do Ninho da Águia, siga a trilha da montanha para o norte até o canto sudeste das Terras Pestilentas Ocidentais (65.30, 86.80) e depois siga a estrada para o oeste até o Acampamento Ventogelante.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [3]={nodeA="{a:3197}", node="Chillwind Camp"}, [4]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [5]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [6]={hint="Colete 20 Pedras do Flagelo do Lacaio e leve-as ao Sumo Sacerdote Thel'danis nas Terras Pestilentas Ocidentais."}, [7]={npc="Sumo Sacerdote Thel'danis", tgt="Sumo Sacerdote Thel'danis"}, [8]={npc="Sumo Sacerdote Thel'danis", tgt="Sumo Sacerdote Thel'danis"}, [9]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [10]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom", tag="Grupo recomendado, Opcional", desc="Entregue para obter a Pedra do Poder."}, [11]={hint="Leve as Penas Vodu para Ashlam Punhobom.", tag="Grupo recomendado, Opcional", desc="Entregue para obter a Pedra do Poder."}, [12]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom", tag="Grupo recomendado, Opcional", desc="Entregue para obter a Pedra do Poder."}, [13]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [14]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [15]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [16]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [17]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida"}, [18]={npc="Oficial Argêntea Cândida", tgt="Oficial Argêntea Cândida", desc="Missão de entrega de uma carta; entregue perto da entrada do Monte Hyjal."}, [19]={npc="Flint Umbramais", tgt="Flint Umbramais", tag="Opcional"}, [20]={npc="Flint Umbramais", tgt="Flint Umbramais", tag="Opcional"}, [21]={hint="Mate 10 Esfoladores Descarnados e 10 Carniçais Salivantes na Colina do Pesar."}, [22]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [23]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [24]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [25]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [26]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [27]={hint="Usando a Tocha Sinalizadora, marque cada torre em Andorhal. Você tem que ficar na entrada da torre para conseguir marcá-la."}, [28]={hint="Vá ao Campo Pedravil nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá. Ele pode ter uma chave que dê acesso ao caldeirão. Você precisa estar com a Garrafa do Campo Pedravil Vazia para guardar uma amostra dos venenos usados no caldeirão."}, [29]={npc="Caldeirão do Flagelo", npcObj=true}, [30]={npc="Caldeirão do Flagelo", npcObj=true}, [31]={npc="Janice Pedravil", tgt="Janice Pedravil"}, [32]={npc="Embrulho da Janice", npcObj=true}, [33]={npc="Embrulho da Janice", npcObj=true}, [34]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [35]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [36]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [37]={hint="Vá a Lágrimas de Dalson nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa das Lágrimas de Dalson Vazia para guardar uma amostra dos venenos usados no caldeirão."}, [38]={npc="Caldeirão do Flagelo", npcObj=true}, [39]={npc="Caldeirão do Flagelo", npcObj=true}, [40]={npc="Diário da Sra. Dalson", npcObj=true, desc="O diário no celeiro ao lado do caldeirão."}, [41]={hint="Complete os objetivos da missão."}, [42]={npc="Diário da Sra. Dalson", npcObj=true}, [43]={npc="Casinha", npcObj=true, desc="Depois de ler o diário, procure o Esqueleto Errante. O fazendeiro aparece ao abrir a latrina."}, [44]={hint="Saque de: Esqueleto Errante"}, [45]={npc="Casinha", npcObj=true}, [46]={npc="Armário Trancado", npcObj=true, desc="Limpe ao redor da latrina. Abra o baú e entregue imediatamente."}, [47]={hint="Saque de: Fazendeiro Dalson"}, [48]={npc="Armário Trancado", npcObj=true}, [49]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [50]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [51]={npc="Nataniel Dumah", tgt="Nataniel Dumah"}, [52]={hint="Vá ao Antro Repelente nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa do Antro Repelente Vazia para guardar uma amostra dos venenos usados no caldeirão."}, [53]={npc="Caldeirão do Flagelo", npcObj=true}, [54]={npc="Caldeirão do Flagelo", npcObj=true}, [55]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [56]={hint="Destrua 8 Lobos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais."}, [57]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [58]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [59]={hint="Destrua 8 Ursos-cinzentos Doentes e fale novamente com Mulgris Riofundo no Antro Repelente, que fica nas Terras Pestilentas Ocidentais."}, [60]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [61]={npc="Mulgris Riofundo", tgt="Mulgris Riofundo"}, [62]={text="Vá para sudeste e pegue aqui a trilha da montanha para as Terras Agrestes."}, [63]={text="Vincule sua Pedra de Regresso na estalagem de Ninho da Águia (13.80, 41.60).", bindA="{a:348}"}, [64]={npc="Tesouro de Cortello", npcObj=true, tag="Opcional", desc="O tesouro fica na costa leste das Terras Agrestes, é preciso atravessar o mapa inteiro; depois de entregar, use a pedra de regresso para voltar."}, [65]={bindA="{a:348}"}}},
    ["04-56"] = {steps={[1]={text="Do Ninho da Águia, siga a trilha da montanha para o norte até as Terras Pestilentas Ocidentais e depois vá para leste, atravessando o Rio Thondroril, até as Terras Pestilentas Orientais. Tirion Fordring está na cabana ao lado da entrada."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [3]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [5]={hint="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída."}, [6]={hint="Mate 30 Quirópragos e fale novamente com Tirion Fordring."}, [7]={hint="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro."}, [8]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [9]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [10]={hint="Encontre a boneca de Pâmela.", desc="Nas casas em ruínas da Vila das Flechas, pegue a cabeça, o lado esquerdo e o lado direito e clique com o botão direito para juntar."}, [11]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [12]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [13]={npc="Pâmela Trilharrubra", tgt="Pâmela Trilharrubra"}, [14]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff"}, [15]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [16]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado"}, [17]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado", tag="Opcional, Grupo recomendado"}, [18]={npc="Leandro Leonardo", tgt="Leandro Leonardo", tag="Opcional, Grupo recomendado"}, [19]={node="Capela Esperança da Luz"}, [20]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [21]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}, [22]={npc="Zelador Alen", tgt="Zelador Alen"}, [23]={hint="Liberte 15 Espíritos da Vila das Flechas e fale novamente com Carlin Trilharrubra.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [24]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [25]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [26]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [27]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [28]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [29]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [30]={hint="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo."}, [31]={hint="Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz."}, [32]={npc="Pergaminho Rasgado", npcObj=true}, [33]={hint="Vasculhe as Terras Pestilentas Orientais em busca de pistas sobre o \"Arauto da Praga\" e os agentes da AVIN desaparecidos. Ser encontrar alguma Insígnia da AVIN, leve de volta para Flint Umbramais, no Acampamento Ventogelante.", tag="Opcional", desc="Pegue uma insígnia de cada um dos três corpos. Com as três na bolsa, confira o objetivo de reconhecimento no registro. Se ainda estiver pendente, examine os arredores do ponto marcado e mantenha distância do inimigo de elite."}, [34]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [35]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [36]={npc="Zelador Alen", tgt="Zelador Alen"}, [37]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}}},
    ["04-53"] = {steps={[1]={to="Southshore", toA="{a:271}", desc="Você fará uma conexão no Acampamento Ventogelante ou no Ninho da Águia; se Costa Sul não estiver no seu mapa de voo, voe para Ventobravo como de costume e pegue o barco para Auberdine no porto."}, [2]={npc="Raul, o Devotado", tgt="Raul, o Devotado", tag="Opcional, Requer materiais"}, [3]={to="Auberdine", from="Southshore", fromA="{a:271}", desc="Pegue o barco para Auberdine no cais de Costa Sul. Se voar para Ventobravo, embarque no porto de Ventobravo."}, [4]={to="Everlook", toA="{a:2255}"}, [5]={hint="Bruna Covaneve, de Hibérnia, quer que você mate 8 Desbravadores Invernosos, 8 Vigias do Covil dos Invernosos e 8 Totêmicos Invernosos."}, [6]={hint="Salfa quer que você mate 8 Xamãs Invernosos, 8 Vigias do Covil dos Invernosos e 8 Ursinos Invernosos. Salfa está perto da entrada do Domínio dos Presamatos, em Hibérnia."}, [7]={npc="Frasco Vazio de Aguardente", npcObj=true, tag="Aceite se cair, Opcional", desc="Os furbolgs Invernosos deixam cair o Frasco Vazio de Aguardente; depois de pegá-lo, clique com o botão direito para aceitar a missão; se ainda não caiu, continue matando furbolgs."}, [8]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [9]={npc="Bruna Covaneve", tgt="Bruna Covaneve", tag="Faça se cair"}, [10]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [11]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [12]={npc="Bruna Covaneve", tgt="Bruna Covaneve", desc="Explorar a Garganta do Sussurro Sombrio é concluído no caminho para o Monte Hyjal na próxima parada; entregue antes de voltar a Hibérnia e seguir para Clareira da Lua. Entregue antes de voltar a Hibérnia e seguir para Clareira da Lua."}, [13]={hint="Colete 10 Penas Lunamarca de Hibérnia, depois fale novamente com Erelas Ambarcéu, na Vila de Rut'theran."}, [14]={npc="Salfa", tgt="Salfa"}, [15]={npc="Caldeirão de Lenha Morta", npcObj=true}, [16]={npc="Caldeirão de Lenha Morta", npcObj=true}, [17]={to="Rut'theran Village", toA="{a:702}", desc="Do Caldeirão de Lenha Morta, vá para o sul até o ponto de voo de Clareira da Galhaça (62.49, 24.24) e decole de lá; você faz escala em Auberdine."}, [18]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [19]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [20]={npc="Daryn Aelumnis", tgt="Daryn Aelumnis"}, [21]={to="Everlook", toA="{a:2255}"}, [22]={npc="Harlo Balançante", tgt="Harlo Balançante"}, [23]={npc="Harlo Balançante", tgt="Harlo Balançante", tag="Opcional", desc="Missão de diálogo dentro da vila; a continuação exige enfrentar gigantes de elite, não aceite."}, [24]={npc="Mandingueira Mau'ari", tgt="Mandingueira Mau'ari", tag="Opcional"}, [25]={npc="Umi Zombarruga", tgt="Umi Zombarruga", desc="Enfrente os yetis depois de voltar de Bruna Covaneve, antes de partir para o sul."}, [26]={npc="Eol Correnoite", tgt="Eol Correnoite"}, [27]={npc="Eol Correnoite", tgt="Eol Correnoite"}, [28]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [29]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [30]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [31]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra"}, [32]={hint="Use a Picareta do Jaron para encontrar os quatro Fragmentos da Relíquia dos Altaneiros. Leve-os para Aurora Clamacéus nas Terras Pestilentas Orientais."}, [33]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [34]={hint="Colete 10 Peles Grossas de Yeti para Umi Zombarruga em Visteterna."}, [35]={npc="Umi Zombarruga", tgt="Umi Zombarruga"}, [36]={npc="Umi Zombarruga", tgt="Umi Zombarruga", tag="Opcional", desc="Os chifres só caem das matriarcas e dos patriarcas na caverna, e a taxa de saque é baixa; faça se quiser experiência extra."}, [37]={hint="Colete 2 Chifres Impolutos de Yeti para Umi Zombarruga em Visteterna.", tag="Opcional"}, [38]={npc="Umi Zombarruga", tgt="Umi Zombarruga", tag="Opcional", desc="A continuação exige ir a Un'Goro e a Geringontzan, não aceite."}, [39]={npc="Caixote Danificado", npcObj=true}, [40]={npc="Caixote Danificado", npcObj=true}, [41]={npc="Carroça de Jaron", npcObj=true}, [42]={npc="Carroça de Jaron", npcObj=true}, [43]={hint="Pegue os Suprimentos do Jaron na neve, depois encontre o coruscante que roubou o amuleto de que Jaron falou."}, [44]={npc="Ranshalla", tgt="Ranshalla"}, [45]={npc="Ranshalla", tgt="Ranshalla"}, [46]={hint="Proteja Ranshalla enquanto ela tenta reativar o Altar de Eluna. Relate suas descobertas a Erelas Ambarcéu, na Vila de Rut'theran."}}},
    ["04-57"] = {danger={[1]="Ghansurok (quimera elite de nível 61) patrulha dos hibiscos contaminados até a oficina de Kaylaena (cerca de x55-62,5, y61,5-72,2); confira a posição ao atacar os arbustos e ao voltar à oficina.", [2]="Celastrus, o Amargo (elite de nível 57), anda pelos hibiscos contaminados; fique atento ao atacar os arbustos.", [3]="A pilha de ossos invoca uma gosma elite de nível 58; sem grupo, não clique uma segunda vez."}, grind={[1]={note="A parte norte da Cicatriz Sangrevil; todas as missões de Felflick são feitas aqui."}}, supply={[1]={}}, steps={[1]={text="De Ranshalla, vá para o sul e entre na Garganta do Sussurro Sombrio (59.82, 74.25); siga o desfiladeiro para o oeste até o fim para entrar no Monte Hyjal. Há gigantes de gelo elite na entrada do desfiladeiro e demônios elite lá dentro; fique na estrada e não pare.", tag="Ponto de voo ainda não desbloqueado: na primeira vez, vá a pé"}, [2]={hint="Siga as instruções de Bruna Covaneve, depois fale novamente com ela.", desc="É concluída ao atravessar o desfiladeiro rumo ao Monte Hyjal; não precisa de desvio extra. Conta assim que o diário de missões a mostrar como concluída."}, [3]={text="Entre no Monte Hyjal pelo canto sudeste e siga a estrada para o oeste."}, [4]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [5]={npc="Quintus Wainworth", tgt="Quintus Wainworth"}, [6]={npc="Loose Cog", npcObj=true, desc="Uma engrenagem no chão ao lado da estrada; clique com o botão direito para pegá-la e aceitar a missão."}, [7]={npc="Ketharas", tgt="Ketharas", tag="Opcional", desc="Só entregue se tiver aceitado esta missão antes em Selva Maleva."}, [8]={npc="Ketharas", tgt="Ketharas"}, [9]={npc="Ketharas", tgt="Ketharas"}, [10]={npc="Ketharas", tgt="Ketharas"}, [11]={npc="Ketharas", tgt="Ketharas"}, [12]={npc="Ketharas", tgt="Ketharas"}, [13]={hint="Rescue 12 Hyjal Owl Eggs and bring them to Ketharas."}, [14]={hint="Collect 10 Untainted Seeds for Ketharas."}, [15]={npc="Ketharas", tgt="Ketharas"}, [16]={npc="Ketharas", tgt="Ketharas"}, [17]={npc="Ketharas", tgt="Ketharas"}, [18]={npc="Ketharas", tgt="Ketharas"}, [19]={hint="Saque de: Hyjal Stag, Predatory Hyjal Stag"}, [20]={hint="Plant the Enchanted Seeds near the Ruined Ballista, the Ruined Catapult, and the Ruined Flying Machine.", desc="Os destroços da balista, da catapulta e da máquina voadora contam como um objetivo cada, e é preciso plantar nos três. Procure na encosta fora da Caverna do Eremita."}, [21]={npc="Ketharas", tgt="Ketharas"}, [22]={npc="Ketharas", tgt="Ketharas"}, [23]={npc="Ketharas", tgt="Ketharas"}, [24]={hint="Bury the remains at Ketharas' shrine."}, [25]={npc="Ketharas", tgt="Ketharas"}, [26]={npc="Ketharas", tgt="Ketharas"}, [27]={nodeA="{a:16853}", node="Tainted Foothills", desc="Siga a estrada para o oeste; o ponto de voo fica ao lado do posto dos anciões."}, [28]={npc="Fraxinus", tgt="Fraxinus"}, [29]={npc="Hyacinth", tgt="Hyacinth"}, [30]={npc="Hyacinth", tgt="Hyacinth"}, [31]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional", desc="O alvo é uma elite de nível 57; se não conseguir derrotá-lo sozinho, não aceite."}, [32]={hint="Collect 6 samples of Untainted Soil from around the foothills of Mount Hyjal."}, [33]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Quando for a Visteterna mais tarde, procure Nami para pegar as peças."}, [36]={hint="Matar: Tainted Shrubbery", desc="Os mesmos hibiscos também dropam as folhas que estancam sangramento; ataque-os para as duas missões juntas. Entregue na oficina quando levar a caixa."}, [37]={hint="Saque de: Tainted Shrubbery"}, [38]={hint="Saque de: Celastrus the Bitter", tag="Grupo recomendado, Opcional"}, [39]={npc="Thylaen", tgt="Thylaen", tag="Grupo recomendado, Opcional"}, [40]={npc="Hyacinth", tgt="Hyacinth"}, [41]={npc="Hyacinth", tgt="Hyacinth"}, [42]={npc="Hyacinth", tgt="Hyacinth"}, [43]={hint="Matar: Fraxinus"}, [44]={npc="Fraxinus", tgt="Fraxinus"}, [45]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional", desc="O alvo, Sunderbark, é um ancião elite de nível 56; faça quando tiver grupo; sem grupo, pule, e a entrega mais adiante será pulada automaticamente."}, [46]={npc="Fraxinus", tgt="Fraxinus"}, [47]={npc="Curious Crow", tgt="Curious Crow"}, [48]={npc="Curious Crow", tgt="Curious Crow"}, [49]={npc="Curious Crow", tgt="Curious Crow"}, [50]={npc="Felflick", tgt="Felflick"}, [51]={npc="Felflick", tgt="Felflick"}, [52]={hint="Matar: Ashen Acolyte", desc="As anotações caem dos mesmos acólitos; enfrente-os para as duas missões."}, [53]={hint="Saque de: Ashen Acolyte"}, [54]={npc="Felflick", tgt="Felflick"}, [55]={npc="Felflick", tgt="Felflick"}, [56]={hint="Gather 8 Fel-Slime Crystals and 1 Pristine Fel-Slime Crystal."}, [57]={npc="Curious Crow", tgt="Curious Crow"}, [58]={npc="Curious Crow", tgt="Curious Crow"}, [59]={npc="Curious Crow", tgt="Curious Crow"}, [60]={hint="Saque de: Visgo Nocivo"}, [61]={hint="Collect 10 Prickly Pinecones under healthy trees."}, [62]={npc="Curious Crow", tgt="Curious Crow"}, [63]={npc="Curious Crow", tgt="Curious Crow"}, [64]={npc="Felflick", tgt="Felflick"}, [65]={npc="Felflick", tgt="Felflick"}, [66]={npc="Felflick", tgt="Felflick"}, [67]={hint="Saque de: Tyaeha Darkoath, Dazka Shadowsleep, Frezzlie Popwhiz"}, [68]={hint="Matar: Brashann Grimdark"}, [69]={npc="Felflick", tgt="Felflick"}, [70]={npc="Felflick", tgt="Felflick"}, [71]={npc="Felflick", tgt="Felflick"}, [72]={npc="Bone Pile", npcObj=true, desc="Jogue os ossos do bruxo na pilha de ossos ao lado da poça de gosma."}, [73]={npc="Bone Pile", npcObj=true, tag="Grupo recomendado, Opcional", desc="Invoca uma gosma elite de nível 58; sem grupo, pule Amalgamated Marrow e as missões seguintes."}, [74]={hint="Matar: Awakened Fel Ash Slime", tag="Grupo recomendado, Opcional"}, [75]={npc="Velician", tgt="Velician"}, [76]={npc="Felflick", tgt="Felflick", tag="Grupo recomendado, Opcional"}, [77]={npc="Felflick", tgt="Felflick"}, [78]={npc="Curious Crow", tgt="Curious Crow"}, [79]={npc="Curious Crow", tgt="Curious Crow"}, [80]={npc="Curious Crow", tgt="Curious Crow"}, [81]={npc="Curious Crow", tgt="Curious Crow"}, [82]={hint="Use the pinecones to destroy the Ashen Reign workstations."}, [83]={npc="Curious Crow", tgt="Curious Crow"}, [84]={npc="Curious Crow", tgt="Curious Crow", desc="Entregue em Velhamata, a oeste, na próxima parada."}, [85]={hint="Hunt down and destroy the corrupted ancient Sunderbark, then plant a seed in his remains.", tag="Grupo recomendado, Opcional", desc="No caminho de volta para o leste, rumo à Caverna do Eremita."}, [86]={npc="Ketharas", tgt="Ketharas"}, [87]={npc="Ketharas", tgt="Ketharas"}, [88]={npc="Fraxinus", tgt="Fraxinus", tag="Grupo recomendado, Opcional"}, [89]={to="Everlook", toA="{a:2255}"}, [90]={npc="Nami", tgt="Nami", desc="A caixa seguinte tem limite de tempo; aceite-a quando voltar de Clareira da Lua."}, [91]={npc="Jaron Moldapedra", tgt="Jaron Moldapedra", desc="De Visteterna siga a estrada para oeste por um trecho curto até Aldeia Chuva Estelar."}, [92]={text="Cavalgue a sudoeste pela estrada de Aldeia Chuva Estelar até as fontes termais e procure Donova."}, [93]={npc="Bruna Covaneve", tgt="Bruna Covaneve"}, [94]={to="Clareira da Lua", desc="Cavalgue de volta das fontes termais ao ponto de voo de Visteterna e voe (o ponto de voo de Clareira da Lua foi aberto na {s:04-49}). Se sua reputação com os Presamatos já for neutra, cavalgue ao norte das fontes termais até a entrada do Domínio dos Presamatos (27.70, 34.50); atravessar a caverna até a saída para Clareira da Lua é mais perto; se não abriu o ponto de voo de Clareira da Lua, siga também por este caminho e abra primeiro o ponto de voo ao chegar (48.10, 67.34); abaixo de neutra, você será atacado. Druidas podem usar Teleportar: Clareira da Lua diretamente; ao chegar, vá ao ponto de voo normal (48.10, 67.34) e abra-o para poder voltar voando. Se não abriu o ponto de voo de Clareira da Lua, siga também por este caminho e abra primeiro o ponto de voo ao chegar (48.10, 67.34). Abaixo de neutra, você será atacado. Druidas podem usar Teleportar: Clareira da Lua diretamente; ao chegar, vá ao ponto de voo normal (48.10, 67.34) e abra-o para poder voltar voando."}, [95]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [96]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [97]={npc="Orokai", tgt="Orokai"}, [98]={npc="Orokai", tgt="Orokai"}, [99]={hint="Speak with Orokai when you are ready to see what he learned from the Faintly Glowing Branch."}, [100]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [101]={npc="Dendrite Stellardor", tgt="Dendrite Stellardor"}, [102]={to="Everlook", toA="{a:2255}", desc="Parta do ponto de voo normal de Clareira da Lua (48.10, 67.34) e desça em Visteterna para pegar a caixa."}, [103]={npc="Nami", tgt="Nami", desc="As baterias da caixa param de funcionar após cerca de duas horas, então entregue-a direto a Kaylaena a partir do ponto de voo."}, [104]={to="Tainted Foothills", toA="{a:16853}", desc="Do ponto de voo cavalgue direto ao norte até a oficina de Kaylaena e entregue primeiro a caixa."}}},
    ["04-58"] = {danger={[1]="Ghansurok (quimera elite de nível 61) patrulha a leste do Santuário de Aviana; fique atento ao lutar contra harpias."}, supply={[1]={}, [2]={}}, steps={[1]={hint="Gently transport the crate of parts and baubles to Kaylaena Springwhisper in Mount Hyjal.", desc="Leve a caixa até Kaylaena na oficina e siga o diálogo da missão."}, [2]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Do ponto de voo cavalgue direto ao norte até a oficina e entregue primeiro a caixa."}, [3]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [4]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Os materiais estão nos destroços do acampamento da Horda em Dae'gun, ao norte; pegue quando passar por lá mais tarde."}, [5]={npc="Ketharas", tgt="Ketharas", desc="Cavalgue ao sudeste da oficina de volta à Caverna do Eremita."}, [6]={npc="Ketharas", tgt="Ketharas"}, [7]={npc="Ketharas", tgt="Ketharas"}, [8]={npc="Skylord Omnuron", tgt="Skylord Omnuron", desc="Cavalgue a noroeste da Caverna do Eremita até o Santuário de Aviana."}, [9]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [10]={npc="Skylord Omnuron", tgt="Skylord Omnuron"}, [11]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [12]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [13]={hint="Saque de: Wormwing Harpy, Wormwing Windwitch, Wormwing Ambusher"}, [14]={hint="Collect 8 Tarnished Highfeather Bangles from Wormwing Harpy nests."}, [15]={hint="Find the Jewel of the Horizon in the Wormwing harpy nests on Mount Hyjal and bring it to Ketharas."}, [16]={hint="Saque de: Zarrat Wormwing"}, [17]={npc="Corrupted Growth", npcObj=true, desc="Clique com o botão direito no crescimento corrompido na árvore para aceitar a missão."}, [18]={hint="Usar/coletar: Corrupted Growth"}, [19]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [20]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [21]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather"}, [22]={npc="S