    ["04-60"] = {danger={[1]="Ghansurok (quimera elite de nível 61) anda pela crista ao sul da oficina de Kaylaena.", [2]="Mazzogore (elite de nível 60) patrulha ao sul de Dae'gun; desvie dele ao lutar contra os cães.", [3]="Ve'han Talongrasp (elite de nível 60) vigia a cabana de Nordrassil; não se aproxime demais durante as missões dos cultistas."}, grind={[1]={mob="Sentinela Guarda Vil", note="A metade sul de Dae'gun; pegue de passagem os suprimentos abandonados e os materiais dos destroços da Horda."}, [2]={note="O acampamento dos cultistas a leste do Pico da Eternidade; as missões do topo são todas feitas aqui."}}, supply={[1]={}, [2]={}, [3]={}}, steps={[1]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas", desc="Volte para o leste pela estrada."}, [2]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [3]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [4]={npc="Witherbeard", tgt="Witherbeard"}, [5]={npc="Yashiro", tgt="Yashiro"}, [6]={hint="Light the two bonfires in Dae'gun and return to Yashiro."}, [7]={text="Depois de acender a fogueira a sudeste, siga a sudeste até Renalard; entregue primeiro Criatura Esperta, aceite as missões das cinzas e da raposa e limpe Dae'gun mais uma vez na volta."}, [8]={npc="Renalard", tgt="Renalard"}, [9]={npc="Renalard", tgt="Renalard"}, [10]={npc="Renalard", tgt="Renalard"}, [11]={hint="Collect 8 Abandoned Supplies.", desc="Use o chumaço de pelo de raposa (Tuft of Fox Fur) que a missão dá para afastar o demônio e depois pegue 8 suprimentos abandonados. Os suprimentos não ficam ao lado de Renalard."}, [12]={hint="Scavenge the remains of the Horde base and return 5 Frayed Wire, 5 Scrap Metal, and 5 Calcified Excrement to Kaylaena."}, [13]={hint="Saque de: Defiling Hound"}, [14]={hint="Matar: Felguard Sentinel"}, [15]={hint="Fetch a pinch of Azgalor's Ashes from the ruins of Dae'gun on Mount Hyjal."}, [16]={hint="Enter Dae'gun and locate a high vantage point, then report details to Johun."}, [17]={npc="Yashiro", tgt="Yashiro", desc="Depois de limpar Dae'gun, volte aqui a Yashiro para entregar."}, [18]={npc="Yashiro", tgt="Yashiro", tag="Opcional"}, [19]={hint="Fight your way through Dae'gun with Yashiro.", tag="Grupo recomendado, Opcional", desc="Siga Yashiro enquanto ele abre o caminho; é concluída ao derrotar o Demonarca Xarkul (Doomguard Xarkul) no final."}, [20]={npc="Yashiro", tgt="Yashiro", tag="Opcional", desc="Entregue a Yashiro onde o evento terminar, que não é necessariamente o ponto de partida."}, [21]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [22]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Grupo recomendado, Opcional", desc="Os dois alvos são demônios elite de nível 60; sem grupo, pule, e as continuações serão puladas automaticamente."}, [23]={hint="Matar: Bethra'zel, Mazzogore", tag="Grupo recomendado, Opcional"}, [24]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper", tag="Grupo recomendado, Opcional"}, [25]={npc="Elaena Moonwhisper", tgt="Elaena Moonwhisper"}, [26]={npc="Witherbeard", tgt="Witherbeard"}, [27]={npc="Johun Punchy Dillas", tgt="Johun Punchy Dillas"}, [28]={npc="Renalard", tgt="Renalard", desc="Vá para o sudeste."}, [29]={nodeA="{a:16849}", node="Summit of Eternity", desc="De Renalard, suba um trecho da montanha para o leste e obtenha o ponto de voo de Fayran Elthas. Entregue primeiro as missões que trouxe para a montanha, para aliviar o diário."}, [30]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [31]={npc="Tiala Whitemane", tgt="Tiala Whitemane", tag="Opcional", desc="Só entregue se tiver aceitado esta missão antes na Cratera Un'Goro."}, [32]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [33]={npc="Sebelia", tgt="Sebelia", desc="Entregue o pacote de cartas em Visteterna logo mais e depois faça a cadeia do correio."}, [34]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", desc="Do Pico da Eternidade, desça a montanha a oeste passando por Renalard e depois vá ao sul até a oficina. Se o caminho da montanha estiver intransitável, voe para o Contraforte Maculado e cavalgue ao norte."}, [35]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [36]={hint="Turn the two gears and connect the two battery terminals on both sides of Kaylaena's Glaive Thrower."}, [37]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper"}, [38]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Grupo recomendado, Opcional", desc="O Ghansurok que você atrai é uma quimera elite de nível 61."}, [39]={hint="Walk to the ridge south of Kaylaena's workshop and find a way to make a loud distracting commotion to draw the chimaera Ghansurok in range to be attacked.", tag="Grupo recomendado, Opcional", desc="Interaja com o tambor no penhasco ao sul da oficina e atraia a quimera para o alcance do lançador de rodas de lâminas, para que o NPC o opere; não a puxe para longe para lutar à força."}, [40]={npc="Kaylaena Springwhisper", tgt="Kaylaena Springwhisper", tag="Grupo recomendado, Opcional"}, [41]={npc="Phoebe Highfeather", tgt="Phoebe Highfeather", desc="Da oficina, caminhe um trecho curto a sudoeste até o Santuário de Aviana."}, [42]={npc="Ketharas", tgt="Ketharas", desc="Cavalgue a sudeste do santuário de volta à Caverna do Eremita."}, [43]={npc="Ketharas", tgt="Ketharas"}, [44]={npc="Ketharas", tgt="Ketharas"}, [45]={npc="Ketharas", tgt="Ketharas"}, [46]={to="Everlook", toA="{a:2255}", desc="Cavalgue a oeste da Caverna do Eremita e parta do ponto de voo do Contraforte Maculado."}, [47]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [48]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [49]={hint="Find 4 pieces of Missing Mail in the hills north of Everlook and bring it back to Innkeeper Vizzie.", desc="A correspondência está espalhada pelas colinas fora de Visteterna; procure seguindo as dicas do registro de missões; se não encontrar, pode pular por enquanto."}, [50]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi"}, [51]={npc="Estalajadeira Vizzi", tgt="Estalajadeira Vizzi", desc="Leve o correio de volta ao topo do Monte Hyjal para entregar."}, [52]={to="Summit of Eternity", toA="{a:16849}", desc="Você fará conexão no Contraforte Maculado."}, [53]={npc="Sebelia", tgt="Sebelia"}, [54]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [55]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [56]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [57]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [58]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [59]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [60]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [61]={hint="Find thorn seeds in the forests at the summit of Mount Hyjal and bring them back to Tiala Whitemane."}, [62]={hint="Use the Staff of the Mountain on 10 members of the Blackthorne Pact on the Summit of Eternity to remove their wards and then kill them.", desc="Os mesmos cultistas também contam para Acabar com o Frenesi e Ferramentas Retorcidas; use primeiro o cajado e depois mate-os, e faça as três juntas."}, [63]={hint="Matar: Blackthorne Cultist, Blackthorne Adept"}, [64]={hint="Saque de: Blackthorne Cultist, Blackthorne Outrunner, Blackthorne Adept"}, [65]={hint="Saque de: Mountain Squallclimber, Wildbreath Chimaerok"}, [66]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [67]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [68]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [69]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [70]={hint="Plant thorn seeds near the inn, the storage tower, and the grouping of trees at the loyalist druid camp."}, [71]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [72]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [73]={npc="Thisalee Crow", tgt="Thisalee Crow", desc="Depois de aceitar, vá primeiro a Marn Euhorn para entregar Ventos da Purificação e pegar O Perdão de Archimonde (Archimonde's Pardon); faça as duas na mesma viagem."}, [74]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [75]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [76]={hint="Reactivate the sentinel stones north, west, and south around the Blackthorne cultists.", desc="As pedras norte, oeste e sul contam como um objetivo cada, e é preciso visitar as três."}, [77]={hint="Use the Enchanted Branch to release 5 wisps around Nordrassil.", desc="Liberte o fogo-fátuo que já está sob as raízes, em vez de invocá-lo com um item na clareira. Faça na mesma viagem de O Perdão de Archimonde."}, [78]={hint="Take Marn's incense and allow the smoke to ward the air around Archimonde's remains."}, [79]={npc="Thisalee Crow", tgt="Thisalee Crow"}, [80]={npc="Tiala Whitemane", tgt="Tiala Whitemane"}, [81]={npc="Marn Euhorn", tgt="Marn Euhorn"}, [82]={npc="Toron Rockhoof", tgt="Toron Rockhoof"}, [83]={to="Rut'theran Village", toA="{a:702}", desc="Você fará conexão no Contraforte Maculado e em Visteterna."}, [84]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [85]={npc="Erelas Ambarcéu", tgt="Erelas Ambarcéu"}, [86]={text="Entre no portal da Vila de Rut'theran para ir a Darnassus."}, [87]={npc="Arquidruida Fandral Guenelmo", tgt="Arquidruida Fandral Guenelmo"}, [88]={npc="Mathrengyl Ursivagus", tgt="Mathrengyl Ursivagus"}}},
    ["04-59"] = {name="Terras Pestilentas Ocidentais", steps={[1]={bindA="{a:348}", desc="Só use a Pedra de Regresso se ainda estiver vinculada a Ninho da Águia e disponível. Caso contrário, use a rota de barco como alternativa: volte pelo portal a Aldeia Rut'theran, voe para Auberdine, vá primeiro de barco ao Porto de Menethil e siga pela rota marítima do norte até Costa Sul, desembarque ali e voe para o Acampamento Chillwind."}, [2]={to="Chillwind Camp", toA="{a:3197}", desc="Pule se já estiver no Acampamento Chillwind. Se o mapa de voo não listar o Acampamento Chillwind, vá ao norte pela estrada da montanha de Ninho da Águia até as Terras Pestilentas Ocidentais e depois a oeste até o Acampamento Chillwind."}, [3]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [4]={npc="Flint Umbramais", tgt="Flint Umbramais", tag="Opcional"}, [5]={npc="Flint Umbramais", tgt="Flint Umbramais", tag="Opcional"}, [6]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [7]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [8]={npc="Alquimista Arvignon", tgt="Alquimista Arvignon"}, [9]={npc="Alquimista Arvignon", tgt="Alquimista Arvignon", desc="Os Fragmentos de Ossos só começam a cair depois que você aceita a missão; colete-os de passagem ao matar esqueletos na Colina do Pesar e em Andorhal."}, [10]={npc="Marlene Trilharrubra", tgt="Marlene Trilharrubra"}, [11]={npc="Marlene Trilharrubra", tgt="Marlene Trilharrubra"}, [12]={hint="Leve o Anel de Casamento do Josefo para Crona."}, [13]={hint="Leve 15 Fragmentos de Ossos para o Alquimista Arvignon no Morro do Ventogelante, que fica nas Terras Pestilentas Ocidentais."}, [14]={npc="Crona", tgt="Crona"}, [15]={npc="Crona", tgt="Crona"}, [16]={npc="Crona", tgt="Crona"}, [17]={hint="Leve os Anais da Vila das Flechas para Crona em Andorhal."}, [18]={hint="Use o Deslocador Temporal perto de um dos silos de Andorhal e desencave Parasitas Temporais."}, [19]={npc="Crona", tgt="Crona"}, [20]={npc="Crona", tgt="Crona"}, [21]={npc="Crona", tgt="Crona"}, [22]={hint="Encontre 5 Relógios de Andorhal, que estão em cofres em meio às ruínas da cidade. Regresse com eles até Crona, que está na Estalagem Andorhal, que fica nas Terras Pestilentas Ocidentais."}, [23]={npc="Crona", tgt="Crona"}, [24]={npc="Crona", tgt="Crona"}, [25]={to="Capela Esperança da Luz", desc="Andorhal não tem ponto de voo. Volte primeiro a pé para o sul até o Acampamento Ventogelante e voe de lá."}, [26]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [27]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [28]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}, [29]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [30]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado"}, [31]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado", desc="Faça na próxima vez que o grupo for à ala dos mortos-vivos."}, [32]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado", tag="Opcional, Grupo recomendado"}, [33]={npc="Leandro Leonardo", tgt="Leandro Leonardo", tag="Opcional, Grupo recomendado"}, [34]={hint="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo."}, [35]={hint="Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta."}, [36]={npc="Aurora Clamacéus", tgt="Aurora Clamacéus"}, [37]={hint="Use a Jarra de Cupins Vazia nos Cupinzeiros que há nas Terras Pestilentas Orientais. Após conseguir 100 Cupins das Terras Pestilentas, fale novamente com Nataniel Dumah no Acampamento Ventogelante, em Terras Pestilentas Ocidentais."}, [38]={hint="Leve o Crânio de Horgus e a Espada Estilhaçada de Marduk para Carlin Trilharrubra na Capela Esperança da Luz.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [39]={npc="Monturo de Terra", npcObj=true}, [40]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [41]={npc="Tirion Fordring", tgt="Tirion Fordring"}, [42]={hint="Leve o Incunábulo de Davil e o Escudo de Trilharrubra para Carlin Trilharrubra."}, [43]={hint="Vá a Aridez de Garrão nas Terras Pestilentas Ocidentais para localizar e derrotar o Mestre do Caldeirão de lá, e use a chave dele para ter acesso ao caldeirão. Você precisa estar com a Garrafa da Aridez de Garrão Vazia para guardar uma amostra dos venenos usados no caldeirão."}, [44]={npc="Caldeirão do Flagelo", npcObj=true}, [45]={npc="Caldeirão do Flagelo", npcObj=true}, [46]={npc="Artista Renée", tgt="Artista Renée"}, [47]={npc="Alta-sacerdotisa Donélia", tgt="Alta-sacerdotisa Donélia"}, [48]={npc="Alquimista Arvignon", tgt="Alquimista Arvignon", desc="A continuação exige entrar em Scolomântia, não aceite."}, [49]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [50]={npc="Comandante Ashlam Punhobom", tgt="Comandante Ashlam Punhobom"}, [51]={npc="Nataniel Dumah", tgt="Nataniel Dumah"}, [52]={npc="Nataniel Dumah", tgt="Nataniel Dumah"}, [53]={npc="Barril de Cupins", npcObj=true}, [54]={npc="Barril de Cupins", npcObj=true}, [55]={hint="Solte os Cupins das Terras Pestilentas na Serraria de Beiranorte, depois retorne com o Barril de Cupins das Terras Pestilentas até Nataniel Dumah, no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."}, [56]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [57]={hint="Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais."}, [58]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [59]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [60]={hint="Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais."}, [61]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [62]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [63]={hint="Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais.", desc="As coordenadas são aproximadas. Há guardas da Cruzada Escarlate na entrada e ao lado da torre; puxe um de cada vez."}, [64]={npc="Kirsta Sombrafunda", tgt="Kirsta Sombrafunda"}, [65]={npc="Nataniel Dumah", tgt="Nataniel Dumah"}, [66]={to="Capela Esperança da Luz", desc="Você já está no Acampamento Ventogelante; procure direto o mestre de voo."}, [67]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra", tag="Opcional"}, [68]={npc="Carlin Trilharrubra", tgt="Carlin Trilharrubra"}, [69]={to="Altaforja"}, [70]={npc="Historiadora Real Arquefilis", tgt="Historiadora Real Arquefilis"}, [71]={to="Stormwind"}, [72]={npc="Administrador Real Bathrilor", tgt="Administrador Real Bathrilor"}, [73]={npc="Administrador Real Bathrilor", tgt="Administrador Real Bathrilor"}, [74]={npc="Tia Bia", tgt="Tia Bia"}, [75]={npc="Grão-lorde Bolvar Fordragon", tgt="Grão-lorde Bolvar Fordragon", tag="Opcional"}, [76]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Opcional"}, [77]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Opcional"}, [78]={npc="Mestre Mathias Shaw", tgt="Mestre Mathias Shaw", tag="Opcional"}, [79]={to="Lakeshire", toA="{a:69}", tag="Opcional", desc="Só vá a Vila Plácida se tiver Os verdadeiros mestres; se não tiver, voe direto de Ventobravo para a Vigia de Morgan."}, [80]={npc="Magistrado Salomão", tgt="Magistrado Salomão"}, [81]={npc="Magistrado Salomão", tgt="Magistrado Salomão"}, [82]={to="Morgan's Vigil", toA="{a:2418}"}, [83]={npc="Oficial Maxwell", tgt="Oficial Maxwell"}, [84]={npc="Oficial Maxwell", tgt="Oficial Maxwell"}, [85]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [86]={hint="Fale com João Roto para saber o destino do Marechal Vilasboas e fale novamente com o Oficial Maxwell quando tiver completado essa tarefa."}, [87]={hint="Pegue a Cabeça Decepada do Gor'Tesh e coloque no topo do Rochedo Malhorrendo. Procure um montinho de terra macia para espetar a estaca.", tag="Opcional", desc="É um desvio só para isso; não há outros objetivos perto. Se estiver com pressa, pule."}, [88]={npc="Oficial Maxwell", tgt="Oficial Maxwell"}, [89]={npc="Oralius", tgt="Oralius", tag="Opcional"}, [90]={text="Ainda não chegou ao 60? Faça o Abismo Rocha Negra uma vez. Se não bastar, repita Stratholme ou Scolomântia."}}},
    ["05-d13"] = {name="Stratholme", entrance="Terras Pestilentas Orientais 26.52, 10.36 (portão principal escarlate; entrada de serviço dos mortos-vivos em 43.50, 19.40)", steps={[1]={text="Voe até o Acampamento Ventogelante se precisar visitar a pintora em Caer Darrow, nas Terras Pestilentas Ocidentais, para pegar Do Amor e da Família. Se já tiver a missão ou só quiser as da capela, encontre o grupo diretamente."}, [2]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [3]={hint="Mate 20 Cães Pestilentos Miúdos, 5 Cães Pestilentos e 5 Cães Pestilentos Frenéticos. Fale novamente com Tirion Fordring quando a tarefa estiver concluída.", tag="Pré-requisito de masmorra"}, [4]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [5]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [6]={hint="Mate 30 Quirópragos e fale novamente com Tirion Fordring.", tag="Pré-requisito de masmorra"}, [7]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [8]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [9]={hint="Procure os Vermes Carniceiros e os Devoradores de Carniça da região. Mate-os e tire a carne. Fale novamente com Tirion Fordring depois que tiver juntado 15 Nacos de Carne de Verme Carniceiro.", tag="Pré-requisito de masmorra"}, [10]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [11]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [12]={hint="Escute o que Tirion Fordring tem a dizer.", tag="Pré-requisito de masmorra"}, [13]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [14]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [15]={hint="Viaje para a Chácara Secreta, no extremo sul das Terras Pestilentas Orientais, e recupere o Martelo de Taelan. Fale novamente com Tirion Fordring ao completar seu objetivo.", tag="Pré-requisito de masmorra"}, [16]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [17]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [18]={hint="Viaje para o Vilarejo do Norte, na região nordeste das Terras Pestilentas Orientais, e recupere o Símbolo da Honra Perdida. Fale novamente com Tirion Fordring ao completar seu objetivo.", tag="Pré-requisito de masmorra"}, [19]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [20]={npc="Tirion Fordring", tgt="Tirion Fordring", tag="Pré-requisito de masmorra"}, [21]={npc="Artista Renée", tgt="Artista Renée", tag="Pré-requisito de masmorra"}, [22]={npc="Artista Renée", tgt="Artista Renée"}, [23]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [24]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado"}, [25]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado", tag="Opcional, Grupo recomendado"}, [26]={npc="Leandro Leonardo", tgt="Leandro Leonardo", tag="Opcional, Grupo recomendado"}, [27]={text="Da Capela Esperança da Luz, siga com o grupo para Stratholme. O marcador indica o portão principal escarlate para o mercado e o Bastião Escarlate. Se visitar apenas a ala dos mortos-vivos, encontre alguém do grupo que possa abrir a entrada de serviço a leste."}, [28]={text="Entrada: Stratholme"}, [29]={hint="Viaje para Stratholme, ao norte. Procure os caixotes de suprimentos que cobrem a cidade e recupere 5 Águas Bentas de Stratholme. Fale novamente com Leonid Bartolomeu, o Venerado, quando coletar fluido abençoado suficiente.", tag="Opcional, Grupo recomendado", spot="Procure caixotes de suprimentos nas ruas das duas alas. Guarde cinco frascos de Água Benta de Stratholme para a sua entrega e reponha os que usar."}, [30]={hint="Recupere 20 Amostras de Carne Infectada de Stratholme e leve-as para Betina Bigozinco. Você desconfia que qualquer criatura em Stratholme poderia ter essa amostra de carne.", tag="Opcional, Grupo recomendado", spot="Saqueie amostras de carne infectada enquanto o grupo avança por qualquer das alas. Guarde as amostras para outra visita e volte à capela quando tiver vinte."}, [31]={hint="Encontre a tabacaria de Ezra Carranca em Stratholme e recolha uma caixa do Tabaco da Lata do Carranca. Fale novamente com Leandro Leonardo depois que tiver terminado o serviço.", tag="Opcional, Grupo recomendado", spot="Na ala Escarlate, entre pelo portão principal e vá ao mercado. Abra o caixote da tabacaria, derrote Ezra Carranca e saqueie uma caixa do tabaco de primeira dele. Se o grupo só for à ala dos mortos-vivos, deixe para outra visita."}, [32]={hint="Viaje para Stratholme, na parte norte das Terras Pestilentas. No Bastião Escarlate, você encontrará a pintura \"Do Amor e da Família\", escondida atrás de outro quadro que retrata as luas gêmeas do nosso mundo.", spot="Derrotem Galford primeiro. Antes de queimar o arquivo, confirmem com o grupo se todos que precisam de \"Do amor e da família\" já pegaram a pintura atrás do quadro das duas luas. Se ninguém precisar dela, já podem queimar o arquivo."}, [33]={hint="Viaje até Stratholme e encontre o Arquivista Galford da Cruzada Escarlate. Destrua-o e queime o Arquivo Escarlate.", tag="Opcional, Grupo recomendado", spot="Derrotem Galford primeiro. Antes de queimar o arquivo, confirmem com o grupo se todos que precisam de \"Do amor e da família\" já pegaram a pintura atrás do quadro das duas luas. Se ninguém precisar dela, já podem queimar o arquivo."}, [34]={npc="Cabeça do Balnazzar", npcObj=true, tag="Opcional, Grupo recomendado", desc="Depois de entregar O Arquivista, clique com o botão direito na cabeça que você saqueou de Balnazzar para iniciar a missão."}, [35]={hint="Vá para Stratholme e vasculhe os zigurates. Encontre novos Dados do Flagelo e leve-os para Betina Bigozinco.", tag="Opcional, Grupo recomendado", spot="Procure o baú pequeno nos três zigurates da ala dos mortos-vivos e recolha os dados você mesmo."}, [36]={hint="Desbrave Stratholme e destrua o Barão Rivendare. Corte sua cabeça e leve-a de volta para o Duque Nicolau Zverenhoff.", tag="Opcional, Grupo recomendado", spot="Atravesse o Matadouro na ala dos mortos-vivos, derrote o Barão Rivendare e saqueie pessoalmente a cabeça dele."}, [37]={hint="Use o Canhão de Ectoplasma do Egan nos moradores fantasmagóricos e espectrais de Stratholme. Depois de livrá-los da forma de fantasma, use o canhão de novo e BLAU: liberdade!", tag="Opcional, Grupo recomendado", spot="Procure cidadãos fantasmagóricos pelas ruas de Stratholme. Use o disparador de Egan em um cidadão e depois na alma que aparecer. Liberte quinze almas."}, [38]={npc="Tirion Fordring", tgt="Tirion Fordring", desc="Tirion Fordring fica na cabana à beira do rio, no oeste das Terras Pestilentas Orientais."}, [39]={text="Volte à Capela Esperança da Luz. Se estiver com o quadro de \"Do amor e da família\", entregue-o primeiro a Tirion na margem oeste do rio, nas Terras Pestilentas Orientais, e volte à capela."}, [40]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [41]={npc="Cabeça do Balnazzar", npcObj=true, tag="Opcional, Grupo recomendado", desc="Depois de entregar O Arquivista, clique com o botão direito na cabeça que você saqueou de Balnazzar para iniciar a missão."}, [42]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [43]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado", desc="Faça na próxima vez que o grupo for à ala dos mortos-vivos."}, [44]={npc="Duque Nicolau Zverenhoff", tgt="Duque Nicolau Zverenhoff", tag="Opcional, Grupo recomendado"}, [45]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado"}, [46]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado", desc="Faça na próxima vez que o grupo for à ala dos mortos-vivos."}, [47]={npc="Betina Bigozinco", tgt="Betina Bigozinco", tag="Opcional, Grupo recomendado"}, [48]={npc="Leonid Bartolomeu, o Venerado", tgt="Leonid Bartolomeu, o Venerado", tag="Opcional, Grupo recomendado"}, [49]={npc="Leandro Leonardo", tgt="Leandro Leonardo", tag="Opcional, Grupo recomendado"}, [50]={npc="Egan", tgt="Egan", tag="Opcional, Grupo recomendado"}, [51]={to="Altaforja"}}},
